/// Bubble sort — repeatedly swap adjacent out-of-order pairs; stop early once a pass makes no swap.
pub fn bubble_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    let mut out = xs.to_vec();
    let n = out.len();
    for end in (1..n).rev() {
        let mut swapped = false;
        for i in 0..end {
            if out[i] > out[i + 1] {
                out.swap(i, i + 1);
                swapped = true;
            }
        }
        if !swapped {
            break;
        }
    }
    out
}

/// Heap sort — build a max-heap in place, then swap the root to the end and re-sift the rest.
pub fn heap_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    fn sift_down<T: Ord>(a: &mut [T], start: usize, end: usize) {
        let mut root = start;
        loop {
            let left = 2 * root + 1;
            if left > end {
                return;
            }
            let right = left + 1;
            let mut largest = root;
            if a[largest] < a[left] {
                largest = left;
            }
            if right <= end && a[largest] < a[right] {
                largest = right;
            }
            if largest == root {
                return;
            }
            a.swap(root, largest);
            root = largest;
        }
    }
    let mut out = xs.to_vec();
    let n = out.len();
    if n < 2 {
        return out;
    }
    for start in (0..n / 2).rev() {
        sift_down(&mut out, start, n - 1);
    }
    for end in (1..n).rev() {
        out.swap(0, end);
        sift_down(&mut out, 0, end - 1);
    }
    out
}

/// Quick sort — partition around the first element, recurse each side.
pub fn quick_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    if xs.len() <= 1 {
        return xs.to_vec();
    }
    let pivot = xs[0].clone();
    let left: Vec<T> = xs[1..].iter().filter(|x| **x < pivot).cloned().collect();
    let right: Vec<T> = xs[1..].iter().filter(|x| **x >= pivot).cloned().collect();
    let mut out = quick_sort(&left);
    out.push(pivot);
    out.extend(quick_sort(&right));
    out
}

/// Binary search a sorted slice; `Some(index)` on a hit, else `None`.
pub fn binary_search<T: Ord>(xs: &[T], target: &T) -> Option<usize> {
    let (mut lo, mut hi) = (0, xs.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match xs[mid].cmp(target) {
            std::cmp::Ordering::Equal => return Some(mid),
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
        }
    }
    None
}

/// Linear search — the index of the first element equal to `target`, else `None`.
pub fn linear_search<T: PartialEq>(xs: &[T], target: &T) -> Option<usize> {
    xs.iter().position(|x| x == target)
}

/// The nth Fibonacci number (0-indexed: F0 = 0, F1 = 1), iterated bottom-up.
pub fn fibonacci(n: u64) -> u64 {
    if n < 2 {
        return n;
    }
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 2..=n {
        let next = a + b;
        a = b;
        b = next;
    }
    b
}

//! The `bsc teams` subcommand (#2193, renamed from `bsc org` in #2700 — `bsc org` remains a deprecated
//! alias) — the teams-specific shim over the shared verbatim-JSON-per-id store CLI
//! ([`bsc_json_store::cli`], #2158). The teams library (`~/.base-studio-code/orgs/<id>.json`) is
//! list/get/set/remove-able from a session's own shell — the same store the desktop Team designer
//! reads/writes and the planner can compose into (wire a fleet's positions + relationships).
//!
//! Dispatched by the unified `bsc` binary (#1877) via [`run`]; the shared per-command help (#1762):
//!   bsc teams help          # compact menu
//!   bsc teams get help      # detailed help for ONE command
//!
//! The store is located via `--dir <path>` or the `BSC_ORG_DIR` env var, defaulting to
//! `~/.base-studio-code/orgs/` — both KEPT unchanged (a rename would orphan existing saved data, #2700).

use bsc_cli_util::CmdDoc;
use bsc_json_store::cli::CliSpec;

const TAGLINE: &str = "the user teams store — list/get/set/remove ~/.base-studio-code/orgs (#2193/#2700)";

/// The crate's own verb catalog. `pub` so `bsc surface verbs` and the Glance crate drill can PROJECT
/// it rather than restate it — a generated catalog cannot drift, a second list does.
pub const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "list",
        summary: "every team's {id, name} (JSON)",
        usage: "\
