    fn help_overview_lists_the_verbs() {
        let ov = bsc_cli_util::help_overview("bsc usage", TAGLINE, COMMANDS);
        for c in ["record", "summary", "list", "clear"] {
            assert!(ov.contains(c), "overview lists {c}");
        }
    }
