    #[test]
    fn the_handoff_reserve_leaves_room_to_actually_write_one() {
        // One step for the model to answer, one of slack for a tool call it still owes. A reserve of
        // 1 would spend the whole allowance on the request and none on the reply.
        // A `const` block: the reserve is a compile-time invariant, so shrinking it to 1 fails the
        // BUILD rather than a test run. Clippy asks for this and it is the stronger guarantee.
        const { assert!(HANDOFF_RESERVE >= 2, "the reserve must leave room to answer") };
        assert!(!HANDOFF_PROMPT.trim().is_empty(), "the prompt says what it wants");
        assert!(HANDOFF_PROMPT.contains("Do not start anything new"), "and what it forbids");
    }

