    /// A repeat that returned something NEW was productive and must never count toward a refusal.
    #[test]
    fn a_repeat_that_returned_something_new_is_not_counted() {
        let cmd = serde_json::json!({"command": "git status"});
        let mut msgs = vec![Msg::User("go".into())];
        for (n, out) in ["1 file changed", "nothing to commit"].iter().enumerate() {
