        let line = describe_tool_result(ToolOutcome::Ok, "");
        assert!(line.contains("no output"), "{line}");
        assert!(line.contains("0 B"), "{line}");
    }

    #[test]
    fn the_outcome_is_carried_not_sniffed_from_the_text() {
        // `output.starts_with("error:")` would be a guess: a `bash` call whose COMMAND printed the
        // word is a SUCCESSFUL call, and labelling it a failure would be the same class of lie this
        // change exists to remove — just pointing the other way.
        let line = describe_tool_result(ToolOutcome::Ok, "error: npm test reported 2 failures");
        assert!(line.contains("ok"), "the CALL succeeded; its output is the program's: {line}");
        assert!(!line.contains("ERROR"), "{line}");
    }

    #[test]
    fn human_bytes_scales() {
        assert_eq!(human_bytes(0), "0 B");
        assert_eq!(human_bytes(78), "78 B");
