use serde_json::Value;

// The always-on dangerous-bash floor — catastrophic invocations denied for EVERY `bsc-agent` session,
// independent of the env-supplied [`Permissions`]. It now comes from the SHARED `bsc_util::dangerous`
// registry (#1844): the same canonical list the Claude harness renders as `Bash(<glob>)` deny rules
// renders here as substrings (`agent_dangerous_substrings`) — so neither harness can be talked into a
// `sudo` / `rm -rf /` / force-push by an empty or missing permission doc, and the two floors can't
// drift. Substring-matched (coarser than Claude's prefix rules) + deliberately conservative; the
// user's `deniedCommands` and the `bsc-taint` hook (#1167) cover the longer tail (curl|sh exfil, etc.).

/// The session's permission set. All-empty (the [`Default`]) is permissive.
#[derive(Debug, Default, Clone, Deserialize)]
pub struct Permissions {
    /// Tool names that may never run (e.g. `["bash"]` for a read-only role).
    #[serde(default)]
    pub deny_tools: Vec<String>,
    /// Substrings that, if present in a `bash` command, deny it (e.g. `["rm -rf", "git push"]`).
    #[serde(default)]
    pub deny_bash: Vec<String>,
    /// When non-empty, `write_file`/`edit_file` are allowed ONLY for paths matching one
    /// of these globs (e.g. `["src/**", "*.md"]`). Empty ⇒ no write-path restriction.
    #[serde(default)]
    pub write_globs: Vec<String>,
    /// The session's repo root (`$BSC_REPO_ROOT`). When non-empty, the file tools
    /// (`read_file`/`write_file`/`edit_file`) are confined to this subtree — the `bsc-agent`
    /// equivalent of the Claude `bsc-confine` PreToolUse hook (#158/#1916), mirroring
    /// `isPathConfined` in `src/shared/lib/session/fsConfine.ts` so both runtimes confine
    /// identically. Set from the environment in [`Permissions::from_env`], NOT from the perms
    /// JSON (`#[serde(skip)]`). Empty ⇒ no confinement (a bare CLI run where `$BSC_REPO_ROOT`
    /// is unset), preserving the permissive default.
    #[serde(skip)]
    pub repo_root: String,
    /// The session's read-only HARVEST roots (`$BSC_HARVEST_ROOTS`, newline-separated) — extra trees a
    /// `read_file` may reach even though they sit OUTSIDE `repo_root` (#3509/#3530). Mirrors the
    /// `bsc-confine` hook's Read allowance so the two runtimes confine identically: it widens only READS
    /// (`write_file`/`edit_file` stay confined), so a harvest root grants no write anywhere. Read from the
    /// environment in [`Permissions::from_env`], NOT the perms JSON (`#[serde(skip)]`). Empty ⇒ no extra
    /// reach, so behavior is identical to before the flag existed.
    #[serde(skip)]
    pub harvest_roots: Vec<String>,
}

impl Permissions {
    /// Load from `$BSC_AGENT_PERMS`: if it names an existing file, parse that file as
    /// JSON; otherwise parse the value itself as inline JSON. Unset / empty / unparseable
    /// ⇒ the permissive default.
    pub fn from_env() -> Permissions {
        let mut perms = match std::env::var("BSC_AGENT_PERMS") {
            Ok(v) if !v.trim().is_empty() => {
                // A path to a readable file wins; otherwise treat the value as inline JSON.
                let json = std::fs::read_to_string(&v).unwrap_or(v);
                serde_json::from_str(&json).unwrap_or_default()
            }
            _ => Permissions::default(),
        };
        // The confinement root is independent of the perms doc — read it from the env ALWAYS, so even
        // an unconfigured session (no `$BSC_AGENT_PERMS`) is still confined to its worktree (#1916).
        perms.repo_root = std::env::var("BSC_REPO_ROOT").unwrap_or_default();
        // Read-only harvest roots (#3530), newline-separated like the hook reads them.
        perms.harvest_roots = std::env::var("BSC_HARVEST_ROOTS")
            .unwrap_or_default()
            .lines()
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .collect();
        perms
    }

    /// Whether `tool_name` (with the model-supplied `args`) is permitted. `Err(reason)`
    /// is fed back to the model as the tool result so it can adapt — it is not a crash.
    /// Pure: no env / filesystem access.
    pub fn check(&self, tool_name: &str, args: &Value) -> Result<(), String> {
        if self.deny_tools.iter().any(|t| t == tool_name) {
            return Err(format!("permission denied: tool '{tool_name}' is not allowed"));
        }
        // FS confinement (#158/#1916): when a repo root is set, the file tools must stay within it —
        // mirrors the Claude `bsc-confine` hook + `fsConfine.ts` so the two runtimes confine identically.
        // Covers `read_file`/`write_file`/`edit_file` (the same tool set the Claude hook matches); `bash`
        // is the OS sandbox's job (a pure path check can't follow a subprocess), not gated here.
        if !self.repo_root.is_empty()
            && matches!(tool_name, "read_file" | "write_file" | "edit_file")
        {
            let path = args["path"].as_str().unwrap_or("");
            // #3530: a READ may reach a listed read-only harvest root even though it is outside the repo
            // root — mirrors the `bsc-confine` hook. Writes/edits stay confined (read-only widening).
            let harvest_read_ok =
                tool_name == "read_file" && under_any_harvest_root(&self.harvest_roots, path);
            if !path_confined(&self.repo_root, path) && !harvest_read_ok {
                return Err(format!(
                    "permission denied: '{path}' is outside the session's repo root ({}) — #158 FS confinement",
                    self.repo_root
                ));
            }
        }
        match tool_name {
            "bash" => {
                let cmd = args["command"].as_str().unwrap_or("");
                // The always-on floor first — denied for every session regardless of `deny_bash`.
                // #3948: `dangerous_match` skips heredoc bodies written by `cat`/`tee` so writing a
                // file that MENTIONS a dangerous command isn't treated as running one; a body fed to
                // an interpreter is still scanned.
                if bsc_util::dangerous::dangerous_match(cmd).is_some() {
                    return Err("permission denied: command matches the built-in dangerous-command denylist".into());
                }
                // #3483: program-name patterns match the PROGRAM token, not any substring of the
                // command — see `bsc_util::deny`. The floor above keeps `contains` on purpose.
                if self.deny_bash.iter().any(|p| bsc_util::deny::deny_matches(cmd, p.as_str())) {
                    return Err("permission denied: bash command matches a denied pattern".into());
                }
            }
            "write_file" | "edit_file" if !self.write_globs.is_empty() => {
                let path = args["path"].as_str().unwrap_or("");
                let allowed = self.write_globs.iter().any(|g| {
                    glob::Pattern::new(g).map(|pat| pat.matches(path)).unwrap_or(false)
                });
                if !allowed {
                    return Err(format!(
                        "permission denied: '{path}' is outside the allowed write paths"
                    ));
                }
            }
            _ => {}
        }
        Ok(())
    }
}

/// Whether a file-tool `target` stays within `root` — mirrors `isPathConfined` in
/// `src/shared/lib/session/fsConfine.ts` (#158) so the `bsc-agent` runtime and the Claude
/// `bsc-confine` hook confine identically: empty → confined; any `..` segment → NOT confined
/// (rejected conservatively, even within-repo); absolute path → confined only if under `root`;
/// plain relative → confined (resolved against the repo-root cwd). String-based, no realpath,
/// portable across OSes.
fn path_confined(root: &str, target: &str) -> bool {
    if target.is_empty() {
        return true;
    }
    let norm = target.replace('\\', "/");
    if norm.split('/').any(|seg| seg == "..") {
        return false;
    }
    if is_absolute(target) {
        let r = root.replace('\\', "/");
        let r = r.trim_end_matches('/');
        return norm == r || norm.starts_with(&format!("{r}/"));
    }
    true
}

/// Whether a `read_file` `target` sits under one of the read-only harvest roots (#3530) — mirrors
/// `isUnderHarvestRoot` in `fsConfine.ts` and the `__bsc_read_harvestable` shell helper. Same
/// conservatism as [`path_confined`]: only an ABSOLUTE path with no `..` segment, under a listed root
/// (a shared prefix is not containment). Empty roots contribute nothing.
fn under_any_harvest_root(roots: &[String], target: &str) -> bool {
    if target.is_empty() || !is_absolute(target) {
        return false;
    }
    let norm = target.replace('\\', "/");
    if norm.split('/').any(|seg| seg == "..") {
        return false;
    }
    roots.iter().any(|root| {
        if root.is_empty() {
            return false;
        }
        let r = root.replace('\\', "/");
        let r = r.trim_end_matches('/');
        norm == r || norm.starts_with(&format!("{r}/"))
    })
}

/// Absolute paths: POSIX (`/…`), home (`~…`), Windows drive (`C:…`), or UNC (`\\…`).
/// Mirrors `isAbsolute` in `fsConfine.ts`.
fn is_absolute(p: &str) -> bool {
    p.starts_with('/')
        || p.starts_with('~')
        || p.starts_with("\\\\")
        || (p.len() >= 2 && p.as_bytes()[0].is_ascii_alphabetic() && p.as_bytes()[1] == b':')
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn permissive_default_allows_ordinary_work() {
        // The default is permissive for everything EXCEPT the dangerous floor (asserted below):
        // ordinary commands, writes, and reads all pass with no configured permissions.
        let p = Permissions::default();
        assert!(p.check("bash", &json!({ "command": "cargo build" })).is_ok());
        assert!(p.check("write_file", &json!({ "path": "/etc/passwd" })).is_ok());
        assert!(p.check("read_file", &json!({ "path": "/anything" })).is_ok());
    }

    #[test]
    fn base_dangerous_floor_is_enforced_even_under_the_permissive_default() {
        // Parity with the Claude harness's always-on DEFAULT_DENY: an unconfigured session
        // (empty perms) still cannot run the catastrophic invocations.
        let p = Permissions::default();
        for cmd in [
            "sudo rm -rf /tmp/x",
            "rm -rf /",
            "rm -rf ~/work",
            "mkfs.ext4 /dev/sda",
            "git push --force origin main",
            "git push -f origin main",
        ] {
            assert!(p.check("bash", &json!({ "command": cmd })).is_err(), "should deny: {cmd}");
        }
        // Ordinary build/clean commands are unaffected (no false-positive on the floor).
        assert!(p.check("bash", &json!({ "command": "rm -rf target" })).is_ok());
        assert!(p.check("bash", &json!({ "command": "git push origin feat" })).is_ok());
    }

    #[test]
    fn deny_tools_blocks_the_named_tool() {
        let p = Permissions { deny_tools: vec!["bash".into()], ..Default::default() };
        assert!(p.check("bash", &json!({ "command": "ls" })).is_err());
        assert!(p.check("read_file", &json!({ "path": "x" })).is_ok());
    }

    #[test]
    fn deny_bash_matches_substring() {
        let p = Permissions { deny_bash: vec!["rm -rf".into(), "git push".into()], ..Default::default() };
        assert!(p.check("bash", &json!({ "command": "sudo rm -rf /tmp" })).is_err());
        assert!(p.check("bash", &json!({ "command": "git push origin main" })).is_err());
        assert!(p.check("bash", &json!({ "command": "ls -la" })).is_ok());
    }

    #[test]
    fn deny_bash_program_names_match_the_program_not_a_path_substring() {
        // #3483: a bare deny entry is a PROGRAM name. Substring-matching it denied `ed` inside
        // `shared/ui` and `vi` inside `Kevin` — every absolute path on some machines — which left a
        // confined session unable to run its own tooling.
        let p = Permissions {
            deny_bash: vec!["ed".into(), "vi".into(), "tee".into()],
            ..Default::default()
        };
        assert!(p.check("bash", &json!({ "command": "bsc ui harvest src/shared/ui" })).is_ok());
        assert!(p.check("bash", &json!({ "command": "ls C:/Users/Kevin/p" })).is_ok());
        assert!(p.check("bash", &json!({ "command": "vi notes.txt" })).is_err());
        assert!(p.check("bash", &json!({ "command": "cat a | tee b" })).is_err());
        assert!(p.check("bash", &json!({ "command": "sh -c \"tee out\"" })).is_err(), "no -c bypass");
    }

    #[test]
    fn write_globs_restrict_paths_when_set() {
        let p = Permissions { write_globs: vec!["src/**".into(), "*.md".into()], ..Default::default() };
        assert!(p.check("write_file", &json!({ "path": "src/lib.rs" })).is_ok());
        assert!(p.check("edit_file", &json!({ "path": "README.md" })).is_ok());
        assert!(p.check("write_file", &json!({ "path": "/etc/hosts" })).is_err());
        // read_file is never write-restricted.
        assert!(p.check("read_file", &json!({ "path": "/etc/hosts" })).is_ok());
    }

    #[test]
    fn empty_write_globs_means_no_write_restriction() {
        let p = Permissions::default();
        assert!(p.check("write_file", &json!({ "path": "/anywhere/x" })).is_ok());
    }

    #[test]
    fn repo_root_confines_the_file_tools() {
        // The bsc-agent mirror of the Claude `bsc-confine` hook (#158/#1916): file tools must stay
        // within $BSC_REPO_ROOT. In-repo relative + absolute-under-root pass...
        let p = Permissions { repo_root: "/work/repo".into(), ..Default::default() };
        assert!(p.check("read_file", &json!({ "path": "src/lib.rs" })).is_ok());
        assert!(p.check("write_file", &json!({ "path": "/work/repo/src/x.rs" })).is_ok());
        assert!(p.check("edit_file", &json!({ "path": "/work/repo" })).is_ok());
        // ...escapes are denied: `..` traversal, absolute outside the root, a sibling repo sharing a
        // path prefix, and home-relative paths.
        assert!(p.check("read_file", &json!({ "path": "../other/secret" })).is_err());
        assert!(p.check("write_file", &json!({ "path": "/etc/passwd" })).is_err());
        assert!(p.check("read_file", &json!({ "path": "/work/repo-sibling/x" })).is_err());
        assert!(p.check("edit_file", &json!({ "path": "~/.ssh/id_rsa" })).is_err());
        // a `..` anywhere is rejected even if it would resolve back inside the root.
        assert!(p.check("write_file", &json!({ "path": "src/../../escape" })).is_err());
        // bash is NOT path-confined here (the OS sandbox's job, not a pure check).
        assert!(p.check("bash", &json!({ "command": "cat ../other/secret" })).is_ok());
    }

    #[test]
    fn a_read_only_harvest_root_widens_reads_but_not_writes() {
        // #3530: the confined designer can Read the app's own source (its harvest root) even though it is
        // outside its repo root, so it can vendor the sibling files harvest doesn't surface — but writes
        // there stay blocked, preserving the read-only contract.
        let p = Permissions {
            repo_root: "/studio/design".into(),
            harvest_roots: vec!["/dev/base-studio-code".into(), "/other/repo".into()],
            ..Default::default()
        };
        // Read reaches either harvest root...
        assert!(p.check("read_file", &json!({ "path": "/dev/base-studio-code/src/shimmer.ts" })).is_ok());
        assert!(p.check("read_file", &json!({ "path": "/other/repo/x.ts" })).is_ok());
        // ...but Write/Edit into a harvest root is still confined (read-only widening).
        assert!(p.check("write_file", &json!({ "path": "/dev/base-studio-code/src/x.ts" })).is_err());
        assert!(p.check("edit_file", &json!({ "path": "/dev/base-studio-code/src/x.ts" })).is_err());
        // A Read outside BOTH the repo root and every harvest root is still denied, as is a prefix trap
        // and a `..` toward a real root.
        assert!(p.check("read_file", &json!({ "path": "/secrets/creds" })).is_err());
        assert!(p.check("read_file", &json!({ "path": "/dev/base-studio-code-2/x" })).is_err());
        assert!(p.check("read_file", &json!({ "path": "/dev/base-studio-code/../secrets" })).is_err());
    }

    #[test]
    fn no_harvest_roots_leaves_confinement_unchanged() {
        // Empty harvest_roots ⇒ byte-identical to before the flag: a read outside the repo root is denied.
        let p = Permissions { repo_root: "/work/repo".into(), ..Default::default() };
        assert!(p.check("read_file", &json!({ "path": "/dev/base-studio-code/src/x.ts" })).is_err());
    }

    #[test]
    fn no_repo_root_means_no_confinement() {
        // A bare CLI run (no $BSC_REPO_ROOT ⇒ empty repo_root) stays permissive.
        let p = Permissions::default();
        assert!(p.check("read_file", &json!({ "path": "/etc/passwd" })).is_ok());
        assert!(p.check("write_file", &json!({ "path": "../anywhere" })).is_ok());
    }

    #[test]
    fn confinement_composes_with_write_globs() {
        // Both gates apply (deny wins): inside the root AND matching a glob passes; inside the root
        // but outside the globs is denied by the glob check; outside the root is denied by confinement.
        let p = Permissions {
            repo_root: "/work/repo".into(),
            write_globs: vec!["src/**".into()],
            ..Default::default()
        };
        assert!(p.check("write_file", &json!({ "path": "src/a.rs" })).is_ok());
        assert!(p.check("write_file", &json!({ "path": "docs/a.md" })).is_err()); // glob
        assert!(p.check("write_file", &json!({ "path": "/etc/x" })).is_err());     // confinement
    }
}

implementations.code:
//! Native telemetry + transcript (epic #1078, P2d). `bsc-agent` emits the SAME
//! contracts the app already reads, so the existing audit view + cost accounting light
//! up unchanged (preserve the contract, swap the producer):
//!   - `audit.log`  TSV: `ts \t pane \t tool_name \t target`        (`$BSC_AUDIT_LOG`)
//!   - `tokens.log` TSV: `ts \t pane \t session_id \t transcript`   (`$BSC_TOKENS_LOG`)
//!   - a transcript JSONL whose assistant lines carry `message.model` + `message.usage`
//!     `{input_tokens, output_tokens, cache_creation_input_tokens, cache_read_input_tokens}`
//!     — exactly what `src-tauri/src/tokens.rs` parses.
//!
//! All emission is best-effort (a missing env var ⇒ no-op), like the `bsc-*` hooks.

use serde_json::Value;
use std::io::Write;
use std::path::PathBuf;

#[derive(Default)]
pub struct Telemetry {
    audit_log: Option<String>,
    tokens_log: Option<String>,
    pane: String,
    session_id: String,
    transcript_path: Option<PathBuf>,
}

impl Telemetry {
    /// Disabled telemetry — writes nothing (used by tests / non-instrumented runs).
    #[cfg(test)]
    pub fn disabled() -> Self {
        Telemetry::default()
    }

    /// Test constructor: a token-accounting Telemetry with explicit paths (no env).
    #[cfg(test)]
    pub(crate) fn for_test(tokens_log: Option<String>, transcript_path: Option<PathBuf>) -> Self {
        Telemetry {
            tokens_log,
            transcript_path,
            pane: "t0p1".into(),
            session_id: "test".into(),
            audit_log: None,
        }
    }

    /// Build from the per-session env the app sets in `pty_create`. Audit + token
    /// accounting are independently gated by their log-path vars being present.
    pub fn from_env() -> Self {
        let audit_log = std::env::var("BSC_AUDIT_LOG").ok().filter(|s| !s.is_empty());
        let tokens_log = std::env::var("BSC_TOKENS_LOG").ok().filter(|s| !s.is_empty());
        let pane = std::env::var("BSC_AUDIT_PANE").unwrap_or_else(|_| "?".into());
        let session_id = gen_session_id();
        let transcript_path = tokens_log.as_ref().map(|_| transcript_path_for(&session_id));
        Telemetry { audit_log, tokens_log, pane, session_id, transcript_path }
    }

    /// Append one audit line for an executed tool: `ts \t pane \t tool \t target`.
    pub fn audit(&self, tool_name: &str, args: &Value) {
        let Some(log) = &self.audit_log else { return };
        let line = format!("{}\t{}\t{}\t{}\n", utc_now(), self.pane, tool_name, audit_target(args));
        append(log, &line);
    }

    /// Append one assistant message to the transcript (the schema `tokens.rs` parses).
    pub fn record_assistant(&self, model: &str, usage: &Value) {
        let Some(path) = &self.transcript_path else { return };
        if let Some(parent) = path.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        let line = serde_json::json!({ "type": "assistant", "message": { "model": model, "usage": usage } });
        append(&path.to_string_lossy(), &format!("{line}\n"));
    }

    /// Record this session in `tokens.log` so the reader finds its transcript. Once per run.
    pub fn finish(&self) {
        let (Some(log), Some(path)) = (&self.tokens_log, &self.transcript_path) else { return };
        let line = format!(
            "{}\t{}\t{}\t{}\n",
            utc_now(),
            self.pane,
            self.session_id,
            path.to_string_lossy()
        );
        append(log, &line);
    }
}

/// The audit target: the first relevant arg field, tabs/newlines stripped, ≤160 chars
/// (mirrors the `bsc-audit` hook; `content` is deliberately excluded).
fn audit_target(args: &Value) -> String {
    for k in ["command", "file_path", "path", "url", "pattern"] {
        if let Some(s) = args.get(k).and_then(|v| v.as_str()) {
            return s.chars().map(|c| if c == '\t' || c == '\n' { ' ' } else { c }).take(160).collect();
        }
    }
    String::new()
}

fn append(path: &str, line: &str) {
    if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
        let _ = f.write_all(line.as_bytes());
    }
}

fn base_dir() -> PathBuf {
    // Shared resolver (#1646) so the agent writes under the SAME `~/.base-studio-code` the app +
    // CLIs use; an unset home falls back to the relative dir (the historical behavior).
    bsc_util::bsc_base_dir().unwrap_or_else(|| PathBuf::from(".base-studio-code"))
}

fn transcript_path_for(id: &str) -> PathBuf {
    base_dir().join("agent-sessions").join(format!("{id}.jsonl"))
}

fn gen_session_id() -> String {
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    format!("bsc-{nanos}-{}", std::process::id())
}

fn utc_now() -> String {
    // Shared civil-date formatter (#1646), so audit/cost timestamps match the `bsc-*` helpers'
    // `date -u +%Y-%m-%dT%H:%M:%SZ` output.
    bsc_util::epoch_ms_to_iso8601(bsc_util::now_ms())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn audit_target_picks_first_field_and_caps() {
        assert_eq!(audit_target(&serde_json::json!({ "command": "ls -la" })), "ls -la");
        assert_eq!(audit_target(&serde_json::json!({ "path": "a\tb\nc" })), "a b c");
        assert_eq!(audit_target(&serde_json::json!({ "content": "secret" })), ""); // content excluded
        let long = "x".repeat(300);
        assert_eq!(audit_target(&serde_json::json!({ "path": long })).chars().count(), 160);
    }

    #[test]
    fn audit_writes_tsv_line() {
        let dir = std::env::temp_dir().join(format!("bsc_p2d_audit_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let log = dir.join("audit.log").to_string_lossy().into_owned();
        let t = Telemetry { audit_log: Some(log.clone()), pane: "t0p1".into(), ..Default::default() };
        t.audit("bash", &serde_json::json!({ "command": "echo hi" }));
        let line = std::fs::read_to_string(&log).unwrap();
        let cols: Vec<&str> = line.trim_end().split('\t').collect();
        assert_eq!(cols.len(), 4);
        assert_eq!(cols[1], "t0p1");
        assert_eq!(cols[2], "bash");
        assert_eq!(cols[3], "echo hi");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn transcript_and_tokens_log_match_the_reader_schema() {
        let dir = std::env::temp_dir().join(format!("bsc_p2d_tx_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let tx = dir.join("session.jsonl");
        let tokens = dir.join("tokens.log").to_string_lossy().into_owned();
        let t = Telemetry {
            tokens_log: Some(tokens.clone()),
            pane: "t0p1".into(),
            session_id: "sess-1".into(),
            transcript_path: Some(tx.clone()),
            ..Default::default()
        };
        let usage = serde_json::json!({
            "input_tokens": 10, "output_tokens": 4,
            "cache_creation_input_tokens": 0, "cache_read_input_tokens": 0
        });
        t.record_assistant("claude-sonnet-4-6", &usage);
        t.finish();

        // Transcript line parses exactly like tokens.rs expects.
        let tl = std::fs::read_to_string(&tx).unwrap();
        let v: Value = serde_json::from_str(tl.trim()).unwrap();
        assert_eq!(v["message"]["model"], "claude-sonnet-4-6");
        assert_eq!(v["message"]["usage"]["input_tokens"], 10);
        assert_eq!(v["message"]["usage"]["output_tokens"], 4);
        assert!(v["message"]["usage"].get("cache_creation_input_tokens").is_some());
        assert!(v["message"]["usage"].get("cache_read_input_tokens").is_some());

        // tokens.log: ts \t pane \t session \t transcript_path
        let kl = std::fs::read_to_string(&tokens).unwrap();
        let cols: Vec<&str> = kl.trim_end().split('\t').collect();
        assert_eq!(cols.len(), 4);
        assert_eq!(cols[1], "t0p1");
        assert_eq!(cols[2], "sess-1");
        assert_eq!(cols[3], tx.to_string_lossy());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn disabled_telemetry_writes_nothing() {
        // No paths set ⇒ all ops are no-ops and must not panic.
        let t = Telemetry::disabled();
        t.audit("bash", &serde_json::json!({ "command": "x" }));
        t.record_assistant("m", &serde_json::json!({}));
        t.finish();
    }
}

tests.src:
//! Native telemetry + transcript (epic #1078, P2d). `bsc-agent` emits the SAME
//! contracts the app already reads, so the existing audit view + cost accounting light
//! up unchanged (preserve the contract, swap the producer):
//!   - `audit.log`  TSV: `ts \t pane \t tool_name \t target`        (`$BSC_AUDIT_LOG`)
//!   - `tokens.log` TSV: `ts \t pane \t session_id \t transcript`   (`$BSC_TOKENS_LOG`)
//!   - a transcript JSONL whose assistant lines carry `message.model` + `message.usage`
//!     `{input_tokens, output_tokens, cache_creation_input_tokens, cache_read_input_tokens}`
//!     — exactly what `src-tauri/src/tokens.rs` parses.
//!
//! All emission is best-effort (a missing env var ⇒ no-op), like the `bsc-*` hooks.

use serde_json::Value;
use std::io::Write;
use std::path::PathBuf;

#[derive(Default)]
pub struct Telemetry {
    audit_log: Option<String>,
    tokens_log: Option<String>,
    pane: String,
    session_id: String,
    transcript_path: Option<PathBuf>,
}

impl Telemetry {
    /// Disabled telemetry — writes nothing (used by tests / non-instrumented runs).
    #[cfg(test)]
    pub fn disabled() -> Self {
        Telemetry::default()
    }

    /// Test constructor: a token-accounting Telemetry with explicit paths (no env).
    #[cfg(test)]
    pub(crate) fn for_test(tokens_log: Option<String>, transcript_path: Option<PathBuf>) -> Self {
        Telemetry {
            tokens_log,
            transcript_path,
            pane: "t0p1".into(),
            session_id: "test".into(),
            audit_log: None,
        }
    }

    /// Build from the per-session env the app sets in `pty_create`. Audit + token
    /// accounting are independently gated by their log-path vars being present.
    pub fn from_env() -> Self {
        let audit_log = std::env::var("BSC_AUDIT_LOG").ok().filter(|s| !s.is_empty());
        let tokens_log = std::env::var("BSC_TOKENS_LOG").ok().filter(|s| !s.is_empty());
        let pane = std::env::var("BSC_AUDIT_PANE").unwrap_or_else(|_| "?".into());
        let session_id = gen_session_id();
        let transcript_path = tokens_log.as_ref().map(|_| transcript_path_for(&session_id));
        Telemetry { audit_log, tokens_log, pane, session_id, transcript_path }
    }

    /// Append one audit line for an executed tool: `ts \t pane \t tool \t target`.
    pub fn audit(&self, tool_name: &str, args: &Value) {
        let Some(log) = &self.audit_log else { return };
        let line = format!("{}\t{}\t{}\t{}\n", utc_now(), self.pane, tool_name, audit_target(args));
        append(log, &line);
    }

    /// Append one assistant message to the transcript (the schema `tokens.rs` parses).
    pub fn record_assistant(&self, model: &str, usage: &Value) {
        let Some(path) = &self.transcript_path else { return };
        if let Some(parent) = path.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        let line = serde_json::json!({ "type": "assistant", "message": { "model": model, "usage": usage } });
        append(&path.to_string_lossy(), &format!("{line}\n"));
    }

    /// Record this session in `tokens.log` so the reader finds its transcript. Once per run.
    pub fn finish(&self) {
        let (Some(log), Some(path)) = (&self.tokens_log, &self.transcript_path) else { return };
        let line = format!(
            "{}\t{}\t{}\t{}\n",
            utc_now(),
            self.pane,
            self.session_id,
            path.to_string_lossy()
        );
        append(log, &line);
    }
}

/// The audit target: the first relevant arg field, tabs/newlines stripped, ≤160 chars
/// (mirrors the `bsc-audit` hook; `content` is deliberately excluded).
fn audit_target(args: &Value) -> String {
    for k in ["command", "file_path", "path", "url", "pattern"] {
        if let Some(s) = args.get(k).and_then(|v| v.as_str()) {
            return s.chars().map(|c| if c == '\t' || c == '\n' { ' ' } else { c }).take(160).collect();
        }
    }
    String::new()
}

fn append(path: &str, line: &str) {
    if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
        let _ = f.write_all(line.as_bytes());
    }
}

fn base_dir() -> PathBuf {
    // Shared resolver (#1646) so the agent writes under the SAME `~/.base-studio-code` the app +
    // CLIs use; an unset home falls back to the relative dir (the historical behavior).
    bsc_util::bsc_base_dir().unwrap_or_else(|| PathBuf::from(".base-studio-code"))
}

fn transcript_path_for(id: &str) -> PathBuf {
    base_dir().join("agent-sessions").join(format!("{id}.jsonl"))
}

fn gen_session_id() -> String {
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    format!("bsc-{nanos}-{}", std::process::id())
}

fn utc_now() -> String {
    // Shared civil-date formatter (#1646), so audit/cost timestamps match the `bsc-*` helpers'
    // `date -u +%Y-%m-%dT%H:%M:%SZ` output.
    bsc_util::epoch_ms_to_iso8601(bsc_util::now_ms())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn audit_target_picks_first_field_and_caps() {
        assert_eq!(audit_target(&serde_json::json!({ "command": "ls -la" })), "ls -la");
        assert_eq!(audit_target(&serde_json::json!({ "path": "a\tb\nc" })), "a b c");
        assert_eq!(audit_target(&serde_json::json!({ "content": "secret" })), ""); // content excluded
        let long = "x".repeat(300);
        assert_eq!(audit_target(&serde_json::json!({ "path": long })).chars().count(), 160);
    }

    #[test]
    fn audit_writes_tsv_line() {
        let dir = std::env::temp_dir().join(format!("bsc_p2d_audit_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let log = dir.join("audit.log").to_string_lossy().into_owned();
        let t = Telemetry { audit_log: Some(log.clone()), pane: "t0p1".into(), ..Default::default() };
        t.audit("bash", &serde_json::json!({ "command": "echo hi" }));
        let line = std::fs::read_to_string(&log).unwrap();
        let cols: Vec<&str> = line.trim_end().split('\t').collect();
        assert_eq!(cols.len(), 4);
        assert_eq!(cols[1], "t0p1");
        assert_eq!(cols[2], "bash");
        assert_eq!(cols[3], "echo hi");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn transcript_and_tokens_log_match_the_reader_schema() {
        let dir = std::env::temp_dir().join(format!("bsc_p2d_tx_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let tx = dir.join("session.jsonl");
        let tokens = dir.join("tokens.log").to_string_lossy().into_owned();
        let t = Telemetry {
            tokens_log: Some(tokens.clone()),
            pane: "t0p1".into(),
            session_id: "sess-1".into(),
            transcript_path: Some(tx.clone()),
            ..Default::default()
        };
        let usage = serde_json::json!({
            "input_tokens": 10, "output_tokens": 4,
            "cache_creation_input_tokens": 0, "cache_read_input_tokens": 0
        });
        t.record_assistant("claude-sonnet-4-6", &usage);
        t.finish();

        // Transcript line parses exactly like tokens.rs expects.
        let tl = std::fs::read_to_string(&tx).unwrap();
        let v: Value = serde_json::from_str(tl.trim()).unwrap();
        assert_eq!(v["message"]["model"], "claude-sonnet-4-6");
        assert_eq!(v["message"]["usage"]["input_tokens"], 10);
        assert_eq!(v["message"]["usage"]["output_tokens"], 4);
        assert!(v["message"]["usage"].get("cache_creation_input_tokens").is_some());
        assert!(v["message"]["usage"].get("cache_read_input_tokens").is_some());

        // tokens.log: ts \t pane \t session \t transcript_path
        let kl = std::fs::read_to_string(&tokens).unwrap();
        let cols: Vec<&str> = kl.trim_end().split('\t').collect();
        assert_eq!(cols.len(), 4);
        assert_eq!(cols[1], "t0p1");
        assert_eq!(cols[2], "sess-1");
        assert_eq!(cols[3], tx.to_string_lossy());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn disabled_telemetry_writes_nothing() {
        // No paths set ⇒ all ops are no-ops and must not panic.
        let t = Telemetry::disabled();
        t.audit("bash", &serde_json::json!({ "command": "x" }));
        t.record_assistant("m", &serde_json::json!({}));
        t.finish();
    }
}

implementations.code:
//! The native tool builders every `bsc-agent` session is launched with — the file / shell / search /
//! web / delegation verbs (Claude Code tool-set parity, epic #1078). Each builder returns a [`Tool`]
//! (declaration + synchronous executor); the agent loop in [`crate::agent`] drives them. Split out of
//! `agent.rs` so the loop / compaction and the tool implementations live in separate modules.

use crate::agent::{run_agent, run_off_runtime, Tool};
use crate::permissions::Permissions;
use crate::telemetry::Telemetry;
use llm::{LlmProvider, ToolDef};
use serde_json::Value;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

/// Combine a finished process's stdout + stderr into one string, appending an `[exit N]` line on a
/// non-zero exit (a signal death renders as `[exit signal]`). Shared by the `bash` tool and the
/// `bsc-*` CLIs: a non-zero exit is NOT an error — the output is returned so the model can read it.
fn combine_output(output: &std::process::Output) -> String {
    let mut out = String::new();
    out.push_str(&String::from_utf8_lossy(&output.stdout));
    out.push_str(&String::from_utf8_lossy(&output.stderr));
    if !output.status.success() {
        let code = output.status.code().map(|c| c.to_string()).unwrap_or_else(|| "signal".into());
        out.push_str(&format!("\n[exit {code}]"));
    }
    out
}

/// The `read_file` tool: read a UTF-8 text file at `args.path`. One of the core
/// tools alongside write/edit/bash/grep/glob/webfetch (Claude Code tool-set parity).
pub fn read_file_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "read_file".into(),
            description: "Read a UTF-8 text file and return its contents.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": { "path": { "type": "string", "description": "path to the file" } },
                "required": ["path"]
            }),
        },
        run: Box::new(|args| {
            let path = args["path"].as_str().ok_or("missing 'path' argument")?;
            std::fs::read_to_string(path).map_err(|e| format!("read_file {path}: {e}"))
        }),
    }
}

/// The `write_file` tool: write (create/overwrite) a UTF-8 file, creating parent dirs.
pub fn write_file_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "write_file".into(),
            description: "Write a UTF-8 text file (creating or overwriting it), making parent directories as needed.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "path": { "type": "string", "description": "path to the file" },
                    "content": { "type": "string", "description": "full file contents to write" }
                },
                "required": ["path", "content"]
            }),
        },
        run: Box::new(|args| {
            let path = args["path"].as_str().ok_or("missing 'path' argument")?;
            let content = args["content"].as_str().ok_or("missing 'content' argument")?;
            if let Some(parent) = std::path::Path::new(path).parent() {
                if !parent.as_os_str().is_empty() {
                    std::fs::create_dir_all(parent).map_err(|e| format!("write_file {path}: {e}"))?;
                }
            }
            std::fs::write(path, content).map_err(|e| format!("write_file {path}: {e}"))?;
            Ok(format!("wrote {} bytes to {path}", content.len()))
        }),
    }
}

/// The `edit_file` tool: replace the first occurrence of `old_string` with `new_string`.
pub fn edit_file_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "edit_file".into(),
            description: "Replace the first occurrence of old_string with new_string in a UTF-8 file.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "path": { "type": "string", "description": "path to the file" },
                    "old_string": { "type": "string", "description": "exact text to find" },
                    "new_string": { "type": "string", "description": "replacement text" }
                },
                "required": ["path", "old_string", "new_string"]
            }),
        },
        run: Box::new(|args| {
            let path = args["path"].as_str().ok_or("missing 'path' argument")?;
            let old = args["old_string"].as_str().ok_or("missing 'old_string' argument")?;
            let new = args["new_string"].as_str().ok_or("missing 'new_string' argument")?;
            let body = std::fs::read_to_string(path).map_err(|e| format!("edit_file {path}: {e}"))?;
            if !body.contains(old) {
                return Err(format!("edit_file: old_string not found in {path}"));
            }
            std::fs::write(path, body.replacen(old, new, 1)).map_err(|e| format!("edit_file {path}: {e}"))?;
            Ok(format!("edited {path}"))
        }),
    }
}

/// Resolve a real `bash` for the `bash` tool. **Critical on Windows:** a bare `bash` on PATH
/// resolves to `C:\Windows\System32\bash.exe` — the WSL launcher — which fails with
/// `execvpe(/bin/bash): No such file or directory` when no WSL distro is installed. So prefer, in
/// order: `$BSC_AGENT_BASH` (the exact Git Bash the app's session shell runs under, set in
/// `wire_bsc_env`), then a real `$SHELL`, then a located Git Bash, before the bare `bash` fallback.
/// (Mirrors the app's `platform::shell::resolve_shell`; bsc-agent can't depend on `src-tauri`, so the
/// minimal Windows search is duplicated here to keep the standalone binary self-sufficient.)
fn resolve_bash() -> String {
    if let Ok(b) = std::env::var("BSC_AGENT_BASH") {
        let b = b.trim();
        if !b.is_empty() {
            return b.to_string();
        }
    }
    if let Ok(s) = std::env::var("SHELL") {
        if !s.is_empty() && std::path::Path::new(&s).exists() {
            return s;
        }
    }
    #[cfg(windows)]
    if let Some(b) = find_git_bash() {
        return b;
    }
    "bash".to_string()
}

/// Locate Git Bash's `bash.exe` (never WSL's System32 stub) under the common install roots. Windows
/// only; returns the first existing `bin\bash.exe` or `usr\bin\bash.exe`.
#[cfg(windows)]
fn find_git_bash() -> Option<String> {
    use std::path::PathBuf;
    let mut roots: Vec<PathBuf> = Vec::new();
    for var in ["ProgramFiles", "ProgramFiles(x86)", "ProgramW6432"] {
        if let Ok(p) = std::env::var(var) {
            roots.push(PathBuf::from(p).join("Git"));
        }
    }
    if let Ok(p) = std::env::var("LOCALAPPDATA") {
        roots.push(PathBuf::from(p).join("Programs").join("Git"));
    }
    roots.push(PathBuf::from(r"C:\Program Files\Git"));
    for root in roots {
        let bin = root.join("bin").join("bash.exe");
        if bin.exists() {
            return Some(bin.to_string_lossy().into_owned());
        }
        let usr = root.join("usr").join("bin").join("bash.exe");
        if usr.exists() {
            return Some(usr.to_string_lossy().into_owned());
        }
    }
    None
}

/// The `bash` tool: run a command with `bash -c` and return combined stdout+stderr.
/// A non-zero exit is NOT an error — the output (plus an `[exit N]` line) is returned
/// so the agent can read it; only a spawn failure is an `Err`.
pub fn bash_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "bash".into(),
            description: "Run a shell command with `bash -c` and return its combined stdout and stderr.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": { "command": { "type": "string", "description": "the shell command to run" } },
                "required": ["command"]
            }),
        },
        run: Box::new(|args| {
            let command = args["command"].as_str().ok_or("missing 'command' argument")?;
            let shell = resolve_bash();
            let output = std::process::Command::new(&shell)
                .arg("-c")
                .arg(command)
                .output()
                .map_err(|e| format!("bash: failed to spawn '{shell}': {e}"))?;
            Ok(combine_output(&output))
        }),
    }
}

/// Run a project `bsc-*` CLI by name via `bash -c "<cli> <args>"` (so the BASH_ENV shell function that
/// execs the staged sidecar is in scope), feeding `stdin` to it when provided. Returns combined
/// stdout+stderr (a non-zero exit is appended as `[exit N]`, not an error — the model reads it).
/// Shared by every [`bsc_cli_tool`]. (#qwen)
fn run_bsc_cli(cli: &str, args: &str, stdin: Option<&str>) -> Result<String, String> {
    use std::io::Write;
    use std::process::Stdio;
    let shell = resolve_bash();
    // EXEC THE BINARY BY PATH when we know it, instead of asking the shell to resolve the NAME.
    //
    // `bsc` is a staged sidecar at `~/.base-studio-code/bin/` and is deliberately on no PATH; inside
    // the app a shell-rc function covers that, and an EXTERNAL terminal has no rc. So `bash -c "bsc
    // plan list"` failed there with `command not found` — and since `available_clis` advertises these
    // tools whenever `$BSC_BIN` is set, the session would offer 22 tools that every one of which
    // fails. Advertising a capability that is not there is worse than not having it.
    let program = std::env::var("BSC_BIN")
        .ok()
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty() && cli == "bsc")
        // Single-quoted: a staged path can contain spaces, and this string is handed to `bash -c`.
        .map(|p| format!("'{}'", p.replace('\'', "'\\''")))
        .unwrap_or_else(|| cli.to_string());
    let line = if args.trim().is_empty() { program.clone() } else { format!("{program} {}", args.trim()) };
    let mut child = std::process::Command::new(&shell)
        .arg("-c")
        .arg(&line)
        .stdin(if stdin.is_some() { Stdio::piped() } else { Stdio::null() })
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| format!("{cli}: failed to spawn '{shell}': {e}"))?;
    if let Some(s) = stdin {
        if let Some(mut si) = child.stdin.take() {
            let _ = si.write_all(s.as_bytes());
        } // dropped here → EOF, so a CLI that reads stdin (e.g. `bsc-plan add`) doesn't hang
    }
    let output = child.wait_with_output().map_err(|e| format!("{cli}: {e}"))?;
    Ok(combine_output(&output))
}

#[cfg(test)]
mod bsc_bin_tests {
    /// Serialises the tests that mutate `$BSC_BIN`, which is PROCESS-GLOBAL.
    ///
    /// Both tests below `set_var` it, run a command, then restore it. Under `cargo nextest` each test
    /// gets its own PROCESS and cannot collide; under `cargo test` they are parallel threads in one
    /// process, and one restoring the variable while the other is mid-run makes that other one exec
    /// the wrong binary. It stayed latent until an unrelated change altered the thread schedule —
    /// which is the trouble with a latent race: the test that exposes it looks like the culprit.
    ///
    /// THE GATE RUNS NEXTEST, so it could never see this. Same shape and same reason as
    /// `testutil::ENV_LOCK`; poisoning is recovered so a panicking sibling cannot cascade.
    static BSC_BIN_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    /// The `bsc` CLI tools must reach a binary that is on NO PATH.
    ///
    /// `bsc` is a staged sidecar at `~/.base-studio-code/bin/`. Inside the app a shell-rc function
    /// resolves the name; an external terminal has no rc, so `bash -c "bsc plan list"` answered
    /// `command not found` — while `available_clis` had already advertised 22 tools on the strength of
    /// `$BSC_BIN` being set. Every one of them would have failed.
    #[test]
    fn the_bsc_tools_exec_the_binary_by_path_when_one_is_known() {
        let _guard = BSC_BIN_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let dir = std::env::temp_dir().join(format!("bsc-binpath-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        // A stand-in "bsc" that only works if it is invoked BY PATH — it is not on PATH.
        let fake = dir.join("bsc");
        std::fs::write(&fake, "#!/bin/sh\necho REACHED \"$@\"\n").unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&fake, std::fs::Permissions::from_mode(0o755)).unwrap();
        }
        let prev = std::env::var("BSC_BIN").ok();
        std::env::set_var("BSC_BIN", &fake);
        let out = super::run_bsc_cli("bsc", "plan summary", None).expect("runs");
        match prev {
            Some(v) => std::env::set_var("BSC_BIN", v),
            None => std::env::remove_var("BSC_BIN"),
        }
        let _ = std::fs::remove_dir_all(&dir);
        assert!(out.contains("REACHED"), "the binary was reached by path: {out:?}");
        assert!(out.contains("plan summary"), "and got its arguments: {out:?}");
    }

    /// With no `$BSC_BIN` it falls back to the bare name, which is what a PATH install wants.
    #[test]
    fn without_a_known_path_it_still_calls_the_bare_name() {
        let _guard = BSC_BIN_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let prev = std::env::var("BSC_BIN").ok();
        std::env::remove_var("BSC_BIN");
        // `true` is on PATH everywhere; the point is only that the bare-name path still runs.
        let out = super::run_bsc_cli("true", "", None);
        if let Some(v) = prev {
            std::env::set_var("BSC_BIN", v);
        }
        assert!(out.is_ok(), "the bare-name fallback still spawns: {out:?}");
    }
}

/// Pull the command-argument string + optional stdin out of a model's tool-call arguments, however it
/// shaped them — so a `bsc-*` tool runs like the normal command it is rather than depending on one
/// exact arg key (#qwen). A local model may pass the args under `args`/`command`/`cmd`/`argv`/
/// `subcommand`, as a string OR an argv array, or just splat positional values into the object; any of
/// those reconstructs the same command line. `stdin` (or `input`) pipes input for a write. Pure.
fn extract_cli_args(v: &Value) -> (String, Option<String>) {
    let stdin = ["stdin", "input"]
        .iter()
        .find_map(|k| v.get(*k).and_then(Value::as_str))
        .filter(|s| !s.is_empty())
        .map(str::to_string);
    // An explicit arguments field wins — as a string ("list --limit 5") or an argv array.
    for key in ["args", "arguments", "command", "cmd", "argv", "subcommand"] {
        match v.get(key) {
            Some(Value::String(s)) => return (s.trim().to_string(), stdin),
            Some(Value::Array(arr)) => {
                let joined = arr.iter().filter_map(Value::as_str).collect::<Vec<_>>().join(" ");
                return (joined.trim().to_string(), stdin);
            }
            _ => {}
        }
    }
    // Fallback: treat the object as positional args — join its scalar values (skipping the stdin
    // keys), so `{ "0": "list", "1": "--limit", "2": "5" }` or `{ "x": "summary" }` still runs.
    let positional: Vec<String> = v
        .as_object()
        .map(|o| {
            o.iter()
                .filter(|(k, _)| !matches!(k.as_str(), "stdin" | "input"))
                .filter_map(|(_, val)| match val {
                    Value::String(s) => Some(s.clone()),
                    Value::Number(n) => Some(n.to_string()),
                    Value::Bool(b) => Some(b.to_string()),
                    _ => None,
                })
                .collect()
        })
        .unwrap_or_default();
    (positional.join(" ").trim().to_string(), stdin)
}

/// A FIRST-CLASS tool for one `bsc <sub>` project CLI subcommand (#qwen / #1877). Local models (qwen
/// especially) call a CLI like `bsc-plan` as a *tool*, not via the `bash` tool — and then bounce off
/// "unknown tool" and give up. So we hand them the tool by a recognizable name `bsc-<sub>` (e.g.
/// `bsc-plan`): `args` is the CLI argument string (`"summary"`, `"list --status open"`), `stdin`
/// optionally pipes input (JSON for a write like `add`). It runs `bsc <sub> <args>` through bash (the
/// `bsc` shell helper execs the staged $BSC_BIN). Same intent-named-tool fix as `list_files`. Only
/// registered when the unified `bsc` binary is staged this session ($BSC_BIN set).
pub fn bsc_cli_tool(sub: &'static str) -> Tool {
    Tool {
        def: ToolDef {
            name: format!("bsc-{sub}"),
            description: format!(
                "Run the `bsc {sub}` project CLI. Put the CLI arguments in `args` (e.g. \"summary\" or \
                 \"list --limit 5\"); use `args: \"help\"` to see its commands, then `args: \"<command> help\"` \
                 for one command's args. Pipe input (e.g. JSON for a write) via `stdin`. Equivalent to \
                 running `bsc {sub} <args>` in the shell."
            ),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "args": { "type": "string", "description": "the CLI arguments, e.g. \"summary\" or \"list --limit 5\" (empty runs the subcommand with no args — its help/overview)" },
                    "stdin": { "type": "string", "description": "optional text piped to the command's stdin (e.g. JSON for a write command)" }
                }
            }),
        },
        run: Box::new(move |args| {
            // Tolerant of however the model shaped the call, so it runs like the normal command it is.
            let (a, stdin) = extract_cli_args(args);
            // Run via the unified binary: `bsc <sub> <args>` (the `bsc` shell helper execs $BSC_BIN).
            let full = if a.is_empty() { sub.to_string() } else { format!("{sub} {a}") };
            run_bsc_cli("bsc", &full, stdin.as_deref())
        }),
    }
}

/// Recursively collect the files under `root` (a directory), or just `root` itself
/// when it is a file. Best-effort: unreadable entries are skipped. Used by `grep`.
fn collect_files(root: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
    if root.is_file() {
        out.push(root.to_path_buf());
        return;
    }
    let Ok(entries) = std::fs::read_dir(root) else { return };
    for entry in entries.flatten() {
        let path = entry.path();
        // Skip the usual heavy / noise directories so a repo-root grep stays useful.
        if path.is_dir() {
            let skip = matches!(
                path.file_name().and_then(|n| n.to_str()),
                Some(".git" | "node_modules" | "target" | "dist" | ".vite")
            );
            if !skip {
                collect_files(&path, out);
            }
        } else if path.is_file() {
            out.push(path);
        }
    }
}

/// The `grep` tool: search file contents for a regular expression and return the
/// matching lines as `path:line:text`. Mirrors Claude Code's Grep so weak models get
/// a first-class search verb instead of improvising `bash` pipelines (#1442).
pub fn grep_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "grep".into(),
            description: "Search file contents for a regular expression. Returns matching lines as `path:line:text`. `path` defaults to the current directory and may be a file or a directory (searched recursively, skipping .git/node_modules/target/dist).".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "pattern": { "type": "string", "description": "the regular expression to search for" },
                    "path": { "type": "string", "description": "file or directory to search (default: current directory)" }
                },
                "required": ["pattern"]
            }),
        },
        run: Box::new(|args| {
            let pattern = args["pattern"].as_str().ok_or("missing 'pattern' argument")?;
            let path = args["path"].as_str().unwrap_or(".");
            let re = regex::Regex::new(pattern).map_err(|e| format!("grep: invalid pattern: {e}"))?;
            let mut files = Vec::new();
            collect_files(std::path::Path::new(path), &mut files);
            const MAX_MATCHES: usize = 500;
            let mut matches = Vec::new();
            let mut truncated = false;
            'outer: for file in files {
                // Non-UTF-8 / binary files are skipped silently (read_to_string fails).
                let Ok(body) = std::fs::read_to_string(&file) else { continue };
                for (i, line) in body.lines().enumerate() {
                    if re.is_match(line) {
                        if matches.len() >= MAX_MATCHES {
                            truncated = true;
                            break 'outer;
                        }
                        matches.push(format!("{}:{}:{}", file.display(), i + 1, line));
                    }
                }
            }
            if matches.is_empty() {
                return Ok("no matches".into());
            }
            let mut out = matches.join("\n");
            if truncated {
                out.push_str(&format!("\n[truncated at {MAX_MATCHES} matches]"));
            }
            Ok(out)
        }),
    }
}

/// The `glob` tool: list filesystem paths matching a glob pattern (e.g. `src/**/*.rs`),
/// newest first is not guaranteed — paths are returned in glob order. Gives weak models
/// a first-class file-discovery verb (#1442).
pub fn glob_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "glob".into(),
            description: "List files matching a glob pattern (e.g. `src/**/*.rs`). Returns one path per line.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "pattern": { "type": "string", "description": "the glob pattern, e.g. `**/*.toml`" }
                },
                "required": ["pattern"]
            }),
        },
        run: Box::new(|args| {
            let pattern = args["pattern"].as_str().ok_or("missing 'pattern' argument")?;
            let paths = glob::glob(pattern).map_err(|e| format!("glob: invalid pattern: {e}"))?;
            const MAX: usize = 1000;
            let mut out = Vec::new();
            let mut truncated = false;
            for p in paths.flatten() {
                if out.len() >= MAX {
                    truncated = true;
                    break;
                }
                out.push(p.display().to_string());
            }
            if out.is_empty() {
                return Ok("no matches".into());
            }
            let mut joined = out.join("\n");
            if truncated {
                joined.push_str(&format!("\n[truncated at {MAX} paths]"));
            }
            Ok(joined)
        }),
    }
}

/// The `webfetch` tool: HTTP GET a URL and return the response body as text. Runs the
/// blocking request on a dedicated OS thread because the agent loop executes tools
/// inline on a tokio worker, and reqwest::blocking panics if started inside a runtime.
pub fn webfetch_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "webfetch".into(),
            description: "HTTP GET a URL and return the response body as text. Output is capped; non-2xx responses are returned with an `[http N]` prefix.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "url": { "type": "string", "description": "the absolute http(s) URL to fetch" }
                },
                "required": ["url"]
            }),
        },
        run: Box::new(|args| {
            let url = args["url"].as_str().ok_or("missing 'url' argument")?.to_string();
            let body = run_off_runtime(move || -> Result<String, String> {
                let client = reqwest::blocking::Client::builder()
                    .user_agent("bsc-agent")
                    .build()
                    .map_err(|e| format!("webfetch: client: {e}"))?;
                let resp = client.get(&url).send().map_err(|e| format!("webfetch {url}: {e}"))?;
                let status = resp.status();
                let text = resp.text().map_err(|e| format!("webfetch {url}: {e}"))?;
                if status.is_success() {
                    Ok(text)
                } else {
                    Ok(format!("[http {}]\n{text}", status.as_u16()))
                }
            })?;
            // Char-safe cap (never split a UTF-8 boundary).
            const MAX_CHARS: usize = 100_000;
            if body.chars().count() > MAX_CHARS {
                let mut capped: String = body.chars().take(MAX_CHARS).collect();
                capped.push_str("\n[truncated]");
                Ok(capped)
            } else {
                Ok(body)
            }
        }),
    }
}

/// Max sub-agent nesting depth. A `task` tool built at depth `d` refuses to spawn when
/// `d >= MAX_TASK_DEPTH` — the root tool set is depth 0, so this permits `MAX_TASK_DEPTH`
/// levels of delegation (director → sub-agent → sub-sub-agent) before the backstop trips.
const MAX_TASK_DEPTH: usize = 2;
/// Process-wide cap on the total number of sub-agents spawned in one run — a backstop
/// against a model fanning out unboundedly. Never reset (one process = one agent run).
const MAX_TASK_CHILDREN: usize = 32;
/// Step budget for a sub-agent loop (mirrors the root loop's 20).
const MAX_TASK_STEPS: usize = 20;
/// Prepended to the inherited project context so a delegated child knows its remit.
const TASK_SYSTEM_PREFIX: &str = "You are a sub-agent spawned to complete one focused task. Work autonomously with the tools available and return your final answer as plain text when you are done.\n\n";

static TASK_CHILDREN_SPAWNED: AtomicUsize = AtomicUsize::new(0);

/// The native tool builders every `bsc-agent` session is launched with — the file/shell/search/web
/// verbs as one registry (#1846), so adding a verb is one line here. `list_files`/`file_info` are
/// FIRST-CLASS, INTENT-NAMED tools (backed by the `bsc-files` LIBRARY in-process — no subprocess, no
/// binary-path fragility) because a local model reaches for "list/show the files" and kept inventing
/// `*_list` names when nothing matched — clearly-named tools it calls as reliably as MCP tools (the
/// prose-only hint didn't work, and a single args-string tool got fumbled).
pub(crate) const NATIVE_TOOL_BUILDERS: &[fn() -> Tool] = &[
    read_file_tool,
    write_file_tool,
    edit_file_tool,
    bash_tool,
    grep_tool,
    glob_tool,
    webfetch_tool,
    list_files_tool,
    file_info_tool,
];

/// The standard tool set every `bsc-agent` session (root or sub-agent) is launched with: the native
/// [`NATIVE_TOOL_BUILDERS`] verbs plus a [`task_tool`] for delegation. The provider / model /
/// permissions are threaded through so the `task` tool can spawn a child loop on the same provider
/// under the same (no broader) grants. `depth` is the caller's nesting level (0 at the root); the
/// child receives `depth + 1`.
pub fn default_tools<P: LlmProvider + Send + Sync + 'static>(
    provider: Arc<P>,
    api_key: String,
    model: String,
    system: String,
    perms: Permissions,
    depth: usize,
) -> Vec<Tool> {
    let mut tools: Vec<Tool> = NATIVE_TOOL_BUILDERS.iter().map(|b| b()).collect();
    tools.push(task_tool(provider, api_key, model, system, perms, depth));
    tools
}

/// `list_files` — the project's folder structure with file sizes/counts/language (gitignore-aware),
/// rendered from `bsc_files::build_tree`. The model's natural "list/show the files" verb.
pub(crate) fn list_files_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "list_files".into(),
            description: "List the project's files and folders under a path — each file's size and language, each directory's aggregate size and file count. The fast way to understand the codebase layout; respects .gitignore. Use this instead of guessing at the structure.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "path": { "type": "string", "description": "directory to list, relative to the project root (default \".\")" },
                    "depth": { "type": "integer", "description": "limit the tree to this many levels (optional)" }
                }
            }),
        },
        run: Box::new(|args| {
            let rel = args["path"].as_str().filter(|s| !s.is_empty()).unwrap_or(".");
            let depth = args["depth"].as_u64().map(|d| d as usize);
            let base = std::env::current_dir().map_err(|e| format!("list_files: cwd: {e}"))?.join(rel);
            let node = bsc_files::build_tree(&base, &bsc_files::TreeOpts::default())?;
            let mut out = bsc_files::render_tree(&node, depth);
            out.push_str(&format!("\n{} files, {}", node.files, bsc_files::human_size(node.size)));
            Ok(out)
        }),
    }
}

/// `file_info` — size, language, and line count for one path, from `bsc_files::stat`.
pub(crate) fn file_info_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "file_info".into(),
            description: "Report a single file or directory's size, language, and line count.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": { "path": { "type": "string", "description": "the file or directory, relative to the project root" } },
                "required": ["path"]
            }),
        },
        run: Box::new(|args| {
            let rel = args["path"].as_str().ok_or("file_info: missing 'path'")?;
            let base = std::env::current_dir().map_err(|e| format!("file_info: cwd: {e}"))?.join(rel);
            Ok(bsc_files::stat(&base, true)?.lean())
        }),
    }
}

/// The `task` tool: delegate a focused sub-task to a child agent loop. The child runs the
/// SAME provider/model under the SAME [`Permissions`] (a sub-agent can never exceed its
/// parent's grants — the permission set is passed through unchanged), with a fresh
/// conversation that is not persisted, and returns its final text as the tool result.
///
/// Two backstops bound runaway delegation: a per-call depth check ([`MAX_TASK_DEPTH`]) and
/// a process-wide child counter ([`MAX_TASK_CHILDREN`]).
///
/// The child loop is async but the agent runs tools inline on a tokio worker, so the child
/// runs on a dedicated OS thread with its own current-thread runtime — `block_on` inside
/// the parent runtime would panic (mirrors `webfetch`'s blocking isolation).
pub fn task_tool<P: LlmProvider + Send + Sync + 'static>(
    provider: Arc<P>,
    api_key: String,
    model: String,
    system: String,
    perms: Permissions,
    depth: usize,
) -> Tool {
    Tool {
        def: ToolDef {
            name: "task".into(),
            description: "Delegate a focused, self-contained sub-task to a sub-agent. The sub-agent runs its own tool-using loop under the same permissions and returns its final answer as text. Use it to hand off independent work (research, a contained edit, a verification pass).".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "prompt": { "type": "string", "description": "the task for the sub-agent to complete, with all the context it needs" }
                },
                "required": ["prompt"]
            }),
        },
        run: Box::new(move |args| {
            let prompt = args["prompt"].as_str().ok_or("missing 'prompt' argument")?.to_string();
            if depth >= MAX_TASK_DEPTH {
                return Err(format!(
                    "task: max sub-agent depth ({MAX_TASK_DEPTH}) reached — handle this work directly"
                ));
            }
            if TASK_CHILDREN_SPAWNED.fetch_add(1, Ordering::SeqCst) >= MAX_TASK_CHILDREN {
                return Err(format!("task: max sub-agent count ({MAX_TASK_CHILDREN}) reached"));
            }
            // Clone the captured session config for the child (the closure is `Fn`, so it
            // may run many times — each spawns its own child).
            let provider = Arc::clone(&provider);
            let (api_key, model, perms) = (api_key.clone(), model.clone(), perms.clone());
            let system = format!("{TASK_SYSTEM_PREFIX}{system}");
            run_off_runtime(move || -> Result<String, String> {
                let rt = tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                    .map_err(|e| format!("task: runtime: {e}"))?;
                rt.block_on(async {
                    // The child gets its own telemetry session (own id + transcript) writing to
                    // the SAME log files, so the nested run is visible to the app's readers.
                    let tele = Telemetry::from_env();
                    let child_tools = default_tools(
                        Arc::clone(&provider),
                        api_key.clone(),
                        model.clone(),
                        system.clone(),
                        perms.clone(),
                        depth + 1,
                    );
                    run_agent(
                        &*provider, &api_key, &model, &system, &prompt, &child_tools, &perms, &tele,
                        &[], None, MAX_TASK_STEPS, false, // sub-agent: one-shot, never reads stdin
                    )
                    .await
                })
            })
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use llm::{LlmProvider, LlmRequest, ToolCall, Turn, TurnResult};
    use std::sync::atomic::{AtomicUsize, Ordering};

    #[test]
    fn extract_cli_args_handles_the_shapes_a_local_model_uses() {
        use serde_json::json;
        let go = |v| super::extract_cli_args(&v);
        // The documented shape.
        assert_eq!(go(json!({ "args": "summary" })), ("summary".to_string(), None));
        // Alternate arg keys, an argv array, and stdin for a write.
        assert_eq!(go(json!({ "command": "list --limit 5" })).0, "list --limit 5");
        assert_eq!(go(json!({ "argv": ["list", "--status", "open"] })).0, "list --status open");
        assert_eq!(go(json!({ "args": "add", "stdin": "[{}]" })), ("add".to_string(), Some("[{}]".to_string())));
        // Positional splat fallback (sorted keys "0","1" → "fleet get").
        assert_eq!(go(json!({ "0": "fleet", "1": "get" })).0, "fleet get");
        // Empty → runs the CLI bare (its help/overview).
        assert_eq!(go(json!({})), (String::new(), None));
    }

    #[test]
    fn bsc_cli_tool_is_named_after_the_cli_and_takes_args_plus_stdin() {
        // qwen calls `bsc-plan` as a tool; we register the `plan` subcommand by the recognizable name
        // `bsc-plan` so the call resolves instead of bouncing as "unknown tool". args + stdin let it
        // run any subcommand (incl. writes); under the hood it execs `bsc plan <args>` (#1877).
        let t = bsc_cli_tool("plan");
        assert_eq!(t.def.name, "bsc-plan");
        assert!(t.def.description.contains("bsc plan"));
        assert!(t.def.description.contains("help"), "points the model at the CLI's own help");
        let props = &t.def.schema["properties"];
        assert!(props.get("args").is_some(), "exposes an args string");
        assert!(props.get("stdin").is_some(), "exposes an optional stdin");
    }

    #[test]
    fn file_structure_tools_are_named_and_run() {
        let lf = list_files_tool();
        assert_eq!(lf.def.name, "list_files");
        let fi = file_info_tool();
        assert_eq!(fi.def.name, "file_info");
        // list_files runs against the cwd (the crate dir under test) and returns a tree + summary.
        let out = (lf.run)(&serde_json::json!({ "path": ".", "depth": 1 })).unwrap();
        assert!(out.contains("files,"), "summary line present: {out}");
        // file_info on a missing path is a clean Err fed back to the model, not a panic.
        assert!((fi.run)(&serde_json::json!({ "path": "definitely-not-a-real-file-xyz" })).is_err());
    }

    #[test]
    fn write_file_creates_and_writes() {
        let path = std::env::temp_dir().join(format!("bsc_p2b_write_{}.txt", std::process::id()));
        let p = path.to_string_lossy().into_owned();
        let msg = (write_file_tool().run)(&serde_json::json!({ "path": p, "content": "hi there" })).unwrap();
        assert!(msg.contains("wrote"));
        assert_eq!(std::fs::read_to_string(&path).unwrap(), "hi there");
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn edit_file_replaces_first_then_errors_when_absent() {
        let path = std::env::temp_dir().join(format!("bsc_p2b_edit_{}.txt", std::process::id()));
        std::fs::write(&path, "foo bar foo").unwrap();
        let p = path.to_string_lossy().into_owned();
        let tool = edit_file_tool();
        let msg = (tool.run)(&serde_json::json!({ "path": &p, "old_string": "foo", "new_string": "baz" })).unwrap();
        assert!(msg.contains("edited"));
        assert_eq!(std::fs::read_to_string(&path).unwrap(), "baz bar foo"); // first occurrence only
        let err = (tool.run)(&serde_json::json!({ "path": &p, "old_string": "zzz", "new_string": "x" })).unwrap_err();
        assert!(err.contains("not found"));
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn resolve_bash_prefers_app_provided_path() {
        // The app hands the runtime the exact Git Bash via $BSC_AGENT_BASH; it wins over everything
        // (so the `bash` tool never falls through to the Windows WSL launcher). Unique value so the
        // assertion is unambiguous even though env is process-global.
        std::env::set_var("BSC_AGENT_BASH", "/opt/from-app/bash");
        assert_eq!(resolve_bash(), "/opt/from-app/bash");
        // Trimmed + empty is treated as unset (falls through, not returned blank).
        std::env::set_var("BSC_AGENT_BASH", "   ");
        assert_ne!(resolve_bash(), "");
        std::env::remove_var("BSC_AGENT_BASH");
    }

    #[test]
    fn bash_runs_command() {
        // Tolerant: `bash` may be absent or shadowed (e.g. by WSL) in CI/dev. Verify the
        // happy path when a working bash is present; otherwise skip rather than flake.
        match (bash_tool().run)(&serde_json::json!({ "command": "echo hello" })) {
            Ok(out) if out.contains("hello") => {} // a working bash → behavior verified
            Ok(out) => eprintln!("skipping bash assert (bash misconfigured here): {out:?}"),
            Err(e) => eprintln!("skipping bash test (bash unavailable): {e}"),
        }
    }

    #[test]
    fn grep_finds_matching_lines_with_path_and_line() {
        let dir = std::env::temp_dir().join(format!("bsc_grep_{}", std::process::id()));
        let _ = std::fs::create_dir_all(&dir);
        std::fs::write(dir.join("a.txt"), "alpha\nNEEDLE here\nbeta").unwrap();
        std::fs::write(dir.join("b.txt"), "nothing relevant").unwrap();
        let out = (grep_tool().run)(&serde_json::json!({
            "pattern": "NEEDLE",
            "path": dir.to_string_lossy(),
        }))
        .unwrap();
        assert!(out.contains("a.txt"), "names the matching file: {out}");
        assert!(out.contains(":2:"), "reports the 1-based line number: {out}");
        assert!(out.contains("NEEDLE here"));
        // A pattern that matches nothing returns the sentinel, not an error.
        let none = (grep_tool().run)(&serde_json::json!({
            "pattern": "zzz_absent",
            "path": dir.to_string_lossy(),
        }))
        .unwrap();
        assert_eq!(none, "no matches");
        // An invalid regex is an Err fed back to the model, not a crash.
        assert!((grep_tool().run)(&serde_json::json!({ "pattern": "[", "path": "." })).is_err());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn glob_lists_matching_paths() {
        let dir = std::env::temp_dir().join(format!("bsc_glob_{}", std::process::id()));
        let _ = std::fs::create_dir_all(&dir);
        std::fs::write(dir.join("keep.rs"), "").unwrap();
        std::fs::write(dir.join("skip.txt"), "").unwrap();
        let pat = format!("{}/*.rs", dir.to_string_lossy());
        let out = (glob_tool().run)(&serde_json::json!({ "pattern": pat })).unwrap();
        assert!(out.contains("keep.rs"));
        assert!(!out.contains("skip.txt"));
        let none = (glob_tool().run)(&serde_json::json!({
            "pattern": format!("{}/*.never", dir.to_string_lossy()),
        }))
        .unwrap();
        assert_eq!(none, "no matches");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn webfetch_validates_args_without_network() {
        // Missing `url` is a clean Err (no thread spawn / no network), so this stays
        // offline-safe in CI. The happy path is exercised by the parity smoke (#1444).
        assert!((webfetch_tool().run)(&serde_json::json!({})).is_err());
    }

    /// A `Sync` scripted provider for the `task` tests (the real `Arc<P>` capture in
    /// `task_tool` needs `P: Send + Sync`). Each `turn` is driven purely by an atomic call
    /// counter: turn 1 optionally emits one tool call, every later turn returns final text.
    struct ScriptedProvider {
        calls: AtomicUsize,
        first_call: Option<ToolCall>,
        final_text: String,
    }
    impl ScriptedProvider {
        fn finishing(text: &str) -> Self {
            ScriptedProvider { calls: AtomicUsize::new(0), first_call: None, final_text: text.into() }
        }
        fn calling(tc: ToolCall, then: &str) -> Self {
            ScriptedProvider { calls: AtomicUsize::new(0), first_call: Some(tc), final_text: then.into() }
        }
    }
    impl LlmProvider for ScriptedProvider {
        async fn complete(&self, _r: &LlmRequest, _k: &str) -> Result<serde_json::Value, String> {
            unreachable!()
        }
        async fn turn(&self, _t: &Turn, _k: &str) -> Result<TurnResult, String> {
            let n = self.calls.fetch_add(1, Ordering::SeqCst);
            let tool_calls = match (n, &self.first_call) {
                (0, Some(tc)) => vec![tc.clone()],
                _ => vec![],
            };
            let text = if tool_calls.is_empty() { self.final_text.clone() } else { String::new() };
            Ok(TurnResult { text, tool_calls, usage: serde_json::Value::Null, stop_reason: "x".into() })
        }
    }

    #[test]
    fn task_refuses_at_max_depth_without_spawning() {
        // A tool built at the depth limit must reject immediately (no thread / no provider call).
        let provider = Arc::new(ScriptedProvider::finishing("unused"));
        let tool = task_tool(provider, String::new(), "m".into(), String::new(), Permissions::default(), MAX_TASK_DEPTH);
        let err = (tool.run)(&serde_json::json!({ "prompt": "do it" })).unwrap_err();
        assert!(err.contains("max sub-agent depth"), "got: {err}");
    }

    #[test]
    fn task_delegates_and_returns_child_final_text() {
        // The child finishes on its first turn; the tool returns that text verbatim.
        let provider = Arc::new(ScriptedProvider::finishing("sub-agent answer"));
        let tool = task_tool(provider, String::new(), "m".into(), String::new(), Permissions::default(), 0);
        let out = (tool.run)(&serde_json::json!({ "prompt": "summarize" })).unwrap();
        assert_eq!(out, "sub-agent answer");
    }

    #[test]
    fn sub_agent_inherits_parent_permission_denies() {
        // The child is given the parent's perms (bash denied). It scripts a `bash` that would
        // create a sentinel file; the inherited deny must block execution, so the file never
        // appears even though the child loop runs to completion.
        let sentinel = std::env::temp_dir().join(format!("bsc_task_perm_{}.flag", std::process::id()));
        let _ = std::fs::remove_file(&sentinel);
        let bash = ToolCall {
            id: "t1".into(),
            name: "bash".into(),
            args: serde_json::json!({ "command": format!("touch {}", sentinel.display()) }),
        };
        let provider = Arc::new(ScriptedProvider::calling(bash, "done"));
        let perms = Permissions { deny_tools: vec!["bash".into()], ..Default::default() };
        let tool = task_tool(provider, String::new(), "m".into(), String::new(), perms, 0);
        let out = (tool.run)(&serde_json::json!({ "prompt": "run it" })).unwrap();
        assert_eq!(out, "done");
        assert!(!sentinel.exists(), "denied bash must not have executed in the sub-agent");
        let _ = std::fs::remove_file(&sentinel);
    }
}

tests.src:
//! The native tool builders every `bsc-agent` session is launched with — the file / shell / search /
//! web / delegation verbs (Claude Code tool-set parity, epic #1078). Each builder returns a [`Tool`]
//! (declaration + synchronous executor); the agent loop in [`crate::agent`] drives them. Split out of
//! `agent.rs` so the loop / compaction and the tool implementations live in separate modules.

use crate::agent::{run_agent, run_off_runtime, Tool};
use crate::permissions::Permissions;
use crate::telemetry::Telemetry;
use llm::{LlmProvider, ToolDef};
use serde_json::Value;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

/// Combine a finished process's stdout + stderr into one string, appending an `[exit N]` line on a
/// non-zero exit (a signal death renders as `[exit signal]`). Shared by the `bash` tool and the
/// `bsc-*` CLIs: a non-zero exit is NOT an error — the output is returned so the model can read it.
fn combine_output(output: &std::process::Output) -> String {
    let mut out = String::new();
    out.push_str(&String::from_utf8_lossy(&output.stdout));
    out.push_str(&String::from_utf8_lossy(&output.stderr));
    if !output.status.success() {
        let code = output.status.code().map(|c| c.to_string()).unwrap_or_else(|| "signal".into());
        out.push_str(&format!("\n[exit {code}]"));
    }
    out
}

/// The `read_file` tool: read a UTF-8 text file at `args.path`. One of the core
/// tools alongside write/edit/bash/grep/glob/webfetch (Claude Code tool-set parity).
pub fn read_file_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "read_file".into(),
            description: "Read a UTF-8 text file and return its contents.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": { "path": { "type": "string", "description": "path to the file" } },
                "required": ["path"]
            }),
        },
        run: Box::new(|args| {
            let path = args["path"].as_str().ok_or("missing 'path' argument")?;
            std::fs::read_to_string(path).map_err(|e| format!("read_file {path}: {e}"))
        }),
    }
}

/// The `write_file` tool: write (create/overwrite) a UTF-8 file, creating parent dirs.
pub fn write_file_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "write_file".into(),
            description: "Write a UTF-8 text file (creating or overwriting it), making parent directories as needed.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "path": { "type": "string", "description": "path to the file" },
                    "content": { "type": "string", "description": "full file contents to write" }
                },
                "required": ["path", "content"]
            }),
        },
        run: Box::new(|args| {
            let path = args["path"].as_str().ok_or("missing 'path' argument")?;
            let content = args["content"].as_str().ok_or("missing 'content' argument")?;
            if let Some(parent) = std::path::Path::new(path).parent() {
                if !parent.as_os_str().is_empty() {
                    std::fs::create_dir_all(parent).map_err(|e| format!("write_file {path}: {e}"))?;
                }
            }
            std::fs::write(path, content).map_err(|e| format!("write_file {path}: {e}"))?;
            Ok(format!("wrote {} bytes to {path}", content.len()))
        }),
    }
}

/// The `edit_file` tool: replace the first occurrence of `old_string` with `new_string`.
pub fn edit_file_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "edit_file".into(),
            description: "Replace the first occurrence of old_string with new_string in a UTF-8 file.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "path": { "type": "string", "description": "path to the file" },
                    "old_string": { "type": "string", "description": "exact text to find" },
                    "new_string": { "type": "string", "description": "replacement text" }
                },
                "required": ["path", "old_string", "new_string"]
            }),
        },
        run: Box::new(|args| {
            let path = args["path"].as_str().ok_or("missing 'path' argument")?;
            let old = args["old_string"].as_str().ok_or("missing 'old_string' argument")?;
            let new = args["new_string"].as_str().ok_or("missing 'new_string' argument")?;
            let body = std::fs::read_to_string(path).map_err(|e| format!("edit_file {path}: {e}"))?;
            if !body.contains(old) {
                return Err(format!("edit_file: old_string not found in {path}"));
            }
            std::fs::write(path, body.replacen(old, new, 1)).map_err(|e| format!("edit_file {path}: {e}"))?;
            Ok(format!("edited {path}"))
        }),
    }
}

/// Resolve a real `bash` for the `bash` tool. **Critical on Windows:** a bare `bash` on PATH
/// resolves to `C:\Windows\System32\bash.exe` — the WSL launcher — which fails with
/// `execvpe(/bin/bash): No such file or directory` when no WSL distro is installed. So prefer, in
/// order: `$BSC_AGENT_BASH` (the exact Git Bash the app's session shell runs under, set in
/// `wire_bsc_env`), then a real `$SHELL`, then a located Git Bash, before the bare `bash` fallback.
/// (Mirrors the app's `platform::shell::resolve_shell`; bsc-agent can't depend on `src-tauri`, so the
/// minimal Windows search is duplicated here to keep the standalone binary self-sufficient.)
fn resolve_bash() -> String {
    if let Ok(b) = std::env::var("BSC_AGENT_BASH") {
        let b = b.trim();
        if !b.is_empty() {
            return b.to_string();
        }
    }
    if let Ok(s) = std::env::var("SHELL") {
        if !s.is_empty() && std::path::Path::new(&s).exists() {
            return s;
        }
    }
    #[cfg(windows)]
    if let Some(b) = find_git_bash() {
        return b;
    }
    "bash".to_string()
}

/// Locate Git Bash's `bash.exe` (never WSL's System32 stub) under the common install roots. Windows
/// only; returns the first existing `bin\bash.exe` or `usr\bin\bash.exe`.
#[cfg(windows)]
fn find_git_bash() -> Option<String> {
    use std::path::PathBuf;
    let mut roots: Vec<PathBuf> = Vec::new();
    for var in ["ProgramFiles", "ProgramFiles(x86)", "ProgramW6432"] {
        if let Ok(p) = std::env::var(var) {
            roots.push(PathBuf::from(p).join("Git"));
        }
    }
    if let Ok(p) = std::env::var("LOCALAPPDATA") {
        roots.push(PathBuf::from(p).join("Programs").join("Git"));
    }
    roots.push(PathBuf::from(r"C:\Program Files\Git"));
    for root in roots {
        let bin = root.join("bin").join("bash.exe");
        if bin.exists() {
            return Some(bin.to_string_lossy().into_owned());
        }
        let usr = root.join("usr").join("bin").join("bash.exe");
        if usr.exists() {
            return Some(usr.to_string_lossy().into_owned());
        }
    }
    None
}

/// The `bash` tool: run a command with `bash -c` and return combined stdout+stderr.
/// A non-zero exit is NOT an error — the output (plus an `[exit N]` line) is returned
/// so the agent can read it; only a spawn failure is an `Err`.
pub fn bash_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "bash".into(),
            description: "Run a shell command with `bash -c` and return its combined stdout and stderr.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": { "command": { "type": "string", "description": "the shell command to run" } },
                "required": ["command"]
            }),
        },
        run: Box::new(|args| {
            let command = args["command"].as_str().ok_or("missing 'command' argument")?;
            let shell = resolve_bash();
            let output = std::process::Command::new(&shell)
                .arg("-c")
                .arg(command)
                .output()
                .map_err(|e| format!("bash: failed to spawn '{shell}': {e}"))?;
            Ok(combine_output(&output))
        }),
    }
}

/// Run a project `bsc-*` CLI by name via `bash -c "<cli> <args>"` (so the BASH_ENV shell function that
/// execs the staged sidecar is in scope), feeding `stdin` to it when provided. Returns combined
/// stdout+stderr (a non-zero exit is appended as `[exit N]`, not an error — the model reads it).
/// Shared by every [`bsc_cli_tool`]. (#qwen)
fn run_bsc_cli(cli: &str, args: &str, stdin: Option<&str>) -> Result<String, String> {
    use std::io::Write;
    use std::process::Stdio;
    let shell = resolve_bash();
    let line = if args.trim().is_empty() { cli.to_string() } else { format!("{cli} {}", args.trim()) };
    let mut child = std::process::Command::new(&shell)
        .arg("-c")
        .arg(&line)
        .stdin(if stdin.is_some() { Stdio::piped() } else { Stdio::null() })
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| format!("{cli}: failed to spawn '{shell}': {e}"))?;
    if let Some(s) = stdin {
        if let Some(mut si) = child.stdin.take() {
            let _ = si.write_all(s.as_bytes());
        } // dropped here → EOF, so a CLI that reads stdin (e.g. `bsc-plan add`) doesn't hang
    }
    let output = child.wait_with_output().map_err(|e| format!("{cli}: {e}"))?;
    Ok(combine_output(&output))
}

/// Pull the command-argument string + optional stdin out of a model's tool-call arguments, however it
/// shaped them — so a `bsc-*` tool runs like the normal command it is rather than depending on one
/// exact arg key (#qwen). A local model may pass the args under `args`/`command`/`cmd`/`argv`/
/// `subcommand`, as a string OR an argv array, or just splat positional values into the object; any of
/// those reconstructs the same command line. `stdin` (or `input`) pipes input for a write. Pure.
fn extract_cli_args(v: &Value) -> (String, Option<String>) {
    let stdin = ["stdin", "input"]
        .iter()
        .find_map(|k| v.get(*k).and_then(Value::as_str))
        .filter(|s| !s.is_empty())
        .map(str::to_string);
    // An explicit arguments field wins — as a string ("list --limit 5") or an argv array.
    for key in ["args", "arguments", "command", "cmd", "argv", "subcommand"] {
        match v.get(key) {
            Some(Value::String(s)) => return (s.trim().to_string(), stdin),
            Some(Value::Array(arr)) => {
                let joined = arr.iter().filter_map(Value::as_str).collect::<Vec<_>>().join(" ");
                return (joined.trim().to_string(), stdin);
            }
            _ => {}
        }
    }
    // Fallback: treat the object as positional args — join its scalar values (skipping the stdin
    // keys), so `{ "0": "list", "1": "--limit", "2": "5" }` or `{ "x": "summary" }` still runs.
    let positional: Vec<String> = v
        .as_object()
        .map(|o| {
            o.iter()
                .filter(|(k, _)| !matches!(k.as_str(), "stdin" | "input"))
                .filter_map(|(_, val)| match val {
                    Value::String(s) => Some(s.clone()),
                    Value::Number(n) => Some(n.to_string()),
                    Value::Bool(b) => Some(b.to_string()),
                    _ => None,
                })
                .collect()
        })
        .unwrap_or_default();
    (positional.join(" ").trim().to_string(), stdin)
}

/// A FIRST-CLASS tool for one `bsc <sub>` project CLI subcommand (#qwen / #1877). Local models (qwen
/// especially) call a CLI like `bsc-plan` as a *tool*, not via the `bash` tool — and then bounce off
/// "unknown tool" and give up. So we hand them the tool by a recognizable name `bsc-<sub>` (e.g.
/// `bsc-plan`): `args` is the CLI argument string (`"summary"`, `"list --status open"`), `stdin`
/// optionally pipes input (JSON for a write like `add`). It runs `bsc <sub> <args>` through bash (the
/// `bsc` shell helper execs the staged $BSC_BIN). Same intent-named-tool fix as `list_files`. Only
/// registered when the unified `bsc` binary is staged this session ($BSC_BIN set).
pub fn bsc_cli_tool(sub: &'static str) -> Tool {
    Tool {
        def: ToolDef {
            name: format!("bsc-{sub}"),
            description: format!(
                "Run the `bsc {sub}` project CLI. Put the CLI arguments in `args` (e.g. \"summary\" or \
                 \"list --limit 5\"); use `args: \"help\"` to see its commands, then `args: \"<command> help\"` \
                 for one command's args. Pipe input (e.g. JSON for a write) via `stdin`. Equivalent to \
                 running `bsc {sub} <args>` in the shell."
            ),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "args": { "type": "string", "description": "the CLI arguments, e.g. \"summary\" or \"list --limit 5\" (empty runs the subcommand with no args — its help/overview)" },
                    "stdin": { "type": "string", "description": "optional text piped to the command's stdin (e.g. JSON for a write command)" }
                }
            }),
        },
        run: Box::new(move |args| {
            // Tolerant of however the model shaped the call, so it runs like the normal command it is.
            let (a, stdin) = extract_cli_args(args);
            // Run via the unified binary: `bsc <sub> <args>` (the `bsc` shell helper execs $BSC_BIN).
            let full = if a.is_empty() { sub.to_string() } else { format!("{sub} {a}") };
            run_bsc_cli("bsc", &full, stdin.as_deref())
        }),
    }
}

/// Recursively collect the files under `root` (a directory), or just `root` itself
/// when it is a file. Best-effort: unreadable entries are skipped. Used by `grep`.
fn collect_files(root: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
    if root.is_file() {
        out.push(root.to_path_buf());
        return;
    }
    let Ok(entries) = std::fs::read_dir(root) else { return };
    for entry in entries.flatten() {
        let path = entry.path();
        // Skip the usual heavy / noise directories so a repo-root grep stays useful.
        if path.is_dir() {
            let skip = matches!(
                path.file_name().and_then(|n| n.to_str()),
                Some(".git" | "node_modules" | "target" | "dist" | ".vite")
            );
            if !skip {
                collect_files(&path, out);
            }
        } else if path.is_file() {
            out.push(path);
        }
    }
}

/// The `grep` tool: search file contents for a regular expression and return the
/// matching lines as `path:line:text`. Mirrors Claude Code's Grep so weak models get
/// a first-class search verb instead of improvising `bash` pipelines (#1442).
pub fn grep_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "grep".into(),
            description: "Search file contents for a regular expression. Returns matching lines as `path:line:text`. `path` defaults to the current directory and may be a file or a directory (searched recursively, skipping .git/node_modules/target/dist).".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "pattern": { "type": "string", "description": "the regular expression to search for" },
                    "path": { "type": "string", "description": "file or directory to search (default: current directory)" }
                },
                "required": ["pattern"]
            }),
        },
        run: Box::new(|args| {
            let pattern = args["pattern"].as_str().ok_or("missing 'pattern' argument")?;
            let path = args["path"].as_str().unwrap_or(".");
            let re = regex::Regex::new(pattern).map_err(|e| format!("grep: invalid pattern: {e}"))?;
            let mut files = Vec::new();
            collect_files(std::path::Path::new(path), &mut files);
            const MAX_MATCHES: usize = 500;
            let mut matches = Vec::new();
            let mut truncated = false;
            'outer: for file in files {
                // Non-UTF-8 / binary files are skipped silently (read_to_string fails).
                let Ok(body) = std::fs::read_to_string(&file) else { continue };
                for (i, line) in body.lines().enumerate() {
                    if re.is_match(line) {
                        if matches.len() >= MAX_MATCHES {
                            truncated = true;
                            break 'outer;
                        }
                        matches.push(format!("{}:{}:{}", file.display(), i + 1, line));
                    }
                }
            }
            if matches.is_empty() {
                return Ok("no matches".into());
            }
            let mut out = matches.join("\n");
            if truncated {
                out.push_str(&format!("\n[truncated at {MAX_MATCHES} matches]"));
            }
            Ok(out)
        }),
    }
}

/// The `glob` tool: list filesystem paths matching a glob pattern (e.g. `src/**/*.rs`),
/// newest first is not guaranteed — paths are returned in glob order. Gives weak models
/// a first-class file-discovery verb (#1442).
pub fn glob_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "glob".into(),
            description: "List files matching a glob pattern (e.g. `src/**/*.rs`). Returns one path per line.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "pattern": { "type": "string", "description": "the glob pattern, e.g. `**/*.toml`" }
                },
                "required": ["pattern"]
            }),
        },
        run: Box::new(|args| {
            let pattern = args["pattern"].as_str().ok_or("missing 'pattern' argument")?;
            let paths = glob::glob(pattern).map_err(|e| format!("glob: invalid pattern: {e}"))?;
            const MAX: usize = 1000;
            let mut out = Vec::new();
            let mut truncated = false;
            for p in paths.flatten() {
                if out.len() >= MAX {
                    truncated = true;
                    break;
                }
                out.push(p.display().to_string());
            }
            if out.is_empty() {
                return Ok("no matches".into());
            }
            let mut joined = out.join("\n");
            if truncated {
                joined.push_str(&format!("\n[truncated at {MAX} paths]"));
            }
            Ok(joined)
        }),
    }
}

/// The `webfetch` tool: HTTP GET a URL and return the response body as text. Runs the
/// blocking request on a dedicated OS thread because the agent loop executes tools
/// inline on a tokio worker, and reqwest::blocking panics if started inside a runtime.
pub fn webfetch_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "webfetch".into(),
            description: "HTTP GET a URL and return the response body as text. Output is capped; non-2xx responses are returned with an `[http N]` prefix.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "url": { "type": "string", "description": "the absolute http(s) URL to fetch" }
                },
                "required": ["url"]
            }),
        },
        run: Box::new(|args| {
            let url = args["url"].as_str().ok_or("missing 'url' argument")?.to_string();
            let body = run_off_runtime(move || -> Result<String, String> {
                let client = reqwest::blocking::Client::builder()
                    .user_agent("bsc-agent")
                    .build()
                    .map_err(|e| format!("webfetch: client: {e}"))?;
                let resp = client.get(&url).send().map_err(|e| format!("webfetch {url}: {e}"))?;
                let status = resp.status();
                let text = resp.text().map_err(|e| format!("webfetch {url}: {e}"))?;
                if status.is_success() {
                    Ok(text)
                } else {
                    Ok(format!("[http {}]\n{text}", status.as_u16()))
                }
            })?;
            // Char-safe cap (never split a UTF-8 boundary).
            const MAX_CHARS: usize = 100_000;
            if body.chars().count() > MAX_CHARS {
                let mut capped: String = body.chars().take(MAX_CHARS).collect();
                capped.push_str("\n[truncated]");
                Ok(capped)
            } else {
                Ok(body)
            }
        }),
    }
}

/// Max sub-agent nesting depth. A `task` tool built at depth `d` refuses to spawn when
/// `d >= MAX_TASK_DEPTH` — the root tool set is depth 0, so this permits `MAX_TASK_DEPTH`
/// levels of delegation (director → sub-agent → sub-sub-agent) before the backstop trips.
const MAX_TASK_DEPTH: usize = 2;
/// Process-wide cap on the total number of sub-agents spawned in one run — a backstop
/// against a model fanning out unboundedly. Never reset (one process = one agent run).
const MAX_TASK_CHILDREN: usize = 32;
/// Step budget for a sub-agent loop (mirrors the root loop's 20).
const MAX_TASK_STEPS: usize = 20;
/// Prepended to the inherited project context so a delegated child knows its remit.
const TASK_SYSTEM_PREFIX: &str = "You are a sub-agent spawned to complete one focused task. Work autonomously with the tools available and return your final answer as plain text when you are done.\n\n";

static TASK_CHILDREN_SPAWNED: AtomicUsize = AtomicUsize::new(0);

/// The native tool builders every `bsc-agent` session is launched with — the file/shell/search/web
/// verbs as one registry (#1846), so adding a verb is one line here. `list_files`/`file_info` are
/// FIRST-CLASS, INTENT-NAMED tools (backed by the `bsc-files` LIBRARY in-process — no subprocess, no
/// binary-path fragility) because a local model reaches for "list/show the files" and kept inventing
/// `*_list` names when nothing matched — clearly-named tools it calls as reliably as MCP tools (the
/// prose-only hint didn't work, and a single args-string tool got fumbled).
pub(crate) const NATIVE_TOOL_BUILDERS: &[fn() -> Tool] = &[
    read_file_tool,
    write_file_tool,
    edit_file_tool,
    bash_tool,
    grep_tool,
    glob_tool,
    webfetch_tool,
    list_files_tool,
    file_info_tool,
];

/// The standard tool set every `bsc-agent` session (root or sub-agent) is launched with: the native
/// [`NATIVE_TOOL_BUILDERS`] verbs plus a [`task_tool`] for delegation. The provider / model /
/// permissions are threaded through so the `task` tool can spawn a child loop on the same provider
/// under the same (no broader) grants. `depth` is the caller's nesting level (0 at the root); the
/// child receives `depth + 1`.
pub fn default_tools<P: LlmProvider + Send + Sync + 'static>(
    provider: Arc<P>,
    api_key: String,
    model: String,
    system: String,
    perms: Permissions,
    depth: usize,
) -> Vec<Tool> {
    let mut tools: Vec<Tool> = NATIVE_TOOL_BUILDERS.iter().map(|b| b()).collect();
    tools.push(task_tool(provider, api_key, model, system, perms, depth));
    tools
}

/// `list_files` — the project's folder structure with file sizes/counts/language (gitignore-aware),
/// rendered from `bsc_files::build_tree`. The model's natural "list/show the files" verb.
pub(crate) fn list_files_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "list_files".into(),
            description: "List the project's files and folders under a path — each file's size and language, each directory's aggregate size and file count. The fast way to understand the codebase layout; respects .gitignore. Use this instead of guessing at the structure.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "path": { "type": "string", "description": "directory to list, relative to the project root (default \".\")" },
                    "depth": { "type": "integer", "description": "limit the tree to this many levels (optional)" }
                }
            }),
        },
        run: Box::new(|args| {
            let rel = args["path"].as_str().filter(|s| !s.is_empty()).unwrap_or(".");
            let depth = args["depth"].as_u64().map(|d| d as usize);
            let base = std::env::current_dir().map_err(|e| format!("list_files: cwd: {e}"))?.join(rel);
            let node = bsc_files::build_tree(&base, &bsc_files::TreeOpts::default())?;
            let mut out = bsc_files::render_tree(&node, depth);
            out.push_str(&format!("\n{} files, {}", node.files, bsc_files::human_size(node.size)));
            Ok(out)
        }),
    }
}

/// `file_info` — size, language, and line count for one path, from `bsc_files::stat`.
pub(crate) fn file_info_tool() -> Tool {
    Tool {
        def: ToolDef {
            name: "file_info".into(),
            description: "Report a single file or directory's size, language, and line count.".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": { "path": { "type": "string", "description": "the file or directory, relative to the project root" } },
                "required": ["path"]
            }),
        },
        run: Box::new(|args| {
            let rel = args["path"].as_str().ok_or("file_info: missing 'path'")?;
            let base = std::env::current_dir().map_err(|e| format!("file_info: cwd: {e}"))?.join(rel);
            Ok(bsc_files::stat(&base, true)?.lean())
        }),
    }
}

/// The `task` tool: delegate a focused sub-task to a child agent loop. The child runs the
/// SAME provider/model under the SAME [`Permissions`] (a sub-agent can never exceed its
/// parent's grants — the permission set is passed through unchanged), with a fresh
/// conversation that is not persisted, and returns its final text as the tool result.
///
/// Two backstops bound runaway delegation: a per-call depth check ([`MAX_TASK_DEPTH`]) and
/// a process-wide child counter ([`MAX_TASK_CHILDREN`]).
///
/// The child loop is async but the agent runs tools inline on a tokio worker, so the child
/// runs on a dedicated OS thread with its own current-thread runtime — `block_on` inside
/// the parent runtime would panic (mirrors `webfetch`'s blocking isolation).
pub fn task_tool<P: LlmProvider + Send + Sync + 'static>(
    provider: Arc<P>,
    api_key: String,
    model: String,
    system: String,
    perms: Permissions,
    depth: usize,
) -> Tool {
    Tool {
        def: ToolDef {
            name: "task".into(),
            description: "Delegate a focused, self-contained sub-task to a sub-agent. The sub-agent runs its own tool-using loop under the same permissions and returns its final answer as text. Use it to hand off independent work (research, a contained edit, a verification pass).".into(),
            schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "prompt": { "type": "string", "description": "the task for the sub-agent to complete, with all the context it needs" }
                },
                "required": ["prompt"]
            }),
        },
        run: Box::new(move |args| {
            let prompt = args["prompt"].as_str().ok_or("missing 'prompt' argument")?.to_string();
            if depth >= MAX_TASK_DEPTH {
                return Err(format!(
                    "task: max sub-agent depth ({MAX_TASK_DEPTH}) reached — handle this work directly"
                ));
            }
            if TASK_CHILDREN_SPAWNED.fetch_add(1, Ordering::SeqCst) >= MAX_TASK_CHILDREN {
                return Err(format!("task: max sub-agent count ({MAX_TASK_CHILDREN}) reached"));
            }
            // Clone the captured session config for the child (the closure is `Fn`, so it
            // may run many times — each spawns its own child).
            let provider = Arc::clone(&provider);
            let (api_key, model, perms) = (api_key.clone(), model.clone(), perms.clone());
            let system = format!("{TASK_SYSTEM_PREFIX}{system}");
            run_off_runtime(move || -> Result<String, String> {
                let rt = tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                    .map_err(|e| format!("task: runtime: {e}"))?;
                rt.block_on(async {
                    // The child gets its own telemetry session (own id + transcript) writing to
                    // the SAME log files, so the nested run is visible to the app's readers.
                    let tele = Telemetry::from_env();
                    let child_tools = default_tools(
                        Arc::clone(&provider),
                        api_key.clone(),
                        model.clone(),
                        system.clone(),
                        perms.clone(),
                        depth + 1,
                    );
                    run_agent(
                        &*provider, &api_key, &model, &system, &prompt, &child_tools, &perms, &tele,
                        &[], None, MAX_TASK_STEPS, false, // sub-agent: one-shot, never reads stdin
                    )
                    .await
                })
            })
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use llm::{LlmProvider, LlmRequest, ToolCall, Turn, TurnResult};
    use std::sync::atomic::{AtomicUsize, Ordering};

    #[test]
    fn extract_cli_args_handles_the_shapes_a_local_model_uses() {
        use serde_json::json;
        let go = |v| super::extract_cli_args(&v);
        // The documented shape.
        assert_eq!(go(json!({ "args": "summary" })), ("summary".to_string(), None));
        // Alternate arg keys, an argv array, and stdin for a write.
        assert_eq!(go(json!({ "command": "list --limit 5" })).0, "list --limit 5");
        assert_eq!(go(json!({ "argv": ["list", "--status", "open"] })).0, "list --status open");
        assert_eq!(go(json!({ "args": "add", "stdin": "[{}]" })), ("add".to_string(), Some("[{}]".to_string())));
        // Positional splat fallback (sorted keys "0","1" → "fleet get").
        assert_eq!(go(json!({ "0": "fleet", "1": "get" })).0, "fleet get");
        // Empty → runs the CLI bare (its help/overview).
        assert_eq!(go(json!({})), (String::new(), None));
    }

    #[test]
    fn bsc_cli_tool_is_named_after_the_cli_and_takes_args_plus_stdin() {
        // qwen calls `bsc-plan` as a tool; we register the `plan` subcommand by the recognizable name
        // `bsc-plan` so the call resolves instead of bouncing as "unknown tool". args + stdin let it
        // run any subcommand (incl. writes); under the hood it execs `bsc plan <args>` (#1877).
        let t = bsc_cli_tool("plan");
        assert_eq!(t.def.name, "bsc-plan");
        assert!(t.def.description.contains("bsc plan"));
        assert!(t.def.description.contains("help"), "points the model at the CLI's own help");
        let props = &t.def.schema["properties"];
        assert!(props.get("args").is_some(), "exposes an args string");
        assert!(props.get("stdin").is_some(), "exposes an optional stdin");
    }

    #[test]
    fn file_structure_tools_are_named_and_run() {
        let lf = list_files_tool();
        assert_eq!(lf.def.name, "list_files");
        let fi = file_info_tool();
        assert_eq!(fi.def.name, "file_info");
        // list_files runs against the cwd (the crate dir under test) and returns a tree + summary.
        let out = (lf.run)(&serde_json::json!({ "path": ".", "depth": 1 })).unwrap();
        assert!(out.contains("files,"), "summary line present: {out}");
        // file_info on a missing path is a clean Err fed back to the model, not a panic.
        assert!((fi.run)(&serde_json::json!({ "path": "definitely-not-a-real-file-xyz" })).is_err());
    }

    #[test]
    fn write_file_creates_and_writes() {
        let path = std::env::temp_dir().join(format!("bsc_p2b_write_{}.txt", std::process::id()));
        let p = path.to_string_lossy().into_owned();
        let msg = (write_file_tool().run)(&serde_json::json!({ "path": p, "content": "hi there" })).unwrap();
        assert!(msg.contains("wrote"));
        assert_eq!(std::fs::read_to_string(&path).unwrap(), "hi there");
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn edit_file_replaces_first_then_errors_when_absent() {
        let path = std::env::temp_dir().join(format!("bsc_p2b_edit_{}.txt", std::process::id()));
        std::fs::write(&path, "foo bar foo").unwrap();
        let p = path.to_string_lossy().into_owned();
        let tool = edit_file_tool();
        let msg = (tool.run)(&serde_json::json!({ "path": &p, "old_string": "foo", "new_string": "baz" })).unwrap();
        assert!(msg.contains("edited"));
        assert_eq!(std::fs::read_to_string(&path).unwrap(), "baz bar foo"); // first occurrence only
        let err = (tool.run)(&serde_json::json!({ "path": &p, "old_string": "zzz", "new_string": "x" })).unwrap_err();
        assert!(err.contains("not found"));
        let _ = std::fs::remove_file(&path);
    }

    #[test]
    fn resolve_bash_prefers_app_provided_path() {
        // The app hands the runtime the exact Git Bash via $BSC_AGENT_BASH; it wins over everything
        // (so the `bash` tool never falls through to the Windows WSL launcher). Unique value so the
        // assertion is unambiguous even though env is process-global.
        std::env::set_var("BSC_AGENT_BASH", "/opt/from-app/bash");
        assert_eq!(resolve_bash(), "/opt/from-app/bash");
        // Trimmed + empty is treated as unset (falls through, not returned blank).
        std::env::set_var("BSC_AGENT_BASH", "   ");
        assert_ne!(resolve_bash(), "");
        std::env::remove_var("BSC_AGENT_BASH");
    }

    #[test]
    fn bash_runs_command() {
        // Tolerant: `bash` may be absent or shadowed (e.g. by WSL) in CI/dev. Verify the
        // happy path when a working bash is present; otherwise skip rather than flake.
        match (bash_tool().run)(&serde_json::json!({ "command": "echo hello" })) {
            Ok(out) if out.contains("hello") => {} // a working bash → behavior verified
            Ok(out) => eprintln!("skipping bash assert (bash misconfigured here): {out:?}"),
            Err(e) => eprintln!("skipping bash test (bash unavailable): {e}"),
        }
    }

    #[test]
    fn grep_finds_matching_lines_with_path_and_line() {
        let dir = std::env::temp_dir().join(format!("bsc_grep_{}", std::process::id()));
        let _ = std::fs::create_dir_all(&dir);
        std::fs::write(dir.join("a.txt"), "alpha\nNEEDLE here\nbeta").unwrap();
        std::fs::write(dir.join("b.txt"), "nothing relevant").unwrap();
        let out = (grep_tool().run)(&serde_json::json!({
            "pattern": "NEEDLE",
            "path": dir.to_string_lossy(),
        }))
        .unwrap();
        assert!(out.contains("a.txt"), "names the matching file: {out}");
        assert!(out.contains(":2:"), "reports the 1-based line number: {out}");
        assert!(out.contains("NEEDLE here"));
        // A pattern that matches nothing returns the sentinel, not an error.
        let none = (grep_tool().run)(&serde_json::json!({
            "pattern": "zzz_absent",
            "path": dir.to_string_lossy(),
        }))
        .unwrap();
        assert_eq!(none, "no matches");
        // An invalid regex is an Err fed back to the model, not a crash.
        assert!((grep_tool().run)(&serde_json::json!({ "pattern": "[", "path": "." })).is_err());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn glob_lists_matching_paths() {
        let dir = std::env::temp_dir().join(format!("bsc_glob_{}", std::process::id()));
        let _ = std::fs::create_dir_all(&dir);
        std::fs::write(dir.join("keep.rs"), "").unwrap();
        std::fs::write(dir.join("skip.txt"), "").unwrap();
        let pat = format!("{}/*.rs", dir.to_string_lossy());
        let out = (glob_tool().run)(&serde_json::json!({ "pattern": pat })).unwrap();
        assert!(out.contains("keep.rs"));
        assert!(!out.contains("skip.txt"));
        let none = (glob_tool().run)(&serde_json::json!({
            "pattern": format!("{}/*.never", dir.to_string_lossy()),
        }))
        .unwrap();
        assert_eq!(none, "no matches");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn webfetch_validates_args_without_network() {
        // Missing `url` is a clean Err (no thread spawn / no network), so this stays
        // offline-safe in CI. The happy path is exercised by the parity smoke (#1444).
        assert!((webfetch_tool().run)(&serde_json::json!({})).is_err());
    }

    /// A `Sync` scripted provider for the `task` tests (the real `Arc<P>` capture in
    /// `task_tool` needs `P: Send + Sync`). Each `turn` is driven purely by an atomic call
    /// counter: turn 1 optionally emits one tool call, every later turn returns final text.
    struct ScriptedProvider {
        calls: AtomicUsize,
        first_call: Option<ToolCall>,
        final_text: String,
    }
    impl ScriptedProvider {
        fn finishing(text: &str) -> Self {
            ScriptedProvider { calls: AtomicUsize::new(0), first_call: None, final_text: text.into() }
        }
        fn calling(tc: ToolCall, then: &str) -> Self {
            ScriptedProvider { calls: AtomicUsize::new(0), first_call: Some(tc), final_text: then.into() }
        }
    }
    impl LlmProvider for ScriptedProvider {
        async fn complete(&self, _r: &LlmRequest, _k: &str) -> Result<serde_json::Value, String> {
            unreachable!()
        }
        async fn turn(&self, _t: &Turn, _k: &str) -> Result<TurnResult, String> {
            let n = self.calls.fetch_add(1, Ordering::SeqCst);
            let tool_calls = match (n, &self.first_call) {
                (0, Some(tc)) => vec![tc.clone()],
                _ => vec![],
            };
            let text = if tool_calls.is_empty() { self.final_text.clone() } else { String::new() };
            Ok(TurnResult { text, tool_calls, usage: serde_json::Value::Null, stop_reason: "x".into() })
        }
    }

    #[test]
    fn task_refuses_at_max_depth_without_spawning() {
        // A tool built at the depth limit must reject immediately (no thread / no provider call).
        let provider = Arc::new(ScriptedProvider::finishing("unused"));
        let tool = task_tool(provider, String::new(), "m".into(), String::new(), Permissions::default(), MAX_TASK_DEPTH);
        let err = (tool.run)(&serde_json::json!({ "prompt": "do it" })).unwrap_err();
        assert!(err.contains("max sub-agent depth"), "got: {err}");
    }

    #[test]
    fn task_delegates_and_returns_child_final_text() {
        // The child finishes on its first turn; the tool returns that text verbatim.
        let provider = Arc::new(ScriptedProvider::finishing("sub-agent answer"));
        let tool = task_tool(provider, String::new(), "m".into(), String::new(), Permissions::default(), 0);
        let out = (tool.run)(&serde_json::json!({ "prompt": "summarize" })).unwrap();
        assert_eq!(out, "sub-agent answer");
    }

    #[test]
    fn sub_agent_inherits_parent_permission_denies() {
        // The child is given the parent's perms (bash denied). It scripts a `bash` that would
        // create a sentinel file; the inherited deny must block execution, so the file never
        // appears even though the child loop runs to completion.
        let sentinel = std::env::temp_dir().join(format!("bsc_task_perm_{}.flag", std::process::id()));
        let _ = std::fs::remove_file(&sentinel);
        let bash = ToolCall {
            id: "t1".into(),
            name: "bash".into(),
            args: serde_json::json!({ "command": format!("touch {}", sentinel.display()) }),
        };
        let provider = Arc::new(ScriptedProvider::calling(bash, "done"));
        let perms = Permissions { deny_tools: vec!["bash".into()], ..Default::default() };
        let tool = task_tool(provider, String::new(), "m".into(), String::new(), perms, 0);
        let out = (tool.run)(&serde_json::json!({ "prompt": "run it" })).unwrap();
        assert_eq!(out, "done");
        assert!(!sentinel.exists(), "denied bash must not have executed in the sub-agent");
        let _ = std::fs::remove_file(&sentinel);
    }
}

implementations.code:
//! `bsc sandbox` — inspect or REPLAY a caged session's exact launch (request #135), and REPAIR a
//! settings.json whose PreToolUse hooks name the sandbox-only guest path (request #188).
//!
//! A dev session hit a real gap: a caged pane's `bwrap`/`systemd-run` argv was never recorded
//! anywhere retrievable, so reproducing one outside the app meant grepping `journalctl` for a debug
//! line that does not exist and hand-extracting the command from it. `namespace_argv` (the launch
//! path in the desktop crate) now calls [`crate::write_launch_argv`] the moment a launch renders;
//! this is the READ side — the one verb the surface needed: `replay` prints the recorded argv, or
//! execs it directly so a session can drop straight into the same cage.
//!
//! `repair-hooks` closes a second, unrelated gap on the same guest path: a session's
//! `.claude/settings.json` can be WRITTEN while caged and then read again by a later, uncaged
//! launch of the same directory — `ensure_session_settings` in the desktop crate rewrites the file
//! on every launch, but a hub or worktree nothing has relaunched simply keeps whatever it last
//! wrote. `hook_floor_mismatch` (`session/settings.rs`) detects that state at launch and a pane's
//! own next launch now self-heals it ([`crate::rewrite_guest_hooks`]), but the fix has to reach the
//! files ALREADY sitting stale on disk too — this walks every project hub and worktree and does
//! that in one pass.

use crate::{read_launch_argv, sandbox_stores_root};
use bsc_cli_util::CmdDoc;

const TAGLINE: &str =
    "a caged session's rendered argv (replay) and its settings.json's sandbox-only hook path (repair)";

/// The crate's own verb catalog. `pub` so `bsc surface verbs` and the Glance crate drill can PROJECT
/// it rather than restate it — a generated catalog cannot drift, a second list does.
pub const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "replay",
        summary: "print or exec the exact bwrap/systemd-run argv a pane's caged launch used",
        usage: "\
USAGE:
  bsc sandbox replay <pane-id> [--exec]

Prints the exact argv the last caged launch of <pane-id> rendered to, one argument per line — the
argv IS the command, so there is no shell string to quote or misquote (see SandboxSpec::render).
Pipe it into an array to run it by hand:

  mapfile -t argv < <(bsc sandbox replay <pane-id>)
  \"${argv[@]}\"

--exec skips the mapfile step and execs it directly, replacing this process with the SAME cage the
pane launched — the actual point of `replay`. Unix-only (bwrap/systemd-run are Linux-only).

The record lives beside the pane's other per-session state and disappears with it: a pane that never
launched caged, or whose session already ended, has nothing to replay.",
    },
    CmdDoc {
        name: "repair-hooks",
        summary: "fix a settings.json whose PreToolUse hooks name the sandbox-only guest path (request #188)",
        usage: "\
USAGE:
  bsc sandbox repair-hooks [--dry-run]

A session's `.claude/settings.json` can end up naming the sandbox-only guest hook path — the
PreToolUse commands a NAMESPACED launch installs — while the session that reads it is NOT running
in a mount namespace. That happens when a directory was gated by a caged launch and a later,
uncaged launch of the SAME directory never followed (`hook_floor_mismatch`,
`session/settings.rs`, in the desktop crate). Every gate in that file then fails to execute,
NON-BLOCKING: the session runs with no write-scope gate and no dangerous-command floor.

This walks every project hub and worktree under $HOME/.base-studio-code (`projects/` and
`worktrees/`) for a `.claude/settings.json`, and rewrites each stale one in place — the two guest
commands map onto their host shell-function equivalents (`bsc-scope`, `bsc-deny`). --dry-run
reports which files WOULD change without writing anything.

A pane's OWN next launch already self-heals this on its own; this exists for hubs and worktrees
nothing has relaunched yet.",
    },
];

pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let positional: Vec<String> = args.iter().filter(|a| !a.starts_with("--")).cloned().collect();
    if bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &positional) {
        return Ok(());
    }
    match positional.first().map(String::as_str).unwrap_or_default() {
        "replay" => cmd_replay(&args, &positional),
        "repair-hooks" => cmd_repair_hooks(&args),
        other => Err(bsc_cli_util::unknown_command(prog, TAGLINE, COMMANDS, other)),
    }
}

fn cmd_replay(args: &[String], positional: &[String]) -> Result<(), String> {
    let pane_id = positional
        .get(1)
        .ok_or_else(|| "usage: bsc sandbox replay <pane-id> [--exec]".to_string())?;
    let exec = args.iter().any(|a| a == "--exec");
    let base = bsc_util::bsc_base_dir()
        .ok_or_else(|| "no HOME/USERPROFILE set — cannot locate the sandbox store".to_string())?;
    let root = sandbox_stores_root(&base, pane_id);
    let argv = read_launch_argv(&root).map_err(|e| {
        format!(
            "no recorded launch for pane {pane_id:?} at {} ({e}) — either it never launched caged, \
             or its session ended and the record went with it",
            root.display()
        )
    })?;
    if argv.is_empty() {
        return Err(format!("the recorded launch for pane {pane_id:?} is empty"));
    }
    if exec {
        #[cfg(unix)]
        {
            use std::os::unix::process::CommandExt;
            let err = std::process::Command::new(&argv[0]).args(&argv[1..]).exec();
            return Err(format!("exec {} failed: {err}", argv[0]));
        }
        #[cfg(not(unix))]
        {
            let _ = &argv;
            return Err("--exec needs unix — bwrap/systemd-run are Linux-only".to_string());
        }
    }
    for a in &argv {
        println!("{a}");
    }
    Ok(())
}

fn cmd_repair_hooks(args: &[String]) -> Result<(), String> {
    let dry_run = args.iter().any(|a| a == "--dry-run");
    let base = bsc_util::bsc_base_dir()
        .ok_or_else(|| "no HOME/USERPROFILE set — cannot locate project hubs".to_string())?;
    let fixed = repair_hooks_under(&base, dry_run)?;
    if fixed.is_empty() {
        println!("no stale guest-hook settings.json found under {}", base.display());
    } else {
        let verb = if dry_run { "would repair" } else { "repaired" };
        for path in &fixed {
            println!("{verb} {}", path.display());
        }
        println!("{} file(s) {}", fixed.len(), if dry_run { "would be repaired" } else { "repaired" });
    }
    Ok(())
}

/// How deep under `<base>/projects` or `<base>/worktrees` to look for a `.claude/settings.json` —
/// bounds the walk under a real repo checkout (which can otherwise be arbitrarily deep) without
/// missing any shape this store actually uses: a hub root, a hub's linked-repo subdir, or a
/// worktree dir (`<key>/<repo>--<slug>/`).
const SETTINGS_WALK_DEPTH: usize = 6;

/// Directory names never worth descending into looking for a session's OWN `.claude/settings.json`
/// — vendored/build trees that can be huge and never contain one relevant here.
const SKIP_DIR_NAMES: &[&str] = &[".git", "node_modules", "target", "dist", "build"];

/// Walk `<base>/projects` and `<base>/worktrees` for a stale `.claude/settings.json` (PreToolUse
/// hooks naming the sandbox-only guest path while nothing is running one) and rewrite each in place
/// unless `dry_run`. Returns the paths fixed — or, under `dry_run`, the paths that WOULD be fixed.
fn repair_hooks_under(base: &std::path::Path, dry_run: bool) -> Result<Vec<std::path::PathBuf>, String> {
    let mut candidates = Vec::new();
    for sub in ["projects", "worktrees"] {
        collect_settings_files(&base.join(sub), &mut candidates, SETTINGS_WALK_DEPTH);
    }
    candidates.sort();
    let mut fixed = Vec::new();
    for path in candidates {
        let Ok(raw) = std::fs::read_to_string(&path) else { continue };
        let Ok(mut config) = serde_json::from_str::<serde_json::Value>(&raw) else { continue };
        if !crate::rewrite_guest_hooks(&mut config) {
            continue;
        }
        if !dry_run {
            write_settings_atomic(&path, &config)
                .map_err(|e| format!("failed to repair {}: {e}", path.display()))?;
        }
        fixed.push(path);
    }
    Ok(fixed)
}

fn collect_settings_files(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>, depth: usize) {
    if depth == 0 {
        return;
    }
    let Ok(entries) = std::fs::read_dir(dir) else { return };
    for entry in entries.flatten() {
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let name = entry.file_name();
        let name = name.to_string_lossy();
        if name == ".claude" {
            let settings = path.join("settings.json");
            if settings.is_file() {
                out.push(settings);
            }
            continue;
        }
        if SKIP_DIR_NAMES.contains(&name.as_ref()) {
            continue;
        }
        collect_settings_files(&path, out, depth - 1);
    }
}

fn write_settings_atomic(path: &std::path::Path, value: &serde_json::Value) -> std::io::Result<()> {
    let pretty = serde_json::to_string_pretty(value).map_err(std::io::Error::other)?;
    let tmp_name = format!("{}.tmp", path.file_name().unwrap_or_default().to_string_lossy());
    let tmp = path.with_file_name(tmp_name);
    std::fs::write(&tmp, pretty)?;
    std::fs::rename(&tmp, path)
}

#[cfg(test)]
mod tests {
