// The charter a request session launches with (#one-request-one-debug-session) — kept out of the
// component file so it is directly testable and so the mount stays a component-only module.
export { requestPaneId } from "@/shared/lib/session/requestSpawn";

// ── The debug-session constants (#debug-nodes-hang-off-the-session-that-filed-them) ────────────────
//
// These used to live in `DebugSessionMount`, the STANDING debug session's component. That session and
// its node are gone — every request draws its own — but the two constants below are not about the
// standing session at all: they are what ANY debug session launches with. They moved here, beside the
// only thing that still uses them, rather than being kept alive by a component that no longer mounts.
//
// `DEBUG_START_PROMPT` did NOT move. It was the standing session's queue-serving half ("claim the next
// request"), and a per-request session must never claim — the app claimed for it, and a second claim
// would take a request another session already holds.

export const DEBUG_INIT_CMD = "claude";

/** The shared DEBUG-session prose: who the session is, what it may touch, and the workflow + git rules
 *  every one of them follows. It deliberately says NOTHING about how the session gets its work — the
 *  charter below supplies that, naming the one request this session was spawned for.
 *
 *  ⚠️ ITS SCOPE IS THE WHOLE APP, and this prose said otherwise for a long time. It opened with "your
 *  job: improve the `bsc ui` surface so the Design Studio's designer session never needs permissions
 *  outside it" — true when the queue was the designer's alone, and false since every studio, the
 *  architect and the fleet started filing onto it. Measured on the live queue when this was fixed: the
 *  open requests named `bsc navigate`, `bsc ui`, `bsc graph`, `bsc plan` and `bsc fleet`, resolving to
 *  five different crates. The prompt even contradicted itself one sentence later ("implement the fix
 *  in the owning crate"), which is the instruction that was always right.
 *
 *  Keep it surface-agnostic. Naming a crate here re-scopes every debug session to whichever gap
 *  happened to be common the week it was written. */
export const DEBUG_ROLE_PROMPT =
  "You are the base-studio-code DEBUG session. You have full read/write access to THIS repository and " +
  "run the normal dev workflow. Your job is the WHOLE APPLICATION'S `bsc` surface: every session that " +
  "hits a wall files onto one queue — the architect, the designer, the librarian, the sound designer, " +
  "a director, a dev session — so a request can name any noun and land in any crate. Take the request " +
  "you were given and follow it to whatever owns it. " +
  "Reproduce the cited `bsc` command, implement the fix IN THE OWNING CRATE with tests, verify the gate " +
  "with `npm run gate -- --full`, then `bsc request resolve <id> --note \"<what changed>\"` and " +
  "rebuild the sidecar with " +
  "`cargo build --bin bsc` (the DEV profile — release is the slow one and nothing local needs it). The app " +
  "re-stages that binary and retires its warm `bsc` on its own the moment your request resolves, so the fix " +
  "is live for the next call with NO restart — do not ask for one. " +
  "Track the work the way every slice here is tracked: `bsc plan add` the item if there is not one " +
  "already, `bsc plan change new <ref>` at the START, and `bsc plan change gate <ref> <name> <result>` " +
  "with what each gate ACTUALLY did. " +
  "Work in a git worktree at the REPO ROOT as `wt-<short>` (nested there it needs no npm install, and " +
  "`.claude/worktrees/` is write-denied mid-session) on a branch off develop. " +
  "THIS REPO IS LOCAL-FIRST: never push, never open a PR, never write to GitHub — integration is a " +
  "local `git merge --no-ff` into develop once the work is verified. NEVER commit to develop or main " +
  "directly, and never switch the main checkout off develop.";

/** What a request session needs to know about the request it was spawned for. A subset of the
 *  `bsc request` row (snake_case from the Rust store), so a caller passes the row through. */
export interface RequestBrief {
  id: number;
  /** WHO filed it — the filing session's pane id (#debug-request-carries-its-origin), e.g.
   *  `designer-studio:react`. Absent when the request was filed outside a session. */
  origin?: string | null;
  /** The label form of the request, always populated by the store (explicit `--title`, else derived
   *  from the text). */
  display_title?: string | null;
}

/** The ROLES a studio pane id can name, longest first so `sound-designer` is matched before `designer`
 *  could ever claim its tail. Each maps to how the charter says it in prose. */
const ORIGIN_ROLES: readonly (readonly [string, string])[] = [
  ["sound-designer", "sound designer"],
  ["designer", "designer"],
  ["librarian", "librarian"],
  ["architect", "architect"],
  ["integrator", "integrator"],
];

/** The human name for a filing session's pane id — `design-studio:designer-react` → "the react designer".
 *
 *  READ THE TAIL, NOT THE STUDIO. The first version of this split on `:` and treated the left half as the
 *  role (`<role>-studio`), which is wrong for every session: the studio is named for the SURFACE
 *  (`design-studio`, `algorithms-studio`, `teams-studio`, `sound-studio`, `integration-studio`) and the
 *  role lives in the tail (`designer-react`, `librarian-typescript`, `architect`). It cost nothing to
 *  write and would have mislabelled every request, because the tests quoted the same invented shape.
 *
 *  Derived rather than looked up: the id is the only thing the request carries, and importing the session
 *  registry here would make the charter depend on a store-touching module to phrase one sentence. An
 *  unrecognised shape falls back to the raw id — a project director's `myproject:director` reads as
 *  itself, which is more use to a debug session than no attribution at all. */
export function originLabel(origin: string): string {
  const tail = (origin ?? "").split(":")[1] ?? "";
  for (const [role, human] of ORIGIN_ROLES) {
    if (tail === role) return `the ${human}`;
    if (tail.startsWith(`${role}-`)) return `the ${tail.slice(role.length + 1)} ${human}`;
  }
  return origin;
}

/**
 * The charter for the session working request `req`.
 *
 * It names the request instead of telling the session to go and find one. Under #3535 every pool
 * session launched generic and ran `bsc request claim` on startup, because a slot had no request until
 * it won the race; now the APP claims first and spawns a session for what it got, so the session starts
 * already knowing its job. That removes the whole warming/losing-the-race state — and with it the
 * reaper that existed to clean up after it.
 *
 * The session does NOT claim: its request is already `claimed` (the app did that atomically to obtain
 * the id), and one session exists per request by construction, so there is nothing left to race for.
 *
 * IT ALSO NAMES WHO FILED IT (#debug-request-carries-its-origin). A debug session is spawned BY a
 * studio session hitting a gap, and the fix is only right if it unblocks THAT session's actual workflow
 * — a `bsc ui` gap the React designer hit is a different fix from the same message arriving from
 * nowhere. The origin is on the request, so the charter states it and tells the session it may reply on
 * the thread; without that the relationship exists only in the graph, where the session working the
 * request cannot see it.
 *
 * The closing instruction is deliberate and carried over unchanged: a request must never be left open
 * with no explanation — "filed and silently unworked" is the failure this whole feature exists to
 * remove — and the resolve note IS the change log the maintainer reads back.
 */
export function requestCharter(req: RequestBrief): string {
  const { id } = req;
  const title = req.display_title?.trim();
  const origin = req.origin?.trim();
  const heading = title ? `YOUR REQUEST IS #${id} — "${title}".` : `YOUR REQUEST IS #${id}.`;
  const filedBy = origin
    ? `It was filed by ${originLabel(origin)} (\`${origin}\`) — a session that hit this gap in real work, ` +
      `not a hypothetical. Fix it so THAT session is unblocked: the failing command on the request is what ` +
      `it actually tried. If you need something from them, or the fix changes how the surface is used, ` +
      `reply on the request's thread — \`bsc request note ${id} "<what you found>" --from debugger\` — which ` +
      `they read back with \`bsc request get ${id}\`.\n\n`
    : "";
  return (
    `${DEBUG_ROLE_PROMPT}\n\n` +
    `${heading} It is already claimed for you — do not run \`bsc request claim\`. ` +
    `Read it, then work ONLY that one:\n` +
    `  bsc request get ${id}\n\n` +
    filedBy +
    `Reproduce the failing command, implement the fix in the owning crate with tests, verify the gate, ` +
    `then:\n` +
    `  bsc request resolve ${id} --note "<what you changed>"\n\n` +
    `The note is the change log — always leave one, even if it turns out NOT to be a defect (resolve it ` +
    `anyway with a note saying why; a request must never be left open with no explanation). Then STOP — ` +
    `your session is done and will be closed once #${id} reads resolved.`
  );
}

//! The `bsc network` subcommand — the network-specific shim over the shared verbatim-JSON-per-id
//! store CLI ([`bsc_json_store::cli`], #2158).
//!
//! A **network** is a domain that owns a set of projects and exactly one architect session. This store
//! holds the network entity only; a project's MEMBERSHIP is the `network` column on its project row,
//! set with `bsc project network set|clear` — the same seam `architect` already uses.
//!
//! Dispatched by the unified `bsc` binary (#1877) via [`run`]; the per-command help (#1762):
//!   bsc network help          # compact menu (the small "what commands exist" prompt)
//!   bsc network get help      # detailed help for ONE command
//!
//! The store is located via `--dir <path>` or the `BSC_NETWORK_DIR` env var (set per-session at
//! launch), defaulting to `~/.base-studio-code/networks.db`.

use bsc_cli_util::CmdDoc;
use bsc_json_store::cli::CliSpec;

const TAGLINE: &str =
    "the user network store — a domain that owns a set of projects and one architect session";

/// The command catalog — drives both dispatch and the shared help system. One detailed `usage` block
/// per command keeps the overview tiny and the detail one-fetch-away.
/// The crate's own verb catalog. `pub` so `bsc surface verbs` and the Glance crate drill can PROJECT
/// it rather than restate it — a generated catalog cannot drift, a second list does.
pub const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "new",
        summary: "create a network from a NAME; mints its id and prints it",
        usage: "\
USAGE:
  bsc network new <name>… [--pretty]

Creates a network and prints its id. The name may contain spaces — every argument is joined, so
`bsc network new cash flow` and `bsc network new \"cash flow\"` are the same thing.

THE NAME BECOMES THE ID, and the id is FROZEN: `network-<slug>`, lowercase [a-z0-9-]. A colliding
name gets a fresh id (`network-cash-flow-2`) rather than overwriting — the convention every in-app
library uses, and the reason this is not the `projectSlug`-plus-collision-modal discipline: that one
exists where an id names an on-disk hub recovered by derivation, and a network is a row.

The id is frozen because the architect's pane id (`network-<slug>:architect`) and its workspace
directory derive from it, so changing it would strand a running session. Change the NAME with
`bsc network rename`; it is display-only and safe.",
    },
    CmdDoc {
        name: "rename",
        summary: "change a network's display name (never its id)",
        usage: "\
USAGE:
  bsc network rename <id> <name>… [--pretty]

Sets the name shown on the Glance tab. DISPLAY ONLY — the id is untouched, because the architect's
pane id and workspace directory derive from it.

An empty name is refused rather than stored: a blank tab label is indistinguishable from a broken
one.",
    },
    CmdDoc {
        name: "list",
        summary: "every network's {id, name, architect} (JSON)",
        usage: "\
USAGE:
  bsc network list [--full] [--pretty]

Prints every network's { id, name, architect } as JSON (compact; --pretty for indented). --full emits
the COMPLETE network objects, which is what the desktop hydration reads.

A network is a DOMAIN: the set of projects that belong to one concern, drawn as one Glance tab. Which
projects are in it is NOT stored here — it is the `network` column on each project row, so read that
with `bsc project list` rather than expecting a member list on the network.",
    },
    CmdDoc {
        name: "get",
        summary: "print one network (JSON, verbatim) or null",
        usage: "\
USAGE:
  bsc network get <id> [--pretty]

Prints the stored network JSON for <id> verbatim, or `null` if absent.",
    },
    CmdDoc {
        name: "set",
        summary: "upsert from network JSON on stdin; prints id(s)",
        usage: "\
USAGE:
  bsc network set [--pretty]   # network JSON (one object or an array) on stdin

Upserts each network by its (required, non-empty) \"id\" field, written verbatim. Prints the id(s)
written.

SHAPE: { \"id\": \"network-kitchen\", \"name\": \"kitchen\", \"architect\": \"persona-architect\",
         \"position\": 0 }

  id         frozen at creation. The architect's pane id (`network-<id>:architect`) and its workspace
             dir are derived from it, so a changed id strands a running session. Rename the `name`.
  name       what the Glance tab shows. Display-only; change it freely.
  architect  optional persona id. Absent means the default architect persona.
  position   tab order.

The write is VERBATIM, so a field this CLI has no model for survives a round-trip — the same contract
every other json-store shim keeps.",
    },
    CmdDoc {
        name: "remove",
        summary: "delete a network (no-op if absent)",
        usage: "\
USAGE:
  bsc network remove <id> [--pretty]

Deletes the network keyed by <id>. A no-op (not an error) when it does not exist.

THIS DOES NOT REASSIGN ITS PROJECTS. A project whose `network` column still names a removed network is
unassigned in effect, not broken — clear or move it first with `bsc project network set|clear` if you
want it somewhere. Removing the network a project points at is recoverable; renaming its id is not.",
    },
];

/// The network store's concrete knobs over the shared CLI (#2158): its noun, env var, dir segment,
/// help catalog, and the `{id, name, architect}` lean-`list` projection.
///
/// `meta_fields` carries `architect` alongside the usual `{id, name}` because "who is the architect of
/// this network" is the question the lean list exists to answer — one fetch, no `--full`.
const SPEC: CliSpec = CliSpec {
    noun: "network",
    dir_env: "BSC_NETWORK_DIR",
    dir_segment: "networks",
    tagline: TAGLINE,
    commands: COMMANDS,
    meta_fields: &["id", "name", "architect"],
    graph_fields: &[],
    field_aliases: &[],
};

/// The `network` subcommand entrypoint: `args` is everything after `bsc network`; `prog` is the
/// display name for help/errors. Delegates to the shared dispatch with the network [`SPEC`].
pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    // `new` and `rename` are intercepted BEFORE delegating: the shared store CLI is a verbatim-JSON
    // CRUD surface and knows nothing about minting an id from a name, so it would reject them as
    // unknown commands. `help` still lists them — the catalog above is what the shared help renders.
    // Same shape as `bsc teams model`.
    match args.first().map(String::as_str) {
        Some("new") if args.get(1).map(String::as_str) != Some("help") => return cmd_new(&args, prog),
        Some("rename") if args.get(1).map(String::as_str) != Some("help") => return cmd_rename(&args, prog),
        _ => {}
    }
    bsc_json_store::cli::run(args, prog, &SPEC)
}

/// `network-<slug>` from a display name — THE id-minting rule, and the only copy that decides.
///
/// The frontend has a mirror of this in `mintNetworkId` for its optimistic cache, but the CLI is what
/// a session and a user reach, so the rule lives here. The character class is narrower than a display
/// name allows on purpose: the id becomes a pane key (`network-<slug>:architect`) and a directory name,
/// and `bsc_session::network_architect_slug` refuses anything outside `[a-z0-9-]`. A name that slugs to
/// nothing still yields a usable id rather than a bare `network-`.
fn mint_id(existing: &[String], name: &str) -> String {
    let slug: String = name
        .to_lowercase()
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
        .collect::<String>()
        .split('-')
        .filter(|p| !p.is_empty())
        .collect::<Vec<_>>()
        .join("-")
        .chars()
        .take(60)
        .collect();
    let base = format!("network-{}", if slug.is_empty() { "network" } else { &slug });
    if !existing.iter().any(|e| e == &base) {
        return base;
    }
    let mut n = 2;
    while existing.iter().any(|e| e == &format!("{base}-{n}")) {
        n += 1;
    }
    format!("{base}-{n}")
}

/// Open the network store the same way every verb does — `--dir` → `$BSC_NETWORK_DIR` → the default.
fn open_store(args: &[String], prog: &str) -> Result<bsc_json_store::Store, String> {
    let dir_flag = args
        .iter()
        .position(|a| a == "--dir")
        .and_then(|i| args.get(i + 1))
        .cloned();
    let dir = bsc_cli_util::resolve_store_path(&dir_flag, SPEC.dir_env, || {
        bsc_util::bsc_base_dir()
            .map(|b| b.join(SPEC.dir_segment))
            .ok_or_else(|| format!("{prog}: could not resolve the network store; set HOME/USERPROFILE or pass --dir"))
    })?;
    Ok(bsc_json_store::Store::new(dir, SPEC.noun))
}

/// Every argument after the verb that is not a flag or a flag's value, joined — so a name with spaces
/// needs no quoting.
fn joined_name(args: &[String], skip: usize) -> String {
    let mut out: Vec<&str> = Vec::new();
    let mut it = args.iter().skip(skip).peekable();
    while let Some(a) = it.next() {
        if a == "--dir" {
            it.next();
            continue;
        }
        if a.starts_with("--") {
            continue;
        }
        out.push(a);
    }
    out.join(" ").trim().to_string()
}

fn cmd_new(args: &[String], prog: &str) -> Result<(), String> {
    let name = joined_name(args, 1);
    if name.is_empty() {
        return Err(format!("usage: {prog} new <name>"));
    }
    let store = open_store(args, prog)?;
    // Existing ids, for the collision walk. Read from the store rather than tracked separately: two
    // sources for "which ids are taken" is how a mint starts overwriting.
    let rows = store.list();
    let existing: Vec<String> = rows
        .iter()
        .filter_map(|r| serde_json::from_str::<serde_json::Value>(r).ok())
        .filter_map(|v| v.get("id").and_then(|i| i.as_str()).map(str::to_string))
        .collect();
    let id = mint_id(&existing, &name);
    let position = existing.len() as i64;
    let row = serde_json::json!({ "id": id, "name": name, "position": position });
    store.set(&id, &serde_json::to_string(&row).map_err(|e| format!("{prog} new: {e}"))?)?;
    println!("{id}");
    Ok(())
}

fn cmd_rename(args: &[String], prog: &str) -> Result<(), String> {
    let id = args
        .get(1)
        .filter(|a| !a.starts_with("--"))
        .ok_or_else(|| format!("usage: {prog} rename <id> <name>"))?;
    let name = joined_name(args, 2);
    if name.is_empty() {
        // Refused rather than stored: a blank tab label is indistinguishable from a broken one.
        return Err(format!("usage: {prog} rename <id> <name>  (a name cannot be empty)"));
    }
    let store = open_store(args, prog)?;
    let raw = store
        .get(id)?
        .ok_or_else(|| format!("{prog} rename: no network '{id}' (list them with `{prog} list`)"))?;
    let mut v: serde_json::Value =
        serde_json::from_str(&raw).map_err(|e| format!("{prog} rename: '{id}' is not valid JSON: {e}"))?;
    // The NAME only. The id is re-pinned rather than left to the patch, so a rename can never move it.
    v["name"] = serde_json::Value::String(name);
    v["id"] = serde_json::Value::String(id.clone());
    store.set(id, &serde_json::to_string(&v).map_err(|e| format!("{prog} rename: {e}"))?)?;
    println!("{id}");
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Freezes the store's identity. These four values are what bind the CLI to a location on disk:
    /// change one and every existing user's networks become invisible without a single test failing
    /// elsewhere. Every shim pins them for that reason.
    /// The id-minting rule, pinned against the SAME hostile names the frontend's `mintNetworkId` test
    /// uses. Two copies of a rule drift; this is the one that decides, and the pair of tests is what
    /// says so out loud.
    #[test]
    fn mint_id_slugs_and_auto_disambiguates() {
        assert_eq!(mint_id(&[], "Finance"), "network-finance");
        assert_eq!(mint_id(&["network-finance".into()], "Finance"), "network-finance-2");
        assert_eq!(
            mint_id(&["network-finance".into(), "network-finance-2".into()], "finance"),
            "network-finance-3",
        );
    }

    /// The id becomes a PANE KEY (`network-<slug>:architect`) and a DIRECTORY NAME, and
    /// `bsc_session::network_architect_slug` refuses anything outside `[a-z0-9-]`. A name that slugs to
    /// nothing must still yield a usable id rather than a bare `network-`.
    #[test]
    fn a_minted_id_is_always_a_legal_pane_key() {
        for name in ["Cash & Flow", "  spaced  out  ", "../escape", "ÜNICODE", "!!!", "a/b", "x;y"] {
            let id = mint_id(&[], name);
            let slug = id.strip_prefix("network-").expect("every id carries the prefix");
            assert!(!slug.is_empty(), "{name} -> {id}");
            assert!(
                slug.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-'),
                "{name} -> {id} must be a legal pane key",
            );
        }
        assert_eq!(mint_id(&[], "!!!"), "network-network");
        assert_eq!(mint_id(&[], "Cash & Flow"), "network-cash-flow");
    }

    /// A name with spaces needs no quoting — every non-flag argument is joined — and `--dir` takes its
    /// value with it rather than leaking into the name.
    #[test]
    fn the_name_is_every_non_flag_argument_joined() {
        let args: Vec<String> = ["new", "cash", "flow", "--dir", "/tmp/x", "--pretty"]
            .iter().map(|s| s.to_string()).collect();
        assert_eq!(joined_name(&args, 1), "cash flow");
    }

    #[test]
    fn spec_pins_the_store_identity() {
        assert_eq!(SPEC.noun, "network");
        assert_eq!(SPEC.dir_env, "BSC_NETWORK_DIR");
        assert_eq!(SPEC.dir_segment, "networks");
        assert_eq!(SPEC.meta_fields, &["id", "name", "architect"]);
    }

    /// `--graph` is rejected rather than silently empty: an empty `graph_fields` means this store has no
    /// graph projection, and answering the flag with `[]` would read as "no networks".
    #[test]
    fn spec_declares_no_graph_projection() {
        assert!(SPEC.graph_fields.is_empty());
    }

    /// The help system is two-tier (#1762): a compact overview that names every command, and a detailed
    /// per-command drill-in. A command missing from the catalog is unreachable from help even when it
    /// dispatches, which is how a verb goes undiscovered.
    #[test]
    fn help_overview_lists_commands_and_per_command_help_drills_in() {
        for name in ["list", "get", "set", "remove"] {
            let doc = COMMANDS.iter().find(|c| c.name == name);
            let doc = doc.unwrap_or_else(|| panic!("`{name}` is missing from the help catalog"));
            assert!(!doc.summary.is_empty(), "`{name}` has a summary for the overview");
            assert!(
                doc.usage.contains(&format!("bsc network {name}")),
                "`{name}`'s detailed usage names the full command",
            );
        }
    }

    /// The id is load-bearing beyond this store — it derives the architect's pane id and workspace dir —
    /// so `set`'s help has to say the id is frozen and the name is what you rename. Documented behaviour
    /// with no test is how a contract quietly stops being true.
    #[test]
    fn set_help_states_the_id_is_frozen_and_the_name_is_not() {
        let set = COMMANDS.iter().find(|c| c.name == "set").expect("set is in the catalog");
        assert!(set.usage.contains("frozen at creation"));
        assert!(set.usage.contains("network-<id>:architect"));
    }
}

// Studios feature store slice (#3357) — the LIFECYCLE of the app-owned designer / librarian / architect
// sessions, now that all three live on the shared TerminalHost instead of a page-owned xterm.
//
// Two transient (NEVER persisted) fields, both keyed by StudioId:
//   • `wantedStudios` — which studios should have a WARM session. A studio enters the list the first time
//     something shows it (its page dock or the Glance morph, via `useStudioViewer`) and leaves it when the
//     idle reaper fires. `StudioSessionHosts` renders one persistent `TerminalSlot` per wanted studio, so
//     "wanted" is exactly "this studio has a terminal on the host". (The backend PTY is killed explicitly
//     by whoever drops the studio — the reaper, or an "End session" from the Glance morph — because
//     `TerminalView`'s unmount deliberately leaves the session alive for reconnect.)
//   • `studioViewers` — a REF COUNT of the surfaces currently SHOWING each studio. Two independent
//     surfaces can show the same session at once (the studio page dock and the Glance node morph), so a
//     boolean would let whichever closed first cancel the other. Counting means the reaper only arms when
//     the LAST viewer goes away.
//
// Nothing here launches or kills a PTY directly — `wantedStudios` is a declaration and the mount/TerminalHost
// pair is what acts on it. That keeps the whole lifecycle unit-testable as plain state transitions.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import { STUDIO_IDS, type StudioId } from "@/features/studio-sessions/lib/studioSessions";

export interface StudiosSlice {
  /** Studios whose session should be kept warm on TerminalHost. Transient — nothing launches at boot. */
  wantedStudios: StudioId[];
  /** studio id → number of mounted surfaces currently SHOWING it (page dock + Glance morph). Transient. */
  studioViewers: Record<string, number>;
  /** A launch DIRECTIVE waiting to be baked into a studio's next start, keyed by studio id.
   *
   *  Set by `bsc session ask` when it starts a session to serve a loop, and consumed (once) by
   *  `seedStudioLaunchState` as an appendix to the persona prompt — so the session comes up already
   *  running `bsc loop watch`. Transient like the rest of this slice: a directive that outlived the
   *  app restart it was written for would send a session to watch a loop nobody is waiting on. */
  studioPendingDirective: Partial<Record<StudioId, string>>;
  /** Queue a launch directive for a studio's NEXT start. Overwrites any unconsumed one — a second ask
   *  supersedes the first, and two directives in one launch prompt would have the session watching two
   *  loops and answering neither. */
  setStudioPendingDirective: (id: StudioId, directive: string) => void;
  /** Take the directive, clearing it — so it is baked in exactly once and a later relaunch of the same
   *  studio (a reaper reclaim, a user re-open) does not resurrect a stale request. */
  takeStudioPendingDirective: (id: StudioId) => string | undefined;
  /** Mark a studio as wanted — the lazy start. Idempotent, so every viewer can call it on mount. */
  openStudio: (id: StudioId) => void;
  /** Drop a studio from the wanted list → its persistent mount unmounts. Called by the idle reaper and by
   *  an explicit "End session" from the Glance morph, BOTH of which also `pty_kill` the session. */
  closeStudio: (id: StudioId) => void;
  /** A surface began showing this studio (cancels any armed reap). */
  addStudioViewer: (id: StudioId) => void;
  /** A surface stopped showing this studio (arms the reaper when the count reaches 0). */
  removeStudioViewer: (id: StudioId) => void;

  /** NETWORK ids whose architect session should be kept warm. Transient, like `wantedStudios`.
   *
   *  A separate list rather than more `StudioId`s: a studio is one of a fixed set the app ships, and a
   *  network is created by the user at runtime. Widening `StudioId` to a string to hold both would have
   *  cost every studio call site its exhaustiveness — the compile-time key is what makes a typo in a
   *  studio id a build error rather than a silently dead session. */
  wantedNetworkArchitects: string[];
  /** Mark a network's architect as wanted — the lazy start. Idempotent, so every viewer can call it. */
  openNetworkArchitect: (networkId: string) => void;
  /** Drop it → its mount unmounts. The caller that wants the PTY gone also kills it, exactly as
   *  `closeStudio`'s callers do. */
  closeNetworkArchitect: (networkId: string) => void;
}

export const createStudiosSlice: StateCreator<AppStore, [], [], StudiosSlice> = (set, get) => ({
  wantedStudios: [],
  studioViewers: {},
  studioPendingDirective: {},
  wantedNetworkArchitects: [],

  openNetworkArchitect: (networkId) =>
    set((s) => (s.wantedNetworkArchitects.includes(networkId)
      ? {}
      : { wantedNetworkArchitects: [...s.wantedNetworkArchitects, networkId] })),

  closeNetworkArchitect: (networkId) =>
    set((s) => (s.wantedNetworkArchitects.includes(networkId)
      ? { wantedNetworkArchitects: s.wantedNetworkArchitects.filter((w) => w !== networkId) }
      : {})),

  setStudioPendingDirective: (id, directive) =>
    set((s) => ({ studioPendingDirective: { ...s.studioPendingDirective, [id]: directive } })),

  // A GET-AND-CLEAR rather than a selector plus a separate clear: two callers reading before either
  // cleared would both bake the directive in, and the second launch would watch a loop already served.
  takeStudioPendingDirective: (id) => {
    const current = get().studioPendingDirective[id];
    if (current !== undefined) {
      set((s) => {
        const next = { ...s.studioPendingDirective };
        delete next[id];
        return { studioPendingDirective: next };
      });
    }
    return current;
  },

  openStudio: (id) =>
    set((s) => (s.wantedStudios.includes(id) ? {} : { wantedStudios: [...s.wantedStudios, id] })),

  closeStudio: (id) =>
    set((s) => (s.wantedStudios.includes(id) ? { wantedStudios: s.wantedStudios.filter((w) => w !== id) } : {})),

  addStudioViewer: (id) =>
    set((s) => ({ studioViewers: { ...s.studioViewers, [id]: (s.studioViewers[id] ?? 0) + 1 } })),

  // Clamp at 0: a double-unmount (StrictMode, a racing cleanup) must never drive the count negative —
  // a negative count would read as "still watched" forever and the reaper would never arm.
  removeStudioViewer: (id) =>
    set((s) => ({ studioViewers: { ...s.studioViewers, [id]: Math.max(0, (s.studioViewers[id] ?? 0) - 1) } })),
});

/** The studios currently WANTED, in canonical rail order (so the mounts render in a stable order). */
export function orderedWantedStudios(wanted: readonly StudioId[]): StudioId[] {
  return STUDIO_IDS.filter((id) => wanted.includes(id));
}

