// useFleetDirectorBridge (#architect-creates-a-director-with-discovery) — apply a
// `bsc fleet director new` request and ACK it.
//
// THE ROUND TRIP
//   bsc fleet director new <key> → request file → Rust watcher (resolves the project, refuses a live
//   director, seeds prompts/director-kickoff.md) → `bsc://fleet-director` → HERE → fleetStartProject
//   → `fleet_director_ack`
//
// A thin adapter: the DECISION lives in `fleetDirectorBridge.ts`, unit-testable without Tauri.
//
// THIS IS NOT AN INJECTION PATH. The director's context is BAKED INTO THE LAUNCH as claude's
// initial-message argument — the same delivery the kickoff doc always used. Nothing is typed into a
// running session, and `injectCallers.test.ts` stays green on its empty set.
//
// WHY THE DOC IS READ HERE RATHER THAN AT LAUNCH (#the-director-launches-with-no-kickoff-prompt)
// `fleetStartProject` seeds the kickoff as a doc PATH, which TerminalView resolves once inside its
// launch effect. That is the route whose silent-loss failure is documented on the `startupPrompt`
// prop — the one that left every debug session "a bare `claude` with nothing to do" until debug and
// studio sessions were migrated off it. The director never was.
//
// So this resolves the doc to text FIRST and hands it to `applyDirectorNew`, which seeds it before any
// pane exists. `read_document` failing is not fatal: the launch proceeds and the doc route stays as
// the fallback, because a director delivered the old way beats no director at all.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { log } from "@/shared/lib/core/log";
import { scriptDocRelpath } from "@/features/planner/session/planningSession";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";
import { applyDirectorNew, type DirectorRequest, type DirectorAck } from "@/app/fleetDirectorBridge";

/** The hub-relative kickoff every director launch reads, resolved in Rust before the emit. */
const KICKOFF_RELPATH = "prompts/director-kickoff.md";

/** Listen for `bsc://fleet-director` and launch it. Mounted once by the shell. */
export function useFleetDirectorBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<DirectorRequest>("bsc://fleet-director", (e) => {
      const req = e.payload;
      void (async () => {
        // Resolve the kickoff BEFORE the launch. A failure is logged and carried as `undefined` — the
        // launch still happens and falls back to the doc route rather than refusing to create the
        // director the architect asked for.
        let kickoffText: string | undefined;
        try {
          const relpath = scriptDocRelpath(sanitizeProjectKey(req.projectKey ?? ""), KICKOFF_RELPATH);
          const text = await invoke<string>("read_document", { relpath });
          kickoffText = typeof text === "string" && text.trim() ? text : undefined;
          if (!kickoffText) log.warn(`fleet director ${req.id}: ${relpath} is empty — falling back to the doc route`);
        } catch (err) {
          log.warn(`fleet director ${req.id}: kickoff read failed (${String(err)}) — falling back to the doc route`);
        }

        let ack: DirectorAck;
        try {
          ack = applyDirectorNew(
            req,
            {
              // Read off a LIVE getState, not a captured snapshot — zustand hands out a new object per
              // update, so a stale closure could launch against an older tab list.
              fleetStartProject: (name, fleet, key, paths) =>
                useAppStore.getState().fleetStartProject(name, fleet, key, paths),
              seedStartupPromptText: (paneId, text) =>
                useAppStore.setState((s) => ({
                  paneStartupPromptText: { ...s.paneStartupPromptText, [paneId]: text },
                })),
            },
            kickoffText,
          );
        } catch (err) {
          ack = {
            id: req.id,
            error: `fleet director threw: ${err instanceof Error ? err.message : String(err)}`,
            created: false,
          };
          log.error(`fleet director ${req.id} threw: ${String(err)}`);
        }
        void invoke("fleet_director_ack", { ack: { ...ack, id: req.id } }).catch((e2) => {
          // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
          log.error(`fleet_director_ack failed for ${req.id}: ${String(e2)}`);
        });
      })();
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}

// The feature list (#…): the authoritative artifact of the Features stage. Each entry is a
// capability AND a fleet stream, carrying a dependency DAG (`dependsOn`). The planner writes them to
// plan.db (surfaced by the poll as the `features` section); the Features board renders it and the
// gate signal reads it. Issues are generated FROM features at publish — `featuresToPlanIssues`.
// Pure + tolerant of partial/malformed input — no React/Tauri.

import type { PlanIssue } from "@/features/planner/issues/planIssues";
import { slugify } from "@/shared/lib/core/format";

export interface PlanFeature {
  /** Stable slug / stream id (kebab-case). */
  slug: string;
  /** Capability name ("Invite teammates", "Geometry kernel"). Not just user-facing — a feature can
   *  be foundational (others depend on it). */
  name: string;
  /** What it does + when, in the user's terms. */
  behavior?: string;
  /** Done-when checklist a building agent verifies against. */
  acceptance?: string[];
  /** The build approach — the shape of the solution. */
  approach?: string;
  /** Specific libraries / services / frameworks. */
  tools?: string[];
  /** Feature slugs this feature builds on — the coarse roadmap DAG (#plan-db). Must stay acyclic. */
  dependsOn?: string[];
  /** What it stores/reads. */
  data?: string;
  /** The fleet stream that owns it (defaults to the slug — a feature IS a stream). */
  stream?: string;
  /** Algorithm impl ids from the GLOBAL `bsc graph` store this capability needs (#4080) — the plan →
   *  algorithms-graph edge, so a worker is pointed at the reference implementation instead of re-coding
   *  it. DECLARED intent (the planner names them at Features time), not derived fact. */
  requires?: RequiredRef[];
}

/** One `requires` entry, matching Rust's `RequiredRef` (crates/plandb/src/features.rs): a bare id, or
 *  an id carrying who asked for it and why. BOTH arms are load-bearing — the point of populating
 *  `requires` is telling a DIRECTOR's seed from a WORKER's mid-task discovery, and flattening the
 *  object arm to a string throws away the only thing that answers it. This type used to be `string[]`
 *  and `strArray` filtered non-strings out, so every attributed entry vanished between the store and
 *  the board without a word. */
export type RequiredRef = string | { id: string; by?: string; at?: string; note?: string };

/** The id of a `requires` entry, whichever shape it takes. */
export function requiredId(r: RequiredRef): string {
  return typeof r === "string" ? r : r.id;
}

function str(v: unknown): string | undefined {
  return typeof v === "string" && v.trim() ? v.trim() : undefined;
}
/** `requires` entries, keeping the attributed ones whole. Mirrors nothing — it decodes what Rust
 *  serialises; the RULES over the decoded list live in `crates/plandb` and are read with
 *  `bsc plan feature gate`. */
function requiredArray(v: unknown): RequiredRef[] | undefined {
  if (!Array.isArray(v)) return undefined;
  const out: RequiredRef[] = [];
  for (const x of v) {
    if (typeof x === "string" && x.trim()) out.push(x.trim());
    else if (x && typeof x === "object" && typeof (x as { id?: unknown }).id === "string") {
      const o = x as { id: string; by?: unknown; at?: unknown; note?: unknown };
      if (!o.id.trim()) continue;
      out.push({
        id: o.id.trim(),
        ...(typeof o.by === "string" ? { by: o.by } : {}),
        ...(typeof o.at === "string" ? { at: o.at } : {}),
        ...(typeof o.note === "string" ? { note: o.note } : {}),
      });
    }
  }
  return out.length ? out : undefined;
}
function strArray(v: unknown): string[] | undefined {
  if (!Array.isArray(v)) return undefined;
  const out = v.filter((x): x is string => typeof x === "string" && x.trim().length > 0).map((s) => s.trim());
  return out.length ? out : undefined;
}
/** Parse `features.json` (a JSON array of feature objects) into a clean list. Tolerant: bad JSON
 *  ⇒ []; entries missing both slug and name are dropped; duplicate slugs are de-duped; a missing
 *  slug is derived from the name, and stream defaults to the slug. */
export function parseFeaturesFile(raw: string): PlanFeature[] {
  if (!raw.trim()) return [];
  let data: unknown;
  try { data = JSON.parse(raw); } catch { return []; }
  if (!Array.isArray(data)) return [];
  const out: PlanFeature[] = [];
  const seen = new Set<string>();
  for (const item of data) {
    if (!item || typeof item !== "object") continue;
    const o = item as Record<string, unknown>;
    const name = str(o.name) ?? "";
    const slug = str(o.slug) ?? slugify(name, 60);
    if (!slug || !name || seen.has(slug)) continue;
    seen.add(slug);
    out.push({
      slug, name,
      behavior: str(o.behavior),
      acceptance: strArray(o.acceptance),
      approach: str(o.approach),
      tools: strArray(o.tools),
      dependsOn: strArray(o.dependsOn ?? o.depends_on),
      // Both spellings, like `dependsOn` — the store emits camelCase, but a hand-written or older
      // payload may carry snake, and silently dropping it would lose the reference entirely.
      requires: requiredArray(o.requires ?? o.requires_),
      data: str(o.data),
      stream: str(o.stream) ?? slug,
    });
  }
  return out;
}

// featureDefined / featuresSummary / featuresGateComplete / featuresAwaitingConfirm /
// featureDependencyCycle USED TO LIVE HERE and are now in `crates/plandb/src/features.rs`.
//
// They were policy over plan.db, which is the crate's resource, and keeping a copy here is what let
// the two disagree: Rust's `validate.rs` even documented itself as "mirrors the frontend
// `featureDefined`", so the renderer was the spec and the store was the copy. MEASURED 2026-09-03,
// `bsc plan feature list` printed `·` against nearly every row above its own footer claiming
// `47 of 49 features fully defined` — one command, two rules.
//
// Read them instead: `bsc plan feature gate [--confirmed] --json` returns
// { count, specified, defined, allSpecified, gateComplete, awaitingConfirm, dependencyCycle }.
// `featureRulesStayInRust.test.ts` fails if a predicate reappears here.
/** The extra prose (beyond acceptance/owns/dependsOn, which `renderIssueBody` adds) for a feature's
 *  published issue: its behavior + approach + data + tools. */
function featureBody(f: PlanFeature): string | undefined {
  const parts: string[] = [];
  if (f.behavior?.trim()) parts.push(f.behavior.trim());
  if (f.approach?.trim()) parts.push(`## Approach\n${f.approach.trim()}`);
  if (f.data?.trim()) parts.push(`## Data\n${f.data.trim()}`);
  if (f.tools?.length) parts.push(`## Tools\n${f.tools.map((t) => `- ${t}`).join("\n")}`);
  return parts.join("\n\n").trim() || undefined;
}

/**
 * Project features into the issues published from them (#plan-db) — ONE issue per feature. Issues
 * aren't authored during planning; this is what publish (and the structure card) generate from the
 * DB features. The feature's slug becomes the issue `ref`, so a `dependsOn` between features is a
 * `dependsOn` between issues; acceptance carries over; behavior/approach/data/tools become the
 * body. `owns`/`labels` are left to the fleet (assigned to the stream in the Permissions stage).
 */
export function featuresToPlanIssues(features: PlanFeature[]): PlanIssue[] {
  return features.map((f) => ({
    ref: f.slug,
    title: f.name || f.slug,
    acceptance: f.acceptance ?? [],
    owns: [],
    dependsOn: f.dependsOn ?? [],
    labels: [],
    stream: f.stream ?? f.slug,
    body: featureBody(f),
  }));
}

