// The FEATURE node projection (`a-feature-is-a-node`) — the band and one feature's drill.
import { describe, it, expect } from "vitest";
import { featureBand, featureDrill, withFeatureNodes, streamFeature, requiredId, requiredBy } from "@/features/glance/lib/featureNodes";
import { featureNodeId, featureRequiresNodeId } from "@/features/glance/lib/glanceGraph";

const FEATURES = [
  { slug: "glance", name: "Glance", requires: ["safe-invoke.ts", { id: "use-poll.ts", by: "director" }] },
  { slug: "cad", name: "CAD" },
  // No stream anywhere — the case the band must still show.
  { slug: "orphan", name: "Orphan" },
];
const STREAMS = [
  { id: "glance", repo: "o/r" },                              // id IS the slug — the fallback
  { id: "fleet-panes", feature: "glance", repo: "o/r" },       // explicitly under glance
  { id: "cad", feature: "cad", kind: "cleanup", repo: "o/r" },
];

describe("streamFeature — which feature a stream belongs to", () => {
  it("prefers the stream's own `feature` and falls back to its id", () => {
    // The fallback is not a convenience: 37 of studio-code's 89 stream ids ARE feature slugs and the
    // launch has always leaned on that. A projection that disagreed with the launch would draw a graph
    // of a fleet that does not exist.
    expect(streamFeature({ id: "fleet-panes", feature: "glance" })).toBe("glance");
    expect(streamFeature({ id: "glance" })).toBe("glance");
    // Whitespace is the shape a hand-edited record has; it must not read as a real feature.
    expect(streamFeature({ id: "glance", feature: "   " })).toBe("glance");
  });
});

describe("featureBand", () => {
  it("gives EVERY feature a node, including one with no streams", () => {
    // The same reasoning that gives a verb-less crate a node: an unstaffed lane is exactly the one
    // worth seeing, and a projection that dropped it would hide the gap in the view that exists to
    // show gaps.
    const { nodes } = featureBand(FEATURES, STREAMS);
    expect(nodes.map((n) => n.slug)).toEqual(["glance", "cad", "orphan"]);
    expect(nodes.map((n) => n.id)).toEqual([
      featureNodeId("glance"), featureNodeId("cad"), featureNodeId("orphan"),
    ]);
  });

  it("carries the stream COUNT, and states zero rather than omitting it", () => {
    const byId = new Map(featureBand(FEATURES, STREAMS).nodes.map((n) => [n.slug, n.roleLabel]));
    expect(byId.get("glance")).toBe("2 streams");   // the fallback one AND the explicit one
    expect(byId.get("cad")).toBe("1 streams");
    // A blank card is indistinguishable from a rendering bug; `0 streams` is a fact.
    expect(byId.get("orphan")).toBe("0 streams");
  });

  it("draws NO edges between features", () => {
    // `dependsOn` on a feature is the roadmap DAG — a sequencing hint, not a dependency the code has.
    // Drawing it here would read as the same kind of line the crate band uses for a real cargo edge.
    expect(featureBand(FEATURES, STREAMS).edges).toEqual([]);
  });

  it("is deterministic — roster order in, same order out", () => {
    const a = featureBand(FEATURES, STREAMS).nodes.map((n) => n.id);
    const b = featureBand(FEATURES, STREAMS).nodes.map((n) => n.id);
    expect(a).toEqual(b);
  });
});

describe("featureDrill", () => {
  const store = (id: string) => (id === "safe-invoke.ts" ? ("algorithms" as const) : undefined);

  it("puts this feature's streams beneath it, and no other feature's", () => {
    const { nodes, edges } = featureDrill(FEATURES[0], STREAMS, store);
    const streams = nodes.filter((n) => n.kind === "session").map((n) => n.slug);
    expect(streams).toEqual(["glance", "fleet-panes"]);
    expect(streams).not.toContain("cad");
    // Every stream edge points UP to the feature — the drill reads as one lane under one owner.
    const belongs = edges.filter((e) => e.kind === "belongs-to");
    expect(belongs).toHaveLength(2);
    expect(belongs.every((e) => e.to === featureNodeId("glance"))).toBe(true);
    // ONE IDENTITY PER STREAM. The node id is the STREAM's own id — the same id the fleet drill
    // gives the lane — so `fleetPaneId(drill, id)` finds the same pane and the node really is the
    // session it claims to be. A minted `fstream:…` id resolved to nothing.
    expect(belongs[0].from).toBe("glance");
    expect(nodes.filter((n) => n.kind === "session").map((n) => n.id)).toEqual(["glance", "fleet-panes"]);
  });

  it("keeps required RECORDS a different kind from streams", () => {
    // They answer different questions: a stream is this project's own work with a worktree and a
    // worker; a required record is shared and NOT this feature's to edit. Collapsing them would
    // suggest a worker can change both, which is the whole thing `requires` exists to deny.
    const { nodes } = featureDrill(FEATURES[0], STREAMS, store);
    const req = nodes.filter((n) => n.kind === "library");
    expect(req.map((n) => n.slug)).toEqual(["safe-invoke.ts", "use-poll.ts"]);
    expect(req.every((n) => n.role === "infra")).toBe(true);
  });

  it("names WHICH STORE answers a record, and who asked for it", () => {
    // `bsc graph impl get` and `bsc ui get` are different commands — a drill that guessed would send a
    // reader to one that returns nothing for half the list.
    const req = featureDrill(FEATURES[0], STREAMS, store).nodes.filter((n) => n.kind === "library");
    expect(req[0].roleLabel).toBe("algorithms");
    // …and the provenance rides along, which is the whole point of the attributed write.
    expect(req[1].roleLabel).toContain("by director");
  });

  it("flags a record in NEITHER graph rather than dropping it", () => {
    // `requires` is deliberately not validated at plan-write time, so a drill is one of the first
    // places a typo becomes visible. Silently omitting it would make a dangling id look like a
    // feature that requires less than it does.
    const dangling = featureDrill({ slug: "x", requires: ["nope.ts"] }, [], () => undefined);
    // FIND it rather than indexing: node 0 is the feature's own root now, and an index-based test
    // silently changes what it asserts the moment the node order does.
    const n = dangling.nodes.find((x) => x.id === featureRequiresNodeId("x", "nope.ts"))!;
    expect(n, "the dangling record was dropped instead of flagged").toBeDefined();
    expect(n.id).toBe(featureRequiresNodeId("x", "nope.ts"));
    expect(n.health).toBe("warning");
    expect(n.reason).toBe("in neither graph");
  });

  it("puts the FEATURE ITSELF in the graph — the root its streams hang from", () => {
    // It was missing, and every edge named it: the streams rendered with nothing to hang from, which
    // is what a reader sees as "no root". A projection that emits an edge to a node it does not emit
    // is broken however good its other nodes are.
    const { nodes } = featureDrill(FEATURES[0], STREAMS, store);
    const root = nodes.find((n) => n.id === featureNodeId("glance"));
    expect(root, "the drilled feature has no node of its own").toBeDefined();
    expect(root!.kind).toBe("feature");
    expect(root!.roleLabel).toBe("2 streams");
  });

  it("holds a feature with nothing under it to just its root, rather than throwing", () => {
    // Not `{nodes: [], edges: []}` any more: an unstaffed feature still IS one, and a drill that
    // rendered blank would be indistinguishable from a broken one.
    const { nodes, edges } = featureDrill(FEATURES[2], STREAMS, store);
    expect(nodes.map((n) => n.id)).toEqual([featureNodeId("orphan")]);
    expect(edges).toEqual([]);
  });

  // THE INVARIANT THAT WOULD HAVE CAUGHT IT, asserted over BOTH projections rather than trusting
  // either: `featureBand` filtered its edges to the nodes it emitted and `featureDrill` did not, so
  // the property held in one and silently failed in the other.
  it("emits no edge to a node it does not also emit", () => {
    for (const f of FEATURES) {
      const { nodes, edges } = featureDrill(f, STREAMS, store);
      const ids = new Set(nodes.map((n) => n.id));
      const dangling = edges.filter((e) => !ids.has(e.from) || !ids.has(e.to));
      expect(dangling.map((e) => e.id), `dangling edge(s) in the ${f.slug} drill`).toEqual([]);
    }
  });
});

describe("requiredId / requiredBy — the two entry shapes", () => {
  it("reads a bare id and an attributed entry the same way, and invents no author", () => {
    expect(requiredId("a.ts")).toBe("a.ts");
    expect(requiredId({ id: "b.ts" })).toBe("b.ts");
    // A bare id carries NO author — absent, never guessed, which is what makes a seeded entry
    // distinguishable from a discovered one.
    expect(requiredBy("a.ts")).toBeUndefined();
    expect(requiredBy({ id: "b.ts", by: "worker-A" })).toBe("worker-A");
  });
});

// THE FOLD ITSELF WAS UNTESTED, which is how it shipped ADDING to the graph instead of REPLACING in
// it — 89 flat stream nodes and 27 feature cards on one canvas, read (correctly) as "the old plan".
// `featureBand` and `featureDrill` each had their own passing tests throughout; nothing asserted what
// the fold did to the graph it was folding into.
describe("withFeatureNodes — the feature replaces the streams it covers", () => {
  const FLEET = {
    sample: false,
    rawNodes: [
      { id: "director", slug: "director", kind: "session" as const, role: "service" as const, health: "off" as const, activity: "idle" as const },
      { id: "glance", slug: "glance", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
      { id: "fleet-panes", slug: "fleet-panes", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
      { id: "unassigned", slug: "unassigned", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
    ],
    rawEdges: [
      { id: "d-glance", from: "director", to: "glance", kind: "coordinates" as const },
      { id: "d-panes", from: "director", to: "fleet-panes", kind: "coordinates" as const },
      { id: "d-un", from: "director", to: "unassigned", kind: "coordinates" as const },
    ],
  };
  const FEATS = [{ slug: "glance", name: "Glance" }];
  const STRS = [
    { id: "glance", feature: "glance" },
    { id: "fleet-panes", feature: "glance" },
    { id: "unassigned" },
  ];

  it("drops the stream nodes its features stand for", () => {
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const ids = out.rawNodes.map((n) => n.id);
    expect(ids).not.toContain("glance");
    expect(ids).not.toContain("fleet-panes");
    expect(ids).toContain(featureNodeId("glance"));
  });

  it("KEEPS a stream no feature covers — unassigned work must not vanish", () => {
    // The one thing this view must never do. An unstaffed lane is exactly what a reader is scanning
    // for, and removing it leaves no node to notice its absence by.
    expect(withFeatureNodes(FLEET, FEATS, STRS).rawNodes.map((n) => n.id)).toContain("unassigned");
  });

  it("leaves the director alone", () => {
    expect(withFeatureNodes(FLEET, FEATS, STRS).rawNodes.map((n) => n.id)).toContain("director");
  });

  it("leaves no edge pointing at a removed stream", () => {
    // A dangling edge is what made the feature DRILL render rootless; the fold must not reintroduce
    // the same class one level up.
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const ids = new Set(out.rawNodes.map((n) => n.id));
    expect(out.rawEdges.filter((e) => !ids.has(e.from) || !ids.has(e.to))).toEqual([]);
  });

  it("REDIRECTS a removed stream's edges onto its feature — the director still manages it", () => {
    // The relationship is inherited, not minted: `fleetToOrg` draws `director manages <stream>` via
    // `archOf`, which a TEAM may have authored differently. A fresh edge here would discard that.
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const toFeature = out.rawEdges.filter((e) => e.to === featureNodeId("glance"));
    expect(toFeature).toHaveLength(1);
    expect(toFeature[0].from).toBe("director");
    expect(toFeature[0].kind).toBe("coordinates");
  });

  it("collapses N streams under one feature into ONE edge", () => {
    // `glance` covers two streams, and the director managed both. Twenty parallel lines between the
    // same pair is one fact drawn twenty times.
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const pairs = out.rawEdges.map((e) => `${e.from}|${e.to}|${e.kind}`);
    expect(new Set(pairs).size).toBe(pairs.length);
  });

  it("keeps an UNCOVERED stream's own edge untouched", () => {
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    expect(out.rawEdges.find((e) => e.to === "unassigned")?.id).toBe("d-un");
  });

  it("preserves an AUTHORED archetype through the redirect", () => {
    const authored = {
      ...FLEET,
      rawEdges: [{ id: "d-glance", from: "director", to: "glance", kind: "coordinates" as const, archetype: "mentors" }],
    };
    const out = withFeatureNodes(authored, FEATS, STRS);
    const e = out.rawEdges.find((x) => x.to === featureNodeId("glance"));
    expect(e?.archetype, "a team-authored archetype was replaced by a minted default").toBe("mentors");
  });

  it("does NOT fold a stream-to-stream edge into a feature-to-feature one", () => {
    // THE CYCLE FACTORY. Collapsing a DAG's nodes into groups manufactures cycles: MEASURED on the
    // real plan, 208 acyclic `dependsOn` edges between streams became 20 cycles between features,
    // which flooded the coordination-hazard pane and hid the list. The claims were invented — the
    // plan never said `cad` depends on `cli-platform`.
    const cross = {
      ...FLEET,
      rawNodes: [
        ...FLEET.rawNodes,
        { id: "cad", slug: "cad", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
      ],
      rawEdges: [{ id: "s-s", from: "glance", to: "cad", kind: "depends-on" as const }],
    };
    const out = withFeatureNodes(cross, [...FEATS, { slug: "cad", name: "CAD" }], [...STRS, { id: "cad", feature: "cad" }]);
    const featIds = new Set([featureNodeId("glance"), featureNodeId("cad")]);
    expect(
      out.rawEdges.filter((e) => featIds.has(e.from) && featIds.has(e.to)),
      "a stream's dependency was folded into a claim about features",
    ).toEqual([]);
  });

  it("carries the repo when its streams agree — the band survives the fold", () => {
    // `withStreamRepos` stamps this per STREAM and the layout bands by it. A feature carrying none
    // lands unbanded, which is how folding the streams away removed the repository separation.
    const withRepos = [
      { id: "glance", feature: "glance", repo: "o/desktop" },
      { id: "fleet-panes", feature: "glance", repo: "o/desktop" },
      { id: "unassigned" },
    ];
    const { nodes } = featureBand(FEATS, withRepos);
    expect(nodes.find((n) => n.slug === "glance")?.repo).toBe("o/desktop");
  });

  it("draws ONE NODE PER REPO when its streams span", () => {
    // A majority pick erases the minority; unbanded says it belongs to no repository at all. The
    // feature really does have work in both, so it appears in both bands. `mobile-tunnel` is the live
    // case. Safe to duplicate because cross-repo coherence is enforced through the components and
    // algorithms graphs, not here.
    const spanning = [
      { id: "glance", feature: "glance", repo: "o/desktop" },
      { id: "fleet-panes", feature: "glance", repo: "o/mobile" },
      { id: "extra", feature: "glance", repo: "o/mobile" },
    ];
    const mine = featureBand(FEATS, spanning).nodes.filter((n) => n.slug === "glance");
    expect(mine.map((n) => n.repo).sort()).toEqual(["o/desktop", "o/mobile"]);
    expect(mine.map((n) => n.id).sort()).toEqual([
      featureNodeId("glance", "o/desktop"),
      featureNodeId("glance", "o/mobile"),
    ]);
    // Each band counts ONLY its own streams — the same number in both would be uncheckable.
    expect(mine.find((n) => n.repo === "o/desktop")?.roleLabel).toBe("1 streams");
    expect(mine.find((n) => n.repo === "o/mobile")?.roleLabel).toBe("2 streams");
  });

  it("keeps the plain id for a single-repo feature — no churn", () => {
    const one = [{ id: "glance", feature: "glance", repo: "o/desktop" }];
    expect(featureBand(FEATS, one).nodes[0].id).toBe(featureNodeId("glance"));
  });

  it("bands a feature with NO streams under the plan's dominant repo", () => {
    // Floating beside the director made `help` and `settings` read as project-level actors rather
    // than the unstaffed features they are. "Probably the main repo" is the smaller error.
    const streams = [
      { id: "a", feature: "other", repo: "o/desktop" },
      { id: "b", feature: "other", repo: "o/desktop" },
      { id: "c", feature: "other", repo: "o/mobile" },
    ];
    const n = featureBand([{ slug: "help", name: "help" }], streams).nodes[0];
    expect(n.repo).toBe("o/desktop");
    expect(n.roleLabel).toBe("0 streams");
  });

  it("folds each stream onto the node for ITS OWN repo", () => {
    // Otherwise every `manages` edge lands on whichever band came first and the other sits unmanaged.
    const spanning = [
      { id: "glance", feature: "glance", repo: "o/desktop" },
      { id: "fleet-panes", feature: "glance", repo: "o/mobile" },
    ];
    const fleet = {
      sample: false,
      rawNodes: [
        { id: "director", slug: "director", kind: "session" as const, role: "service" as const, health: "off" as const, activity: "idle" as const },
        { id: "glance", slug: "glance", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
        { id: "fleet-panes", slug: "fleet-panes", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
      ],
      rawEdges: [
        { id: "d1", from: "director", to: "glance", kind: "coordinates" as const },
        { id: "d2", from: "director", to: "fleet-panes", kind: "coordinates" as const },
      ],
    };
    const out = withFeatureNodes(fleet, FEATS, spanning);
    const managed = out.rawEdges.filter((e) => e.from === "director").map((e) => e.to).sort();
    expect(managed).toEqual([
      featureNodeId("glance", "o/desktop"),
      featureNodeId("glance", "o/mobile"),
    ]);
  });

  it("draws no self-edge when two streams of one feature were connected", () => {
    const linked = {
      ...FLEET,
      rawEdges: [{ id: "s-s", from: "glance", to: "fleet-panes", kind: "coordinates" as const }],
    };
    const out = withFeatureNodes(linked, FEATS, STRS);
    expect(out.rawEdges.filter((e) => e.from === e.to)).toEqual([]);
  });

  it("never leaves a feature AND the streams it covers in one graph", () => {
    // THE INVARIANT, stated directly: two representations of the same work on one canvas is the bug.
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const ids = new Set(out.rawNodes.map((n) => n.id));
    for (const f of FEATS) {
      if (!ids.has(featureNodeId(f.slug))) continue;
      const covered = STRS.filter((s) => streamFeature(s) === f.slug).map((s) => s.id);
      expect(covered.filter((id) => ids.has(id)), `${f.slug} is drawn AND so are its streams`).toEqual([]);
    }
  });

  it("is a no-op with no features, rather than emptying the graph", () => {
    expect(withFeatureNodes(FLEET, [], STRS)).toBe(FLEET);
  });
});

implementations.code:
// The parallel-execution (fleet) plan — the agent streams, director, topology, and
// relationship graph a project's fleet describes, plus the parser that turns the
// planner-written JSON (stored in plan.db, #1805) into a typed {@link FleetPlan}.
//
// Pure (no React / xterm / Tauri) so it can be unit-tested in isolation and shared
// between the planner UI, the store, and the fleet helpers. Split out of the former
// planStages.ts (#1615), which conflated this fleet machinery with the discovery
// topic-file helpers; those now live in stages/planTopics.ts.

import type { AgentFlow } from "@/features/planner/fleet/agentFlow";
import { flowOrUndefined } from "@/features/planner/fleet/agentFlow";
import type { SessionModel } from "@/app/console/lib/models";
import { type DirectorDrive, normalizeDirectorDrive, DEFAULT_DIRECTOR_DRIVE } from "@/features/planner/fleet/directorDrive";
import { type IntegrationStrategy, normalizeStrategy } from "@/features/planner/lib/integrationStrategy";
import {
  type Topology, type RelationshipArtifact, type AgentRelationship,
  type EdgeKind, type Hardness, type Via, type ArtifactKind,
} from "@/features/planner/relationship/relationshipGraph";

const TOPOLOGIES: Topology[] = ["director", "peer", "hybrid"];
const EDGE_KINDS: EdgeKind[] = ["handoff", "blocking", "sequence", "review", "notify", "mutex", "shared"];
const HARDNESSES: Hardness[] = ["blocking", "soft", "notify"];
const ARTIFACT_KINDS: ArtifactKind[] = ["schema", "contract", "types", "tokens", "fixture", "other"];

/** Coerce a raw fleet.json `topology` value (default "hybrid"). */
export function normalizeTopology(raw: unknown): Topology {
  return typeof raw === "string" && (TOPOLOGIES as string[]).includes(raw.trim().toLowerCase())
    ? (raw.trim().toLowerCase() as Topology) : "hybrid";
}

function parseArtifacts(raw: unknown): RelationshipArtifact[] {
  if (!Array.isArray(raw)) return [];
  const out: RelationshipArtifact[] = [];
  for (const a of raw) {
    if (!a || typeof a !== "object") continue;
    const o = a as Record<string, unknown>;
    const id = typeof o.id === "string" ? o.id.trim() : "";
    const producer = typeof o.producer === "string" ? o.producer.trim() : "";
    if (!id || !producer) continue;
    const kind = typeof o.kind === "string" && (ARTIFACT_KINDS as string[]).includes(o.kind) ? o.kind as ArtifactKind : "other";
    out.push({
      id, producer, kind,
      name: typeof o.name === "string" && o.name.trim() ? o.name.trim() : id,
      consumers: Array.isArray(o.consumers) ? o.consumers.filter((c): c is string => typeof c === "string") : [],
      status: o.status === "ready" ? "ready" : o.status === "pending" ? "pending" : undefined,
    });
  }
  return out;
}

function parseEdges(raw: unknown): AgentRelationship[] {
  if (!Array.isArray(raw)) return [];
  const out: AgentRelationship[] = [];
  for (const e of raw) {
    if (!e || typeof e !== "object") continue;
    const o = e as Record<string, unknown>;
    const from = typeof o.from === "string" ? o.from.trim() : "";
    const to = typeof o.to === "string" ? o.to.trim() : "";
    if (!from || !to) continue;
    out.push({
      id: typeof o.id === "string" && o.id.trim() ? o.id.trim() : `${from}>${to}`,
      from, to,
      kind: typeof o.kind === "string" && (EDGE_KINDS as string[]).includes(o.kind) ? o.kind as EdgeKind : "blocking",
      hardness: typeof o.hardness === "string" && (HARDNESSES as string[]).includes(o.hardness) ? o.hardness as Hardness : "blocking",
      via: o.via === "director" ? "director" : ("direct" as Via),
      artifact: typeof o.artifact === "string" && o.artifact.trim() ? o.artifact.trim() : undefined,
      note: typeof o.note === "string" && o.note.trim() ? o.note.trim() : undefined,
    });
  }
  return out;
}

/** The fleet section key. The fleet plan is DB-owned (plan.db, #1018/#1805) — surfaced by the poll
 *  under this stem (NOT a `fleet.json` file), not a rendered plan topic; parsed into the fleet store
 *  and shown in its own Fleet card. See {@link parseFleetFile}. */
export const FLEET_KEY = "fleet";

/**
 * One parallel work stream — a single Claude session with a focused role, a repo,
 * the files/globs it OWNS (its conflict boundary), the issues it owns, the streams
 * it must follow (interface-first), and the kickoff script that seeds it.
 */
export interface AgentStream {
  id: string;
  name: string;
  repo: string;
  /** Path globs this stream owns; no other stream should write inside them. */
  owns: string[];
  /** Issue refs this stream owns (e.g. `#12`). */
  issues: string[];
  /** Ids of streams that must land before this one starts. */
  dependsOn: string[];
  /** Shell commands this stream's session may auto-run without prompting (#1572) — the
   *  toolchain the planner grants it (e.g. `["cargo", "wasm-pack"]`), on top of the
   *  posture-scaled safe baseline. Seeds the generated profile's `commands`; written as
   *  `Bash(<cmd> *)` allow rules at launch. Unset/empty ⇒ baseline + mandatory only. */
  commands?: string[];
  /** Relpath of the kickoff script the fleet launch seeds this session with. */
  prompt?: string;
  /** Id of the AgentProfile this stream's session launches under (#289). */
  profile?: string;
  /** Id of the PERSONA this stream launches as (#2094): a live reference resolved at fleet launch to
   *  the stream's ROLE (overriding the default `worker`), start prompt, skills, and model. Unset ⇒ a
   *  plain worker (the historical default). Lets a fleet mix e.g. a documentor / reviewer stream with
   *  workers — the persona is the behavioral identity, the role it references is the permission floor. */
  persona?: string;
  /** Per-agent execution flow (#297): autonomy + GitHub push policy. Unset ⇒ DEFAULT_FLOW at launch. */
  flow?: AgentFlow;
  /** Per-agent LLM model — the DIRECTOR's level of the model precedence chain, and the nearest one:
   *  a fleet stream's own model > a team placement's (`bsc teams model`) > the persona's default
   *  (`bsc persona model`) > the harness's own default. Set with `bsc plan fleet model <id> <model>`.
   *
   *  Unset ⇒ the next level applies, ending at Claude Code's own default. That is the default and
   *  nothing about a fleet you never touch changes.
   *
   *  {@link SessionModel}, not {@link ModelId}: what the picker OFFERS is a closed set of Claude
   *  tiers, but what a session RUNS is wider — a local (bsc-agent) worker runs an Ollama model by
   *  name, and `qwen3.5:9b` is not a tier. The narrow type never constrained this value anyway: it
   *  arrives from plan.db as untyped JSON, so it only asserted something false. A Claude tier becomes
   *  `claude --model <tier>`; anything else reaches a local session as `$BSC_AGENT_MODEL`. */
  model?: SessionModel;
  /** Which FEATURE this stream is a lane of (`a-feature-owns-many-streams`).
   *
   *  A feature owns MANY streams — studio-code has 89 across 41 — so the relation lives here rather
   *  than on the feature, where it used to be a dead 1:1. ABSENT falls back to the stream's own id,
   *  which is how the 37 streams whose id already IS a feature slug resolve with no backfill.
   *
   *  Two things read it and must agree: the prerequisite block a worker launches with
   *  (`inject_required_algorithms` → this feature's `requires`), and `$BSC_FEATURES`, the records the
   *  worker may WRITE. Both derive from this one value so they cannot disagree about which lane the
   *  worker is in. Authored with `bsc plan fleet stream feature <id> <slug>`. */
  feature?: string;
  /** Per-stream integration-strategy override (#378). Unset ⇒ the fleet default. */
  strategy?: IntegrationStrategy;
  /** GitHub login this stream's issues are assigned to at publish (#847). A worker is an
   *  agent session, not a GitHub user, so this maps the stream to a human/collaborator
   *  login. Unset ⇒ the publishing account (viewer). The `stream:<id>` label remains the
   *  agent-ownership marker; this is the first-class GitHub assignee. */
  assignee?: string;
  /** MCP servers (catalog names) the planner assigned to THIS worker (#1054). At fleet launch
   *  the worker gets these (case-insensitive) on top of any global servers; the planner + director
   *  always see every installed server. Unset/empty ⇒ the worker gets only global servers. */
  mcp?: string[];
  /** Skill task-group ids the planner assigned to THIS stream (#1338, parallel to {@link mcp}).
   *  At fleet launch the group ids are expanded (via the global skills.db) into this worker's
   *  skill set, on top of the project-resolved skills and any groups toggled onto the session.
   *  Unset/empty ⇒ the worker gets only its project-resolved skills. */
  groupIds?: string[];
}

/** Optional async-integrator session that coordinates the fleet from the project root. */
export interface FleetDirector { enabled: boolean; role?: string; drive?: DirectorDrive; }

/** The full parallel-execution plan for a project (persisted in plan.db, #1805). */
export interface FleetPlan {
  /** Optimal number of worker sessions to run concurrently. */
  recommended: number;
  /** Why that many — the planner's justification. */
  reasoning: string;
  streams: AgentStream[];
  director: FleetDirector;
  /** Project-default integration strategy (#378). Unset ⇒ DEFAULT_STRATEGY. */
  strategy?: IntegrationStrategy;
  /**
   * The app-owned SYSTEM SESSIONS this project uses — `designer` · `librarian` · `architect` ·
   * `sound-designer` · `integrator` (the fixed singletons named in `shared/lib/session/systemSessions`).
   * They serve the project's planner and render left of it in Glance.
   *
   * Named "system sessions", NOT "studios": a **Studio** is already the export/import unit for the whole
   * app library (studio snapshots), so overloading the word would make two unrelated things share a name
   * in the same codebase.
   *
   * DECLARED, not derived. The obvious inference — a `ui.kit` pairing implies a designer, integrations
   * imply an integrator, a feature's `requires` implies a librarian — reads EMPTY on the live studio-code
   * plan (no ui pairing, no integrations, 0 of 40 features carrying `requires`), so it would show zero
   * sessions on the one project that demonstrably uses all of them. Absent means "not declared", never
   * "not used": an empty list renders no session nodes rather than guessing.
   */
  systemSessions?: string[];
  /** Coordination topology (#…): director-orchestrated, peer mesh, or hybrid (per-edge). */
  topology?: Topology;
  /** Produced contracts/schemas one stream hands to others. */
  artifacts?: RelationshipArtifact[];
  /** Typed relationship edges between streams (beyond plain `dependsOn`). */
  edges?: AgentRelationship[];
}

/** An empty fleet — the default before the planner has designed one. */
export function emptyFleet(): FleetPlan {
  return { recommended: 0, reasoning: "", streams: [], director: { enabled: false, drive: DEFAULT_DIRECTOR_DRIVE } };
}

/**
 * Enrich each stream's `issues` from the plan.db issues that name it as their owning `stream` (#2615),
 * when the stream itself carries none. `AgentStream.issues` and `PlanIssue.stream` are meant to MIRROR
 * each other, but a stream can reach launch with an empty `issues[]` — so a worker gets a placeholder
 * kickoff instead of its real work. Deriving from the issues at launch means a worker always launches
 * with its concrete task list. A stream that already lists its issues is untouched (its authored order
 * wins). Pure + generic over the issue shape (`{ ref, stream }`) so it's unit-testable.
 */
export function withDerivedStreamIssues<T extends { id: string; issues: string[] }>(
  streams: T[],
  issues: ReadonlyArray<{ ref?: string; stream?: string }>,
): T[] {
  const byStream = new Map<string, string[]>();
  for (const iss of issues) {
    if (!iss.stream || !iss.ref) continue;
    const arr = byStream.get(iss.stream);
    if (arr) arr.push(iss.ref); else byStream.set(iss.stream, [iss.ref]);
  }
  return streams.map((s) => (s.issues.length > 0 ? s : { ...s, issues: byStream.get(s.id) ?? [] }));
}

/** Coerce a JSON value into a string[]. Accepts an array (strings kept, others
 *  stringified) or a single comma-separated string; anything else → []. */
function toStringArray(v: unknown): string[] {
  if (Array.isArray(v)) {
    return v.map(x => (typeof x === "string" ? x : String(x))).map(s => s.trim()).filter(Boolean);
  }
  if (typeof v === "string") {
    return v.split(",").map(s => s.trim()).filter(Boolean);
  }
  return [];
}

/** Coerce a JSON value into a non-negative integer; non-numeric → 0. */
function coerceNum(v: unknown): number {
  const n = typeof v === "number" ? v : typeof v === "string" ? Number(v) : NaN;
  return Number.isFinite(n) && n >= 0 ? Math.floor(n) : 0;
}

/**
 * Parse the FleetPlan JSON (the planner writes it to plan.db, #1805; surfaced by the poll
 * as stem {@link FLEET_KEY}) into a {@link FleetPlan}. Tolerant of partial/malformed
 * input: returns `null` only when the text is blank or not a JSON object; otherwise
 * fills sensible defaults. A stream missing an `id` (genuinely unkeyable) is dropped; a repo-less
 * stream DEFAULTS to the project's sole repo (`repos`, when there's exactly one) and otherwise stays
 * VISIBLE with an empty `repo` so it isn't silently hidden from the plan (#2611). `dependsOn`
 * accepts either `dependsOn` or `depends_on`.
 */
export function parseFleetFile(raw: string, repos: string[] = []): FleetPlan | null {
  if (!raw || !raw.trim()) return null;
  let obj: unknown;
  try { obj = JSON.parse(raw); } catch { return null; }
  if (!obj || typeof obj !== "object" || Array.isArray(obj)) return null;
  const o = obj as Record<string, unknown>;

  const streams: AgentStream[] = [];
  const rawStreams = Array.isArray(o.streams) ? o.streams : [];
  for (const s of rawStreams) {
    if (!s || typeof s !== "object") continue;
    const so = s as Record<string, unknown>;
    const id   = typeof so.id === "string" ? so.id.trim() : "";
    if (!id) continue;  // no id ⇒ genuinely unkeyable, drop
    // #2611: default a repo-less stream to the project's SOLE repo (the common single-repo case). If the
    // repo still can't be resolved (multi-repo / unassigned), KEEP the stream with an empty repo so it
    // stays VISIBLE in the planner graph flagged as needing a repo — silently dropping it hid streams
    // from the plan AND from launch. The launch path (usePlanPublish) skips a repo-less stream so it
    // never aborts the fleet or spawns a broken worktree.
    let repo = typeof so.repo === "string" ? so.repo.trim() : "";
    if (!repo && repos.length === 1) repo = repos[0];
    const prompt = typeof so.prompt === "string" && so.prompt.trim() ? so.prompt.trim() : undefined;
    // MCP servers (catalog names) the planner assigned to this worker (#1054); undefined when none
    // so the field round-trips cleanly. Carried through to fleetStartProject's per-worker resolution.
    const mcp = toStringArray(so.mcp);
    // Per-agent flow (#297) arrives in EITHER shape (#1804): NESTED as `so.flow`
    // ({autonomy,push,trigger,gate} — the canonical `bsc-plan fleet set` / fleet.json
    // form, matching the store model) OR FLAT as top-level `so.autonomy`/`so.push`/
    // `so.trigger`/`so.gate` (what the `<agent_assign>` tag attrs and legacy flat
    // fleet.json emit). Prefer a named nested object; else assemble from the flat
    // fields; else leave undefined so genuinely-unset streams still get DEFAULT_FLOW
    // at launch (we must NOT silently materialize a flow here).
    const nestedFlow = so.flow && typeof so.flow === "object" && !Array.isArray(so.flow)
      ? (so.flow as Record<string, unknown>) : null;
    const flow = flowOrUndefined(nestedFlow)
      ?? flowOrUndefined({ autonomy: so.autonomy, push: so.push, trigger: so.trigger, gate: so.gate });
    streams.push({
      id,
      name: typeof so.name === "string" && so.name.trim() ? so.name.trim() : id,
      repo,
      owns:      toStringArray(so.owns),
      issues:    toStringArray(so.issues),
      dependsOn: toStringArray(so.dependsOn ?? so.depends_on),
      commands:  ((cs) => cs.length ? cs : undefined)(toStringArray(so.commands)),
      prompt,
      mcp: mcp.length ? mcp : undefined,
      // Skill task-group ids (#1338), the same shape as `mcp` beside it — and dropped for the same
      // reason `feature` was: declared, expected downstream, never decoded. Rust expands these into
      // the worker's skill set at fleet launch (`bsc-resolve`: `s["groupIds"]` -> `group_skill_ids`),
      // so losing them here silently launches a worker without the skills its stream was assigned.
      groupIds: ((gs) => (gs.length ? gs : undefined))(toStringArray(so.groupIds ?? so.group_ids)),
      profile: typeof so.profile === "string" && so.profile.trim() ? so.profile.trim() : undefined,
      // Persona reference (#2094) — the stream's behavioral identity, resolved to role/prompt/skills/
      // model at fleet launch. Kept verbatim (an id); an unknown id just resolves to no persona.
      persona: typeof so.persona === "string" && so.persona.trim() ? so.persona.trim() : undefined,
      flow,
      // Per-agent model (`bsc plan fleet model <id> <model>`) — round-trips through plan.db verbatim.
      // #173: this used to validate against MODEL_IDS and drop anything else, which silently discarded
      // every LOCAL model a director assigned (`qwen3.5:9b` is not a Claude tier, and never will be) —
      // exactly the value {@link AgentStream.model}'s own doc comment says this field must carry. Any
      // non-empty string round-trips now; only whitespace-only/absent still clears to undefined.
      model: typeof so.model === "string" && so.model.trim() ? (so.model.trim() as SessionModel) : undefined,
      // WHICH FEATURE this stream is a lane of (`a-feature-owns-many-streams`). Declared on
      // {@link AgentStream} and never read here, so every stream arrived `feature: undefined` — the
      // plan as it looked before any feature was assigned. The band appeared correct only because it
      // reads a SECOND poll that goes through no parser; everything reading the fleet saw the old one.
      //
      // THIRD instance of this exact shape on this function — see `model` two fields down (#173) and
      // `requires` on the feature side. A field declared in the type, written by the CLI, present in
      // the store, and dropped by the decoder. `everyDeclaredFieldIsCarried` derives the field list
      // from the interface now, because hand-checking is what failed all three times.
      feature: typeof so.feature === "string" && so.feature.trim() ? so.feature.trim() : undefined,
      strategy: normalizeStrategy(so.strategy),
      assignee: typeof so.assignee === "string" && so.assignee.trim() ? so.assignee.trim() : undefined,
    });
  }

  const dir = (o.director && typeof o.director === "object" && !Array.isArray(o.director))
    ? (o.director as Record<string, unknown>) : {};
  const director: FleetDirector = {
    enabled: dir.enabled === true || dir.enabled === "true",
    role: typeof dir.role === "string" && dir.role.trim() ? dir.role.trim() : undefined,
    drive: normalizeDirectorDrive(dir.drive),
  };

  return {
    recommended: coerceNum(o.recommended),
    reasoning: typeof o.reasoning === "string" ? o.reasoning : "",
    streams,
    director,
    strategy: normalizeStrategy(o.strategy),
    // Carried through explicitly: this parser builds its result field-by-field, so a field that is not
    // named here is silently dropped — which is exactly what made a declared list unable to render no
    // matter what plan.db held. Filtered to strings and de-duplicated at the boundary; the graph drops
    // ids it does not know, and doing the cheap half here keeps the stored value clean.
    systemSessions: Array.isArray(o.systemSessions)
      ? [...new Set(o.systemSessions.filter((s): s is string => typeof s === "string" && !!s.trim()).map((s) => s.trim()))]
      : undefined,
    topology: o.topology !== undefined ? normalizeTopology(o.topology) : undefined,
    artifacts: parseArtifacts(o.artifacts),
    edges: parseEdges(o.edges),
  };
}

