import { describe, it, expect } from "vitest";
import { fromMajor, money, toMajor, isZero, type Money } from "@/features/finance/lib/money";
import { payoff, payoffOrder, compareStrategies, periodicRate, Unpayable, type Debt } from "@/features/finance/lib/payoff";

const usd = (major: number): Money => fromMajor(major, "USD");
const debt = (name: string, balance: number, apr: number, minimum: number): Debt => ({
  name, balance: usd(balance), apr, minimum: usd(minimum),
});

// A shape that actually occurs: a small cheap loan, a big expensive card, a middling one.
const DEBTS: Debt[] = [
  debt("card-A", 2500, 0.2299, 50),
  debt("loan-B", 800, 0.0699, 40),
  debt("card-C", 5000, 0.1899, 100),
];

describe("payoffOrder", () => {
  it("avalanche takes the highest RATE first; snowball the smallest BALANCE", () => {
    expect(payoffOrder(DEBTS, "avalanche").map((d) => d.name)).toEqual(["card-A", "card-C", "loan-B"]);
    expect(payoffOrder(DEBTS, "snowball").map((d) => d.name)).toEqual(["loan-B", "card-A", "card-C"]);
  });

  it("breaks ties deterministically, so two runs agree", () => {
    // Without this the comparison below is not reproducible — and a schedule that changes between
    // runs of the same input is not something anyone can act on.
    const tied = [debt("b", 1000, 0.1, 10), debt("a", 1000, 0.1, 10)];
    expect(payoffOrder(tied, "snowball").map((d) => d.name)).toEqual(["a", "b"]);
    expect(payoffOrder(tied, "avalanche").map((d) => d.name)).toEqual(["a", "b"]);
  });
});

describe("payoff — the schedule", () => {
  it("clears every balance and reports the order they cleared in", () => {
    const p = payoff(DEBTS, usd(400), "avalanche");
    const last = p.periods[p.periods.length - 1];
    expect(last.payments.every((x) => isZero(x.balance))).toBe(true);
    expect(p.order).toHaveLength(3);
    expect(p.months).toBe(p.periods.length);
  });

  it("ROLLS a cleared debt's payment into the next target", () => {
    // This is what makes either strategy accelerate. Without the roll, the last debt would take as
    // long as if it were alone, and the whole method would be pointless.
    const p = payoff(DEBTS, usd(400), "snowball");
    const firstCleared = p.periods.find((x) => x.clearedThisPeriod.length)!;
    const after = p.periods[firstCleared.period]; // the period AFTER one cleared
    const target = p.order[1];
    const before = firstCleared.payments.find((x) => x.name === target)!;
    const now = after.payments.find((x) => x.name === target)!;
    expect(now.principal.minor).toBeGreaterThan(before.principal.minor);
  });

  it("never pays more than clears a debt", () => {
    // Overpaying would show as a negative balance, which is not a debt — it is a modelling error that
    // would then be summed into the totals.
    const p = payoff(DEBTS, usd(900), "avalanche");
    for (const period of p.periods) {
      for (const x of period.payments) expect(x.balance.minor).toBeGreaterThanOrEqual(0);
    }
  });

  it("totals reconcile: everything paid is principal plus interest", () => {
    const p = payoff(DEBTS, usd(400), "avalanche");
    const principal = p.periods.flatMap((x) => x.payments).reduce((a, x) => a + x.principal.minor, 0);
    const interest = p.periods.flatMap((x) => x.payments).reduce((a, x) => a + x.interest.minor, 0);
    // Every cent paid went somewhere, and the starting balances were exactly retired.
    expect(principal).toBe(DEBTS.reduce((a, d) => a + d.balance.minor, 0));
    expect(interest).toBe(p.totalInterest.minor);
    expect(p.totalPaid.minor).toBe(principal + interest);
  });
});

describe("payoff — refusals", () => {
  it("REFUSES a budget below the minimums rather than returning a fantasy", () => {
    // The shortfall is the finding. A schedule that quietly ignored it would look like a plan.
    expect(() => payoff(DEBTS, usd(100), "avalanche")).toThrow(Unpayable);
  });

  it("REFUSES when interest outruns the payment, rather than looping to a horizon", () => {
    // Minimums are covered, but they are all interest — the balance never falls. Returning a
    // truncated schedule would show a payoff that does not exist.
    const stuck = [debt("payday", 1000, 3.0, 10)];
    expect(() => payoff(stuck, usd(10), "avalanche", { maxPeriods: 60 })).toThrow(Unpayable);
  });

  it("needs at least one debt", () => {
    expect(() => payoff([], usd(100), "avalanche")).toThrow(Unpayable);
  });
});

describe("compareStrategies — the trade, as a number", () => {
  it("avalanche is NEVER beaten on interest or on months", () => {
    // The mathematical claim the module rests on. If this fails, the advice it supports is wrong.
    const c = compareStrategies(DEBTS, usd(400));
    expect(c.extraInterest.minor).toBeGreaterThanOrEqual(0);
    expect(c.extraMonths).toBeGreaterThanOrEqual(0);
  });

  it("holds across many budgets, not just the one that was convenient", () => {
    for (const budget of [200, 250, 300, 400, 600, 1000]) {
      const c = compareStrategies(DEBTS, usd(budget));
      expect(c.extraInterest.minor, `budget ${budget}`).toBeGreaterThanOrEqual(0);
      expect(c.extraMonths, `budget ${budget}`).toBeGreaterThanOrEqual(0);
    }
  });

  it("names what snowball BUYS — the first debt gone sooner", () => {
    // The cost is real and so is the benefit. Reporting only the cost would be advocacy, not a tool.
    const c = compareStrategies(DEBTS, usd(400));
    expect(c.snowball.order[0]).toBe("loan-B");
    expect(c.avalanche.order[0]).toBe("card-A");
    expect(c.firstClearedSooner).toBeGreaterThan(0);
  });

  it("agrees with itself when there is only one debt — no strategy to choose", () => {
    const one = [debt("only", 1000, 0.1, 50)];
    const c = compareStrategies(one, usd(200));
    expect(c.extraInterest.minor).toBe(0);
    expect(c.extraMonths).toBe(0);
  });
});

describe("periodicRate", () => {
  it("divides the nominal annual rate by the periods in a year", () => {
    expect(periodicRate(0.12)).toBeCloseTo(0.01, 12);
    expect(periodicRate(0.12, 4)).toBeCloseTo(0.03, 12);
  });
});

implementations.code:
//! The `bsc fin` verbs.
//!
//! READ-ONLY SO FAR, and deliberately: `parse` proves the ingest against a file and prints what it
//! found without writing anything. A store lands next, and it lands after the parse is trustworthy —
//! a store filled by a parser nobody has checked is a confident wrong answer that persists.
//!
//! THE RENDERING IS SPLIT OUT FROM `run` ON PURPOSE. `run` does file IO and calls `println!`, and
//! neither can be asserted on; a verb whose whole job is REPORTING therefore had no test at all,
//! which is precisely backwards for the one surface a person reads a balance off. `render_text` and
//! `render_json` are pure — a `Parsed` in, a string in hand — so what this prints is a fact a test
//! can hold rather than something that has to be run and eyeballed.
use crate::account::{self, Account};
use crate::inbox;
use crate::session::{self, FetchVerdict, SessionState};
use crate::statement::{self, Parsed};

pub const COMMANDS: &[bsc_cli_util::CmdDoc] = &[
    bsc_cli_util::CmdDoc {
        name: "parse",
        summary: "read a statement export and report what it found — and every row it could NOT read",
        usage: "bsc fin parse <file.csv> [--json]",
    },
    bsc_cli_util::CmdDoc {
        name: "start",
        summary: "what to download, from where, and where to put it — the one command between nothing and a full picture",
        usage: "bsc fin start",
    },
    bsc_cli_util::CmdDoc {
        name: "inbox",
        summary: "what statement exports are waiting, and with --ingest read them and claim them so none is read twice",
        usage: "bsc fin inbox [--ingest] [--json]",
    },
    bsc_cli_util::CmdDoc {
        name: "account",
        summary: "what each account IS — and what is missing, with the capability each gap blocks",
        usage: "bsc fin account [list|set|remove <id>] [--json]",
    },
    bsc_cli_util::CmdDoc {
        name: "session",
        summary: "whether each institution has a session worth reusing — and `<id> --established` after you have signed in by hand",
        usage: "bsc fin session [<institution> --established] [--json]",
    },
];

/// What a human reads.
///
/// EVERY unread row is named with its line number. A count alone would be the wrong shape of
/// honesty: "3 rows not read" tells you the total is wrong without telling you where to look, and a
/// number that is wrong by an unknown amount is not usable for anything.
pub fn render_text(p: &Parsed) -> String {
    let mut out = String::new();
    out.push_str(&format!("{} · {}\n", p.institution.name(), p.profile));
    out.push_str(&format!("  {} transaction(s)\n", p.txns.len()));
    let net: i64 = p.txns.iter().map(|t| t.minor).sum();
    out.push_str(&format!("  net {}\n", crate::money::format_minor(net)));
    if p.rejected.is_empty() {
        out.push_str("  every row read\n");
    } else {
        out.push_str(&format!("  {} row(s) NOT read:\n", p.rejected.len()));
        for r in &p.rejected {
            out.push_str(&format!("    line {}: {}\n", r.line, r.reason));
        }
    }
    out
}

/// What another program reads. Carries the rejections too — a consumer that only saw `transactions`
/// would compute a total off a file it did not know was short.
pub fn render_json(p: &Parsed) -> serde_json::Value {
    serde_json::json!({
        "institution": p.institution.name(),
        "profile": p.profile,
        "transactions": p.txns.iter().map(|t| serde_json::json!({
            "date": t.date,
            "description": t.description,
            "minor": t.minor,
        })).collect::<Vec<_>>(),
        "rejected": p.rejected.iter().map(|r| serde_json::json!({
            "line": r.line,
            "reason": r.reason,
        })).collect::<Vec<_>>(),
    })
}


/// The inbox report, and what to do about each file.
///
/// SEPARATE FROM THE IO for the same reason `render_text` is: what this says is the whole product of
/// the verb, and a verb whose output nothing can assert on has no test.
pub fn render_inbox(files: &[inbox::InboxFile]) -> String {
    inbox::render(files)
}

/// Whether each connection could be fetched unattended right now.
///
/// `NeedsPerson` and `Blocked` are rendered DIFFERENTLY on purpose. One is the design working as
/// intended — you sign in, everything after is unattended — and the other is something to go and look
/// at. Printing both as "failed" would make the normal case alarming and hide the real one.
pub fn render_sessions(states: &[SessionState], connectors: &[&str], as_of: &str) -> String {
    let mut out = String::new();
    for id in connectors {
        let state = session::state_for(states, id);
        let verdict = session::may_fetch_unattended(&state, as_of, session::DEFAULT_TTL_HOURS);
        let (tag, reason) = match &verdict {
            FetchVerdict::Go => ("ready", verdict.reason().to_string()),
            FetchVerdict::NeedsPerson(r) => ("your turn", r.clone()),
            FetchVerdict::Blocked(r) => ("BLOCKED", r.clone()),
        };
        out.push_str(&format!("  {id} · {tag}\n      {reason}\n"));
    }
    out
}

fn store_path() -> Result<std::path::PathBuf, String> {
    let base = bsc_util::bsc_base_dir().ok_or_else(|| "no base dir ($HOME unset)".to_string())?;
    Ok(base.join("fin").join("sessions.json"))
}

fn load_states() -> Vec<SessionState> {
    let Ok(path) = store_path() else { return Vec::new() };
    let Ok(text) = std::fs::read_to_string(&path) else { return Vec::new() };
    serde_json::from_str::<serde_json::Value>(&text).map(|v| session::from_json(&v)).unwrap_or_default()
}

fn save_states(states: &[SessionState]) -> Result<(), String> {
    let path = store_path()?;
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
    }
    std::fs::write(&path, serde_json::to_string_pretty(&session::to_json(states)).unwrap_or_default())
        .map_err(|e| format!("cannot write {}: {e}", path.display()))
}


/// The on-ramp.
///
/// EVERY FIGURE THIS SYSTEM CAN PRODUCE IS WAITING ON A FILE. Position, runway, what to pay first,
/// which call to make — all of it is arithmetic over transactions, and none of it exists until a
/// statement lands. So the highest-value thing the surface can do, before any analysis, is remove
/// every excuse between a person and that download: where the button is, what range to pick, what to
/// call the file, and what to run next.
///
/// The DATE RANGE guidance is not padding. Three whole months is the floor for an income projection,
/// and an annual charge cannot be detected inside twelve — so "as far back as it lets you" is a
/// materially better answer than the default range every one of these sites offers.
pub fn render_start(inbox: &std::path::Path) -> String {
    let mut out = String::new();
    out.push_str("Nothing here works until a statement lands. This is the whole setup.\n\n");
    out.push_str(&format!("  1. the inbox is  {}\n\n", inbox.display()));
    out.push_str("  2. download each account's CSV and drop it in there:\n\n");
    for i in [
        statement::Institution::Discover,
        statement::Institution::CapitalOne,
        statement::Institution::BankOfAmerica,
        statement::Institution::Chase,
    ] {
        out.push_str(&format!("       {:<16} {}\n", i.name(), i.export_path()));
        out.push_str(&format!("       {:<16} name it  {}-<anything>.csv\n\n", "", i.name()));
    }
    // The single highest-leverage instruction on the page.
    out.push_str("  3. pick the LONGEST date range offered — as far back as it lets you.\n");
    out.push_str("     three whole months is the FLOOR for an income projection, and a yearly\n");
    out.push_str("     charge cannot be found inside twelve. the default range on every one of\n");
    out.push_str("     these sites is shorter than what you want.\n\n");
    out.push_str("  4. then run:  bsc fin inbox --ingest\n\n");
    out.push_str("A file whose name does not start with one of those four is left alone rather than\n");
    out.push_str("guessed at — the wrong profile reads a date as an amount and says so confidently.\n");
    out
}


/// Every verb that exists, as prose, from the one place they are declared.
pub fn verb_list(prog: &str) -> String {
    let names: Vec<String> = COMMANDS.iter().map(|c| format!("`{prog} {}`", c.name)).collect();
    match names.split_last() {
        Some((last, rest)) if !rest.is_empty() => format!("{} or {last}", rest.join(", ")),
        Some((last, _)) => last.clone(),
        None => "nothing — this surface has no verbs".to_string(),
    }
}

fn accounts_path() -> Result<std::path::PathBuf, String> {
    let base = bsc_util::bsc_base_dir().ok_or_else(|| "no base dir ($HOME unset)".to_string())?;
    Ok(base.join("fin").join("accounts.json"))
}

fn load_accounts() -> (Vec<Account>, Vec<String>) {
    let Ok(path) = accounts_path() else { return (Vec::new(), Vec::new()) };
    let Ok(text) = std::fs::read_to_string(&path) else { return (Vec::new(), Vec::new()) };
    match serde_json::from_str::<serde_json::Value>(&text) {
        Ok(v) => account::all_from_json(&v),
        Err(e) => (Vec::new(), vec![format!("{}: {e}", path.display())]),
    }
}

fn save_accounts(accounts: &[Account]) -> Result<(), String> {
    let path = accounts_path()?;
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
    }
    std::fs::write(&path, serde_json::to_string_pretty(&account::all_to_json(accounts)).unwrap_or_default())
        .map_err(|e| format!("cannot write {}: {e}", path.display()))
}

/// The registry AND its gaps, as one value — because a caller that got the accounts without knowing
/// what is missing from them would compute a confident number over a partial picture.
pub fn accounts_json(accounts: &[Account], rejected: &[String]) -> serde_json::Value {
    let (known, possible) = account::completeness(accounts);
    serde_json::json!({
        "accounts": account::all_to_json(accounts),
        "gaps": account::gaps(accounts).iter().map(|g| serde_json::json!({
            "account": g.account, "field": g.field, "blocks": g.blocks,
        })).collect::<Vec<_>>(),
        "known": known,
        "knowable": possible,
        "unreadable": rejected,
    })
}

pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let json = args.iter().any(|a| a == "--json");
    let positional: Vec<&String> = args.iter().filter(|a| !a.starts_with("--")).collect();
    match positional.first().map(|s| s.as_str()) {
        Some("parse") => {
            let path = positional
                .get(1)
                .ok_or_else(|| format!("usage: {prog} parse <file.csv> [--json]"))?;
            let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
            let p = statement::parse_csv(&text)?;
            if json {
                println!("{}", render_json(&p));
            } else {
                print!("{}", render_text(&p));
            }
            Ok(())
        }
        Some("start") => {
            let dir = inbox::inbox_dir().ok_or_else(|| "no base dir ($HOME unset)".to_string())?;
            std::fs::create_dir_all(&dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
            print!("{}", render_start(&dir));
            let waiting = inbox::scan(&dir)?;
            if !waiting.is_empty() {
                println!("Already waiting:");
                print!("{}", render_inbox(&waiting));
            }
            Ok(())
        }
        Some("inbox") => {
            let dir = inbox::inbox_dir().ok_or_else(|| "no base dir ($HOME unset)".to_string())?;
            let files = inbox::scan(&dir)?;
            if !args.iter().any(|a| a == "--ingest") {
                print!("{}", render_inbox(&files));
                if files.iter().any(|f| f.readable()) {
                    println!("  run `{prog} inbox --ingest` to read and claim them");
                }
                return Ok(());
            }
            let processed = inbox::processed_dir().ok_or_else(|| "no base dir ($HOME unset)".to_string())?;
            let at = session::now_iso();
            for f in &files {
                if !f.readable() {
                    println!("{} · SKIPPED, cannot tell which institution it is from", f.name);
                    continue;
                }
                let text = std::fs::read_to_string(&f.path).map_err(|e| format!("cannot read {}: {e}", f.name))?;
                match statement::parse_csv(&text) {
                    Ok(p) => {
                        print!("{}", render_text(&p));
                        // CLAIMED ONLY AFTER IT READ. A file moved out of the inbox on a parse that
                        // failed is a statement nobody will notice is missing.
                        let dest = inbox::claim(&f.path, &processed, &at)?;
                        println!("  claimed → {}", dest.display());
                    }
                    Err(e) => println!("{} · NOT READ: {e}\n  left in the inbox", f.name),
                }
            }
            Ok(())
        }
        Some("account") => {
            let (mut accounts, rejected) = load_accounts();
            match positional.get(1).map(|s| s.as_str()) {
                Some("set") => {
                    let mut raw = String::new();
                    std::io::Read::read_to_string(&mut std::io::stdin(), &mut raw)
                        .map_err(|e| format!("cannot read stdin: {e}"))?;
                    let v: serde_json::Value = serde_json::from_str(&raw).map_err(|e| format!("not JSON: {e}"))?;
                    let items = if v.is_array() { v.as_array().unwrap().clone() } else { vec![v] };
                    for item in &items {
                        account::upsert(&mut accounts, account::from_json(item)?);
                    }
                    save_accounts(&accounts)?;
                    println!("{} account(s) stored; {} known", items.len(), accounts.len());
                    Ok(())
                }
                Some("remove") => {
                    let id = positional.get(2).ok_or_else(|| format!("usage: {prog} account remove <id>"))?;
                    let before = accounts.len();
                    accounts.retain(|a| &a.id != *id);
                    if accounts.len() == before {
                        return Err(format!("{prog}: no account `{id}`"));
                    }
                    save_accounts(&accounts)?;
                    println!("removed {id}");
                    Ok(())
                }
                Some(other) if other != "list" => Err(format!("{prog}: unknown account command `{other}` — try list, set or remove")),
                _ => {
                    if json {
                        println!("{}", accounts_json(&accounts, &rejected));
                    } else {
                        print!("{}", account::render(&accounts));
                        for r in &rejected {
                            println!("  UNREADABLE ROW: {r}");
                        }
                    }
                    Ok(())
                }
            }
        }
        Some("session") => {
            let mut states = load_states();
            let connectors: Vec<&str> = inbox::KNOWN.to_vec();
            match positional.get(1).map(|s| s.as_str()) {
                Some(id) if args.iter().any(|a| a == "--established") => {
                    if !connectors.contains(&id) {
                        return Err(format!("{prog}: `{id}` is not a known institution — try one of: {}", connectors.join(", ")));
                    }
                    let mut state = session::state_for(&states, id);
                    session::established(&mut state, &session::now_iso());
                    session::upsert(&mut states, state);
                    save_states(&states)?;
                    println!("{id} · session recorded — unattended fetches may reuse it until it ages out");
                    Ok(())
                }
                Some(id) => Err(format!(
                    "usage: {prog} session {id} --established  # after signing in by hand"
                )),
                None => {
                    print!("{}", render_sessions(&states, &connectors, &session::now_iso()));
                    Ok(())
                }
            }
        }
        // The offer is BUILT FROM `COMMANDS`, not typed out beside it. A hand-written list is a
        // second place to remember, and the test over `COMMANDS` caught it going stale the first
        // time a verb was added — so the fix is to remove the second place rather than update it.
        Some(other) => Err(format!("{prog}: unknown command `{other}` — try {}", verb_list(prog))),
        None => Err(format!("usage: {prog} <start|parse|inbox|account|session>")),
    }
}

